insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36177, 'gorr-the-god-butcher', null, null, 'All-Black', 'Normal Attack', 'Unleash up to a 4-strike rapid combo with All-Black the Necrosword', '[{"label":"Key","value":"Left Click"},{"label":"Type","value":"Melee"},{"label":"Damage","value":"40 for the 1st/3rd hits, 60 for the 2nd/4th hits"},{"label":"Attack Interval","value":"0.4s for the 1st/3rd hits, 0.6s for the 2nd/4th hits"},{"label":"Maximum Distance","value":"7m"}]'::jsonb, 0),
  (36178, 'gorr-the-god-butcher', null, null, 'Necro-Power', 'Ability', 'Charge and launch a symbiote mass forward. Hitting an enemy Slows and teleports nearby Black Berserkers to them, or spawns a new one. Arriving Berserkers unleash a two-strike melee attack to Launch Up nearby enemies before reverting to ranged mode', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"6s"},{"label":"Damage","value":"30"},{"label":"Berserker Summon Range","value":"12m radius"},{"label":"Black Berserker Melee Damage","value":"20 per hit, 2 hits"},{"label":"Slow Effect","value":"15% for 2s"}]'::jsonb, 1),
  (36179, 'gorr-the-god-butcher', null, null, 'Shadow Harvest', 'Ability', 'Warp to a selected Black Berserker, sacrificing it for Bonus Health equal to half its Health and triggering a symbiote explosion. Briefly unlocks Shadow Scythe: fire a piercing shockwave forward. All-Black then becomes a scythe for a set duration or 4 slashes', '[{"label":"Key","value":"F"},{"label":"Cooldown","value":"3s"},{"label":"Maximum Select Distance","value":"22m"},{"label":"Bonus Health","value":"50% of the Black Berserker''s remaining Health, up to 50; shares the Bonus Health cap with Berserker Swarm"},{"label":"Explosion Damage","value":"5 + 5% Max Health"},{"label":"Explosion Range","value":"5m radius"},{"label":"Shadow Scythe Damage","value":"50 + 2% Max Health"},{"label":"Shadow Scythe Attack Interval","value":"0.6s"},{"label":"Shadow Scythe Maximum Distance","value":"8m"},{"label":"Shockwave Damage","value":"55"}]'::jsonb, 2),
  (36180, 'gorr-the-god-butcher', null, null, 'Black Berserker', 'Ability', 'Lob a symbiote mass that spawns a Black Berserker on landing to immediately shoot the nearest enemy. If summoned beside an enemy via Necro-Power, it unleashes a two-strike melee attack instead', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"2 charges, 10s recharge each."},{"label":"Summon Duration","value":"6s"},{"label":"Summon Maximum Health","value":"150"},{"label":"Summon Damage","value":"7.5 per hit"},{"label":"Summon Attack Interval","value":"0.7s"},{"label":"Summon Attack Range","value":"30m radius"},{"label":"Black Berserker Melee Damage","value":"20 per hit, 2 hits"}]'::jsonb, 3),
  (36181, 'gorr-the-god-butcher', null, null, 'Living Abyss', 'Ability', 'Surge forward as an Invincible symbiote mass, leaving a Black Berserker behind and driving all active Berserkers into a Frenzied State. Upon landing, manifest a Necroverse that continuously damages trapped enemies, converting them into Bonus Health', '[{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"13s"},{"label":"Ability Duration","value":"1.5s"},{"label":"Movement Boost","value":"10m/s"},{"label":"Attack Speed Boost To Frenzied Berserkers","value":"40%"},{"label":"Necroverse Damage","value":"30/s"},{"label":"Necroverse Range","value":"10m radius"},{"label":"Damage/Health Conversion","value":"100%, up to 50"}]'::jsonb, 4),
  (36182, 'gorr-the-god-butcher', null, null, 'Berserker Swarm', 'Passive', 'Black Berserker damage grants Gorr Bonus Health. Defeating an enemy instantly spawns a Black Berserker at their location', '[{"label":"Key","value":"Passive"},{"label":"Summon Damage/Health Conversion","value":"100%, up to 50; shares the Bonus Health cap with Shadow Harvest"}]'::jsonb, 5),
  (36183, 'gorr-the-god-butcher', null, null, 'Twilight of the Gods', 'Ultimate', 'Unseal All-Black''s true power, transforming it into the Annihilablade. Upon activation, an expanding Necroverse is formed, instantly spawning a Black Berserker next to all enemies caught inside. While active, every slash of the Annihilablade deals devastating damage. The Necroverse moves with Gorr; Berserkers within the field will not expire and remain locked in a perpetual Frenzied State', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"3400"},{"label":"Maximum Duration","value":"10"},{"label":"Berserker Spawn Range","value":"10m radius"},{"label":"Necroverse Range","value":"30m radius"},{"label":"Annihilablade Damage","value":"65 + 10% Max Health"},{"label":"Annihilablade Attack Interval","value":"0.6s"},{"label":"Annihilablade Maximum Distance","value":"10m"},{"label":"Damage Falloff","value":"Falloff begins at 8m, decreasing to 80% at 10m"}]'::jsonb, 6),
  (36184, 'gorr-the-god-butcher', null, null, 'Ragnarök', 'Team-Up Ability', 'Base Effect: Gain a new ability to morph the All-Black into a scythe and execute a sweeping strike, damaging and briefly Grounding nearby enemies. The weapon stays in scythe form for a short duration. Enhanced Effect: When teaming up with Hela, the scythe''s attack range is expanded. Each hit scatters symbiote fragments, granting Bonus Health to Gorr and nearby allies', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Grounded Duration","value":"1s"},{"label":"Sweeping Range","value":"5m radius"},{"label":"Sweeping Damage","value":"45"},{"label":"Bonus Health","value":"10 per use"},{"label":"Shadow Scythe Maximum Distance Boost","value":"2m"}]'::jsonb, 7),
  (36185, 'gorr-the-god-butcher', null, null, 'Hive Mind', 'Team-Up Ability', 'Base Effect: Gain a new ability to fire a Symbiote Claw forward, dealing piercing damage to enemies in its path. Upon reaching max distance, it retracts, Launching caught enemies toward Gorr. Enhanced Effect: When teaming up with Venom, Black Berserkers receive a slight Damage Boost and apply a Slow effect to enemies they strike', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Symbiote Claw Maximum Flight Distance","value":"25m"},{"label":"Symbiote Claw Damage","value":"40 when fired, 20 when retracted"},{"label":"Black Berserker Damage Boost","value":"33%"},{"label":"Slow Rate","value":"30% for 1s"}]'::jsonb, 8),
  (36186, 'the-hood', null, null, 'Accursed Pistols', 'Normal Attack', 'Shoot forward dual-wielded pistols. Gain increased Attack Speed when Demonic Energy exceeds 50%', '[{"label":"Key","value":"Left Click"},{"label":"Shooting Damage","value":"26 per round"},{"label":"Shooting Interval","value":"0.2s"},{"label":"Shooting Damage After Demonic Energy Exceeds 50%","value":"21 per round"},{"label":"Shooting Interval After Demonic Energy Exceeds 50%","value":"0.15s"},{"label":"Damage Falloff","value":"Falloff begins at 8m, decreasing to 55% at 20m"},{"label":"Ammo","value":"40"}]'::jsonb, 0),
  (36187, 'the-hood', null, null, 'Leaded Transformation', 'Normal Attack', 'Enter Half-Demon State, transforming your arms into demonic rifles to unleash a rain of lead. These rifles have increased Attack Speed and Infinite Ammo. Every bullet that strikes an enemy triggers Lifesteal', '[{"label":"Key","value":"Left Click"},{"label":"Shooting Damage","value":"3.5 per round"},{"label":"Shooting Interval","value":"0.05s"},{"label":"Lifesteal Ratio","value":"10%"},{"label":"Leaded Transformation Damage/Bonus Health Conversion","value":"40%, Max100"},{"label":"Bullet Spread Radius","value":"Spread radius reaches 0.5m after 10 consecutive shots (calculated at 10m distance)"},{"label":"Damage Falloff","value":"Falloff begins at 8m, decreasing to 80% at 20m"}]'::jsonb, 1),
  (36188, 'the-hood', null, null, 'Mantle of Oblivion', 'Ability', 'Spread your cloak to form a spherical barrier, blocking incoming enemy attacks. When Demonic Energy exceeds 50%, the radius of the sphere expands further.', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"12"},{"label":"Max Duration","value":"1s"},{"label":"Sphere Radius","value":"2m"},{"label":"Sphere Radius After Demonic Energy Exceeds 50%","value":"3m"}]'::jsonb, 2),
  (36189, 'the-hood', null, null, 'Abyssal Veil', 'Ability', 'Throw a dark magic sphere that generates a Veil upon landing. Accursed Pistols shots passing through it generate more Demonic Energy and bullets from Leaded Transformation gain increased Lifesteal. Enemy projectiles passing through suffer reduced damage and healing output. Enemies who pass through the Veil take damage and are Blinded', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"10s"},{"label":"Summon Duration","value":"6s"},{"label":"Veil Size","value":"Width: 8m, Height: 3.5m."},{"label":"Damage Reduction","value":"20%"},{"label":"Healing Reduction","value":"20%"},{"label":"Leaded Transformation Lifesteal Ratio","value":"10%"},{"label":"Energy Gain Increased Per Accursed Pistols Hit","value":"0.75"},{"label":"Blind Duration","value":"1s"},{"label":"Damage","value":"60.00"}]'::jsonb, 3),
  (36190, 'the-hood', null, null, 'Void Walk', 'Ability', 'Enter the Void for free-flight. Upon reappearing, gain a decaying Movement Boost and damage surrounding enemies', '[{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"15s"},{"label":"Movement Boost","value":"40% during the Ability, decaying to 0% over 2s after it ends"},{"label":"Damage","value":"40"},{"label":"Spell Field Range","value":"4.5m spherical radius"},{"label":"Max Duration","value":"1.2s"}]'::jsonb, 4),
  (36191, 'the-hood', null, null, 'Ruinous Pact', 'Passive', 'Accumulate Demonic Energy by dealing damage via Accursed Pistols, blocking attacks with Mantle of Oblivion, or by using Void Walk. Reaching full energy automatically triggers the Half-Demon State', '[{"label":"Key","value":"Passive"},{"label":"Max Energy","value":"100"},{"label":"Energy Gain Per Accursed Pistols Hit","value":"2"},{"label":"Mantle Of Oblivion Block Damage/Energy Conversion","value":"3.75%"},{"label":"Energy Gain From Void Walk","value":"20"}]'::jsonb, 5),
  (36192, 'the-hood', null, null, 'Demon of the End', 'Ultimate', 'Enter Full Demon State. Fire up to 6 high-powered shots that pierce through enemies and barriers, with the final shot being the most powerful. Hitting enemies grants Bonus Health to yourself and nearby allies', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"3400"},{"label":"Max Duration","value":"12"},{"label":"Demon State Health","value":"1000"},{"label":"First 5 Rounds Damage","value":"90 + 10% of Target''s Max Health"},{"label":"Final Round Damage","value":"140 + 15% of Target''s Max Health"},{"label":"Bonus Health Per Firing","value":"50"},{"label":"Damage/Bonus Health Conversion","value":"50%"},{"label":"Bonus Health Range","value":"8m radius"},{"label":"Max Bonus Health","value":"200"}]'::jsonb, 6),
  (36193, 'the-hood', null, null, 'Chaos Collision', 'Team-Up Ability', 'Base Effect: Gain a New Ability. Create an arcane zone that continuously damages enemies and applies stacking Damage and Healing Reduction. Reactivate to teleport to the zone''s center. Enhanced Effect: When teaming up with Scarlet Witch, after teleporting, unleash a magical shockwave, dealing one-time damage to nearby enemies while launching them towards The Hood', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"16"},{"label":"Max Select Distance","value":"20m"},{"label":"Max Teleport Distance","value":"30m"},{"label":"Spell Field Duration","value":"4s"},{"label":"Spell Field Range","value":"5m spherical radius"},{"label":"Damage","value":"20 per hit, 2 hits per second"},{"label":"Damage Reduction","value":"5% per hit, Up to 40%"},{"label":"Healing Reduction","value":"5% per hit, Up to 40%"},{"label":"One-Time Damage","value":"60"}]'::jsonb, 7),
  (36194, 'the-hood', null, null, 'New Moon''s Shadow', 'Team-Up Ability', 'Base Effect: Enhances Abyssal Veil into a Lunar Barrier that blocks projectiles. Upon breaking, it detonates, damaging enemies and applying Damage and Healing Reduction. Enemies passing through take damage and are briefly Blinded. Enhanced Effect: When teaming up with Moon Knight, the Lunar Barrier has greater shield value, and The Hood''s attacks that pass through it gain a bounce effect', '[{"label":"Key","value":"E"},{"label":"Summons'' Health","value":"200"},{"label":"Explosion Damage","value":"30"},{"label":"Damage Reduction","value":"35%"},{"label":"Healing Reduction","value":"35%"},{"label":"Explosion Range","value":"8m spherical radius"},{"label":"Enhanced Summons'' Health","value":"300"},{"label":"Max Bounce Distance","value":"6m"},{"label":"Max Number Of Bounces","value":"3"},{"label":"Damage Falloff Per Bounce","value":"50%"}]'::jsonb, 8),
  (36195, 'jubilee', null, null, 'Energy Plasmoids', 'Normal Attack', 'Fire lumikinetic explosive light blasts forward to heal friends and damage foes. Triggering a Sparkle Mark briefly boosts Attack Speed and enables firing without consuming energy', '[{"label":"Key","value":"Left Click"},{"label":"Fire Rate","value":"8 per second"},{"label":"Projectile Speed","value":"200m/s"},{"label":"Damage","value":"11 per hit"},{"label":"Healing","value":"15 per hit"},{"label":"Energy","value":"48"},{"label":"Speed Boost: Fire Rate","value":"32 per second"},{"label":"Speed Boost: Damage","value":"5 per hit"},{"label":"Speed Boost: Healing","value":"6.5 per hit"},{"label":"Damage Falloff","value":"Falloff begins at 10m, decreasing to 70% at 30m"},{"label":"Attack Speed Boost Duration Per Sparkle Mark Triggered","value":"6s"}]'::jsonb, 0),
  (36196, 'jubilee', null, null, 'Blooming Ball', 'Ability', 'Launch a tracking orb of vampiric energy that damages enemies and heals allies in its radius. Striking the orb or hitting targets near it charges it up, increasing both its size and healing power. Press F to manually recall it.', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"2 charges, with each charge taking 12s to recharge."},{"label":"Orb Maximum Duration","value":"6 seconds; when reaching its max charge for the first time, duration is increased by 6 seconds"},{"label":"Energy Required To Charge Orb","value":"250 Healing/Damage"},{"label":"Range","value":"4m radius, increasing linearly with energy; up to 8m at max energy"},{"label":"Healing","value":"35/sec, increasing linearly with energy; up to 50/sec at max energy"},{"label":"Damage","value":"10 per second"},{"label":"Returned Energy On Recall","value":"0; increases linearly with energy, reaching max when the orb''s remaining duration is greater than 6 seconds, restoring 1 charge"}]'::jsonb, 1),
  (36197, 'jubilee', null, null, 'Sparking Sprint', 'Ability', 'Wrap yourself in vampiric energy to gain a Speed Boost. While active, jump height and Attack Speed are increased, and Energy Blasts can be fired at no cost', '[{"label":"Key","value":"Shift"},{"label":"Speed Boost Multiplier","value":"40%"},{"label":"Self Healing Amount","value":"25/s"},{"label":"Maximum Energy","value":"12"},{"label":"Energy Cost","value":"4/s"},{"label":"Energy Recovery","value":"1/s"},{"label":"Cooldown","value":"4s"},{"label":"Spell Field Range","value":"5m spherical radius"},{"label":"Damage","value":"45"},{"label":"Healing Amount","value":"30"}]'::jsonb, 2),
  (36198, 'jubilee', null, null, 'Dazzling Detonation', 'Ability', 'Detonate a firework energy orb, dealing damage to enemies in the area and applying a Blind effect. The energy can also be transferred to an ally, granting them healing and a Speed Boost', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"12s"},{"label":"Spell Field Range","value":"Matches current range of selected orb"},{"label":"Damage","value":"50"},{"label":"Blind Duration","value":"0.8s"},{"label":"Vulnerability","value":"10% for 3s"},{"label":"Healing Spell Field Generation Interval","value":"0.2s"},{"label":"One-Time Healing Amount","value":"65"},{"label":"Healing Over Time Amount","value":"25/sec for 3s"},{"label":"Speed Boost Multiplier","value":"40% for 3s"}]'::jsonb, 3),
  (36199, 'jubilee', null, null, 'Sparkle Mark', 'Passive', 'Hitting targets with Dazzling Detonation and Firework Finale applies a Sparkle Mark. Energy Plasmoids can detonate marks, granting allies a Healing Boost and Bonus Health, while dealing burst damage to enemies', '[{"label":"Key","value":"Passive"},{"label":"Bonus Health","value":"50"},{"label":"Healing Boost","value":"20% for 3s"},{"label":"One-Time Damage","value":"25"}]'::jsonb, 4),
  (36200, 'jubilee', null, null, 'Firework Finale', 'Ultimate', 'Charge up and unleash a massive ring of outward-flying firework clusters, Knocking Back nearby enemies. These clusters then orbit you, creating a field that damages enemies and heals allies. Expanding the cluster radius outward will Launch Up struck enemies', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"4300"},{"label":"Ability Duration","value":"10s"},{"label":"Spell Field Range","value":"Inner circle radius 6m; Outer circle radius 10m"},{"label":"Spell Field Damage","value":"20/s"},{"label":"Spell Field Healing","value":"180/s"},{"label":"Firework Cluster Range","value":"2m radius"},{"label":"Firework Cluster Healing Amount","value":"40 per hit"},{"label":"Firework Cluster Damage","value":"25 per hit"},{"label":"Firework Cluster","value":"20 m/s"},{"label":"Firework Cluster Amount","value":"5"}]'::jsonb, 5),
  (36201, 'jubilee', null, null, 'HELLFIRE SPARKS', 'Team-Up Ability', 'Base Effect: When Attack Speed is enhanced, Energy Plasmoids transform into a hitscan attack that grants self-healing on hit and is capable of dealing critical hits. Enhanced Effect: When teaming up with The Hood, the Void Magic Mark is never cleared, allowing her to indefinitely sustain the hitscan attack form.', '[{"label":"Key","value":"PASSIVE"},{"label":"Hitscan Attack Damage","value":"5 per use"},{"label":"Hitscan Attack Healing","value":"6.5 damage per use"},{"label":"Damage Falloff","value":"Falloff starts at 10m, down to 70% at 30m"},{"label":"Healing On Hit","value":"2/shot"},{"label":"Special Effect","value":"The Void Magic mark is never cleared"}]'::jsonb, 6)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36202, 'jubilee', null, null, 'VAMPIRIC KIN', 'Team-Up Ability', 'Base Effect: Deploy a Vampiric Field. Allies standing within the field gain Life Steal when attacking enemies. Enhanced Effect: When teaming up with Blade, allies inside the field receive an additional Continuous Healing effect.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Field Range","value":"12m spherical radius spell field"},{"label":"Ability Duration","value":"6s"},{"label":"Lifesteal Rate","value":"30%"},{"label":"Healing Over Time","value":"15/s"},{"label":"Enhanced Healing Over Time","value":"25/s"}]'::jsonb, 7),
  (36203, 'cyclops', null, null, 'Optic Blast', 'Normal Attack', 'Fire a quick burst of kinetic force forward. Hitting enemies accelerates Ricochet Force charge rate', '[{"label":"Key","value":"Left Click"},{"label":"Tick Rate","value":"0.03s per use"},{"label":"Damage Per Tick","value":"23"},{"label":"Hit Checks Per Attack","value":"3"},{"label":"Attack Interval","value":"0.6s"},{"label":"Ricochet Force Cd Reduction Per Hit","value":"0.3s"}]'::jsonb, 0),
  (36204, 'cyclops', null, null, 'Concussive Beam', 'Normal Attack', 'Continuously fire a powerful beam that can refract between enemies and the environment. Hitting enemies accelerates Ricochet Force charge rate', '[{"label":"Key","value":"Right Click"},{"label":"Tick Rate","value":"0.083s per use"},{"label":"Damage Per Tick","value":"11.5"},{"label":"Ricochet Damage Falloff","value":"50%, minimum 10%"},{"label":"Environment Ricochet Damage Falloff","value":"30%"},{"label":"Ricochet Force Cd Reduction Per Hit","value":"0.15s"},{"label":"Maximum Energy","value":"100"},{"label":"Energy Cost Per Second","value":"25/s"},{"label":"Energy Recovery Per Second","value":"10/s"}]'::jsonb, 1),
  (36205, 'cyclops', null, null, 'Ricochet Force', 'Ability', 'Fire a beam that can diffract and track nearby enemies after hitting terrain. Upon use, Cyclops gains Bonus Health', '[{"label":"Key","value":"E"},{"label":"Beam Damage","value":"75"},{"label":"Environment Ricochet Damage Falloff","value":"65%"},{"label":"Environment Refraction Damage Falloff","value":"20%"},{"label":"Character Refraction Damage Falloff","value":"50%"},{"label":"Environment Refraction Damage Falloff Distance","value":"Falloff begins at 8m, decreasing to 40% at 12m"},{"label":"Environment Refraction Damage Scaling Per Refraction","value":"After the first refraction, each additional refraction increases damage by 10%, up to 20%"},{"label":"Environment Refraction Character Tracking Range","value":"12m"},{"label":"Cooldown","value":"2 charges, with each charge taking 15s to recharge. Base Cooldown 2s"}]'::jsonb, 2),
  (36206, 'cyclops', null, null, 'Propulsion Burst', 'Ability', 'Fire a propulsion beam to push yourself and the target backward, applying a Slow effect to the enemy', '[{"label":"Key","value":"SHIFT"},{"label":"Cooldown","value":"15s"},{"label":"Ability Duration","value":"Minimum 0.35s, maximum 1s"},{"label":"Dash Duration","value":"Minimum 11m, maximum 22m"},{"label":"Slow Effect","value":"35% for 2s"},{"label":"Tick Rate","value":"0.083s per use"},{"label":"Damage","value":"5 per hit"}]'::jsonb, 3),
  (36207, 'cyclops', null, null, 'Optic Ascent', 'Ability', 'Fire a propulsion beam directly downward to push yourself up and knock back hit enemies, applying a Slow effect to them', '[{"label":"Key","value":"F"},{"label":"Cooldown","value":"15s"},{"label":"Ability Duration","value":"0.6s"},{"label":"Dash Duration","value":"12m"},{"label":"Movement Boost","value":"35% for 2s"},{"label":"Tick Rate","value":"0.083s per use"},{"label":"Damage","value":"5 per hit"}]'::jsonb, 4),
  (36208, 'cyclops', null, null, 'Kinetic Hover', 'Passive', 'Enter a slow-fall state while firing Concussive Beam mid-air', '[{"label":"Key","value":"Passive"}]'::jsonb, 5),
  (36209, 'cyclops', null, null, 'Ruby Rage', 'Ultimate', 'Remove visor and fire a powerful sweeping beam forward. The blast leaves behind volatile excess energy that erupts, dealing massive secondary explosive damage', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"3400"},{"label":"First Spell Field Damage","value":"75+20%Maximum Health"},{"label":"Interval Between Two Fields","value":"1.1s"},{"label":"Second Spell Field Damage","value":"75+40%Maximum Health"},{"label":"Maximum Range","value":"60m"},{"label":"Spell Field Width","value":"First field 2m, second field 8m"}]'::jsonb, 6),
  (36210, 'cyclops', null, null, 'Red Adamantium', 'Team-Up Ability', 'Cyclops supercharges Wolverine''s claws, extending his attack range. While active, Wolverine''s Vicious Rampage is replaced with Kinetic Claws, granting him a brief forward lunge that unleashes a flurry of slashes around him', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"5% Damage Boost"}]'::jsonb, 7),
  (36211, 'cyclops', null, null, 'SLIM AND RED', 'Team-Up Ability', 'Base Effect: Hitting an enemy with Ricochet Force summons the Phoenix Force to ignite them, causing continuous burn damage over a set duration. Hitting an ignited target with Optic Blast or Concussive Beam instantly triggers a percentage of the remaining burn damage as a single burst. Enhanced Effect: When teaming up with Phoenix, Spark detonations reduce the cooldown of Ricochet Force.', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"15s"},{"label":"Burn Damage","value":"7/hit, 2 times per second"},{"label":"Burn Damage Duration","value":"3s"},{"label":"Spark Detonation Damage","value":"50% of remaining Ignite damage"},{"label":"Enhanced Key","value":"Passive"},{"label":"Ricochet Force Charges","value":"0.5"}]'::jsonb, 8),
  (36212, 'cyclops', null, null, 'KINETIC KIN', 'Team-Up Ability', 'Base Effect: Release stored kinetic energy to enter an enhanced state for a duration. While active, Cyclops gains significantly increased movement speed and jump height. Enhanced Effect: When teaming up with Gambit, during the enhanced state, the attack speeds for both Optic Blast and Concussive Beam are increased.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Duration","value":"8s"},{"label":"Movement Boost","value":"40%"},{"label":"Enhanced Jump Speed","value":"5m/s"},{"label":"Optic Blast Attack Speed Boost","value":"25%"},{"label":"Concussive Beam Attack Frequency Boost","value":"15%"}]'::jsonb, 9),
  (36213, 'devil-dinosaur', null, null, 'Primal Bite', 'Normal Attack', 'Bite forward. Applies a Bleed that deals continuous Percentage Damage', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"75"},{"label":"Maximum Distance","value":"4m"},{"label":"Attack Interval","value":"1st and 3rd attacks: 1s; 2nd attack: 0.9s"},{"label":"Bleed Damage","value":"1.2% Maximum Health"},{"label":"Bleed Duration","value":"4s"},{"label":"Bleed Tick Rate","value":"2 times per second"}]'::jsonb, 0),
  (36214, 'devil-dinosaur', null, null, 'Impact Beam', 'Ability', 'Unleash a devastating beam of energy that inflicts a Bleed and Slow.', '[{"label":"Key","value":"Right Click"},{"label":"Ability Duration","value":"3.3s"},{"label":"Attack Range","value":"17m"},{"label":"Spell Field Damage","value":"40/s"},{"label":"Spell Field Radius","value":"1.2m"},{"label":"Slow Effect","value":"15% for 2s"}]'::jsonb, 1),
  (36215, 'devil-dinosaur', null, null, 'Buddy Barrier', 'Ability', 'Activate the heart-shaped generator to expand a spherical shield that blocks incoming damage. Enemies caught within are Slowed', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"12s"},{"label":"Summons Max Health","value":"450"},{"label":"Maximum Duration For Summons","value":"6s"},{"label":"Slow Effect","value":"15% for 2s"}]'::jsonb, 2),
  (36216, 'devil-dinosaur', null, null, 'Savage Predation', 'Ability', 'Dash and pounce on your prey with a vicious bite, applying a Bleed. If the target is already Bleeding, clamp down before hurling them away', '[{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"10s"},{"label":"Dash Duration","value":"2s"},{"label":"Dashing Speed","value":"15m/s"},{"label":"Bite Damage","value":"50"}]'::jsonb, 3),
  (36217, 'devil-dinosaur', null, null, 'Frenzied Feast', 'Ability', 'Unleash a flurry of continuous bites, converting the damage dealt into Bonus Health. Deals extra damage against Bleeding targets', '[{"label":"Key","value":"F"},{"label":"Cooldown","value":"8s"},{"label":"Bite Damge","value":"First 4 hits: 15 each; 5th hit: 30"},{"label":"Bonus Damage","value":"First 4 hits: 8% Maximum Health each; 5th hit: 12% Maximum Health"}]'::jsonb, 4),
  (36218, 'devil-dinosaur', null, null, 'Prehistoric Plating', 'Passive', 'Take reduced damage from headshots. Immune to launch-up, knock-back, and other displacement effects. Enemies and allies generate less Ultimate Ability Energy when damaging or healing him', '[{"label":"Key","value":"Passive"},{"label":"Headshot Damage Taken Reduction","value":"60%"},{"label":"Ultimate Energy Gain Reduction From Damage/Healing Him","value":"40%"}]'::jsonb, 5),
  (36219, 'devil-dinosaur', null, null, 'Apex Advantage', 'Passive', 'Gain Bonus Health when you inflict Bleeding upon an enemy', '[{"label":"Key","value":"Passive"},{"label":"Bonus Health","value":"150% of Bleed Damage Dealt"}]'::jsonb, 6),
  (36220, 'devil-dinosaur', null, null, 'Devil-Beast Rampage', 'Ultimate', 'Erupt in primal fury! Gain a massive Movement Speed Boost while unleashing earth-shattering stomps that Launch enemies and applies a Bleed. Thunderous roars also emit sonic waves that Slow enemies hit', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"3400"},{"label":"Stomp Field Spawn Interval","value":"0.3"},{"label":"Frenzied Feast Cooldown Reduction","value":"1s"},{"label":"Savage Predation Cooldown Reduction","value":"4s"},{"label":"Speed Boost During Ultimate","value":"70%"},{"label":"Stomp Field Range","value":"8m radius spherical spell field"},{"label":"Stomp Field Damage","value":"10"},{"label":"Stomp Field Launch-Up Interval","value":"0.8s"}]'::jsonb, 7),
  (36221, 'devil-dinosaur', null, null, 'Prehistoric Partner', 'Team-Up Ability', 'The Punisher rides atop Devil Dinosaur, restricting him to only Adjudication/Deliverance and Scourge Grenade while disabling other abilities. While mounted, Devil Dinosaur absorbs a portion of all damage inflicted on The Punisher', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"Maximum Health +100"}]'::jsonb, 8),
  (36222, 'devil-dinosaur', null, null, 'PRIMAL PUNISHMENT', 'Team-Up Ability', 'Base Effect: Adds a new ability. Upon activation, Primal Bite is replaced. Devil Dinosaur gains 2 magnetic cannons that can be fired forward; the cannonballs detonate when hitting enemies or the environment. Enhanced Effect: When teaming up with The Punisher, the duo can request an interaction. Once accepted, The Punisher rides atop Devil Dinosaur, restricting him to only Adjudication/Deliverance and Scourge Grenade while disabling other abilities. While mounted, The Punisher gains Damage Reduction; Devil Dinosaur absorbs a portion of all damage inflicted on The Punisher.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Duration","value":"8s"},{"label":"Fire Rate","value":"0.25s per hit"},{"label":"Projectile Damage","value":"5"},{"label":"Spell Field Damage","value":"20"},{"label":"Spell Field Range","value":"3m spherical radius"},{"label":"Special Effect","value":"The explosion applies a Bleed effect to targets"},{"label":"Enhanced Key","value":"X"},{"label":"Damage Reduction","value":"25%"},{"label":"Damage Conversion Rate","value":"50%"}]'::jsonb, 9),
  (36223, 'devil-dinosaur', null, null, 'SURF & TURF', 'Team-Up Ability', 'Base Effect: Impact Beam is replaced by a frontal water spray. This stream damages enemies while providing healing to teammates. Enhanced Effect: When teaming up with Jeff the Land Shark, Jeff can ride atop Devil Dinosaur''s head. While riding, both gain some Damage Reduction and are swirled in therapeutic waters, receiving Continuous Healing. Jeff can only cast Joyful Splash, Aqua Burst, and Healing Bubble during this time.', '[{"label":"Key","value":"Right Click"},{"label":"Maximum Duration","value":"5s"},{"label":"Max Attack Range","value":"20m"},{"label":"Healing Amount","value":"60/s"},{"label":"Enhanced Key","value":"X"},{"label":"Damage Reduction","value":"12.5%"},{"label":"Enhanced Healing Amount","value":"15/s"}]'::jsonb, 10),
  (36224, 'black-cat', null, null, 'FELINE FURY', 'Normal Attack', 'Swipe forward with razor-sharp claws', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"35"},{"label":"Maximum Distance","value":"3.5m"}]'::jsonb, 0),
  (36225, 'black-cat', null, null, 'CALLING CARD', 'Ultimate', 'Issue a Calling Card to all enemies. Instantly dash to any enemy in sight and range, tearing into them with your claws to deal Damage', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"3100"},{"label":"Maximum Dash Distance","value":"40m"},{"label":"Fore-Swing Damage Reduction","value":"50%"},{"label":"Ability Duration","value":"10s"},{"label":"Maximum Targeting Distance","value":"8m"},{"label":"1st Claw Strike Damage","value":"30"},{"label":"2nd Claw Strike Damage","value":"70"},{"label":"Enhanced Maximum Dash Distance","value":"60m"}]'::jsonb, 1),
  (36226, 'black-cat', null, null, 'CAT''S CRADLE', 'Ability', 'Lunge forward with claws bared, slicing through any enemies caught in your path', '[{"label":"Key","value":"Shift"},{"label":"Maximum Dash Distance","value":"15m"},{"label":"Damage","value":"40"},{"label":"Cooldown","value":"1 charges, with each charge taking 8s to recharge"}]'::jsonb, 2)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36227, 'black-cat', null, null, 'TURN OF FORTUNE', 'Ability', 'Launch a grappling hook forward that damages an enemy on impact and steals Fortunebefore pulling it back to Black Cat', '[{"label":"Key","value":"E"},{"label":"Hook Speed","value":"120m/s"},{"label":"Hook Maximum Distance","value":"30m"},{"label":"Hook Damage","value":"30"},{"label":"Bonus Health From Hook Hit","value":"50"},{"label":"Cooldown","value":"5s"}]'::jsonb, 3),
  (36228, 'black-cat', null, null, 'THIEVING GRACE', 'Ability', 'Perform a double jump', '[{"label":"Key","value":"Space"}]'::jsonb, 4),
  (36229, 'black-cat', null, null, 'FORTUNE''S FAVOR', 'Ability', 'Spend Fortuneto unleash either Grapple Swipeor Phantom Pursuit', '[{"label":"Key","value":"Right Click"},{"label":"Grapple Swipe Fortune Consumption","value":"150"},{"label":"Phantom Pursuit Fortune Consumption","value":"250"}]'::jsonb, 5),
  (36230, 'black-cat', null, null, 'STEALTHY CATWALK', 'Ability', 'Hold {Jump} to crawl up vertical surfaces', '[{"label":"Key","value":"Space"}]'::jsonb, 6),
  (36231, 'black-cat', null, null, 'MALKIN MISFORTUNE', 'Passive', 'Apply Jinxto enemies on hit. Jinxedfoes have a chance to lose their bonus damage when striking Black Cat with a Critical Hit', '[{"label":"Key","value":"Passive"}]'::jsonb, 7),
  (36232, 'black-cat', null, null, 'GIFT OF GOLD', 'Team-Up Ability', 'Black Cat shares items acquired from Insider Trading with White Fox and Captain America. White Fox receives the Life Orb, which restores Spirit Fox Tail energy and converts life energy into Nine-Tailed Radiance that auto-tracks nearby allies and enemies, granting allies speed and healing while dealing damage and slowing enemies. Captain America receives the Vibranium Energy Amplifier, which expands shield block range when raised and reflects projectiles back along the crosshair direction.', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"5% Damage Boost"}]'::jsonb, 8),
  (36233, 'black-cat', null, null, 'CLAW WHIP', 'Normal Attack', 'Fire out tethered claws and whip them forward in a devastating arc, dealing damage to all enemies caught in range', '[{"label":"Key","value":"Left Click"},{"label":"Spell Field Range","value":"150° cone spell field with a radius of 7.5m and a height of 2.5m"},{"label":"Spell Field Damage","value":"65"},{"label":"Attack Interval","value":"0.6s per hit"},{"label":"Damage Falloff","value":"Falloff begins at 30°, drop to 30% of maximum damage at 75°"},{"label":"Bonus Health Per Hit","value":"25"},{"label":"Max Bonus Health","value":"50"}]'::jsonb, 9),
  (36234, 'black-cat', null, null, 'PHANTOM PURSUIT', 'Ability', 'Swiftly dash to an enemy, unleash a rapid flurry of claw attacks, and flash back to your starting position.', '[{"label":"Key","value":"E"},{"label":"Dash Duration","value":"0.25s"},{"label":"Damage","value":"70"},{"label":"Maximum Dash Distance","value":"20m"},{"label":"Cooldown","value":"2s"},{"label":"Special Effect","value":"grants 50% Damage Reduction and Unstoppable while casting Phantom Pursuit"}]'::jsonb, 10),
  (36235, 'black-cat', null, null, 'GILDED DEAL', 'Ability', 'Use the Spatial Resonator to open a portal to the Elder Gods'' dimension, consuming Fortune to trade with the Golden Elder and acquire items from the New York Thieves Guild vault.', '[{"label":"Key","value":"F"}]'::jsonb, 11),
  (36236, 'black-cat', null, null, 'TABLET OF DESTINIES', 'Ability', 'Gain a random amount of Fortune', '[{"label":"Key","value":"F"},{"label":"Special Effect","value":"Gain 0/50/200/500 Fortune randomly"},{"label":"Fortune Consumption","value":"100"}]'::jsonb, 12),
  (36237, 'black-cat', null, null, 'HELM OF HADES', 'Ability', 'Enter Invisiblestate for a set duration', '[{"label":"Key","value":"F"},{"label":"Fortune Consumption","value":"200"},{"label":"Invisibility Duration","value":"2.5s"},{"label":"Movement Speed Boost Duration","value":"2.5s"},{"label":"Movement Boost","value":"60%, drop to 0 in 2.5s"}]'::jsonb, 13),
  (36238, 'black-cat', null, null, 'FALTINE FLAME ORB', 'Ability', 'Conjure an orb of mystical Faltine Flame to Revealand mark all nearby enemies', '[{"label":"Key","value":"F"},{"label":"Fortune Consumption","value":"200"},{"label":"Summon Health","value":"50"},{"label":"Maximum Summon Quantity","value":"1"}]'::jsonb, 14),
  (36239, 'black-cat', null, null, 'CHERNOBOG''S CRYSTAL', 'Ability', 'Purify yourself, instantly removing any active control effects', '[{"label":"Key","value":"F"},{"label":"Fortune Consumption","value":"300"},{"label":"Special Effect","value":"Remove any active control effects"}]'::jsonb, 15),
  (36240, 'black-cat', null, null, 'RING OF ZONA', 'Ability', 'Open a portal on a surface, allowing instant traversal to the opposite side', '[{"label":"Key","value":"F"},{"label":"Fortune Consumption","value":"300"}]'::jsonb, 16),
  (36241, 'black-cat', null, null, 'MENTO-FISH', 'Ability', 'Create a hypnosis field. Inflicts Slow, disables movement abilities, and Groundsall enemies caught within', '[{"label":"Key","value":"F"},{"label":"Fortune Consumption","value":"300"},{"label":"Casting","value":"Projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"30m/s"},{"label":"Spell Field Range","value":"A cylindrical spell field with a radius of 5m and a height of 40m."},{"label":"Slow Ratio","value":"35%"}]'::jsonb, 17),
  (36242, 'black-cat', null, null, 'STICKY PAWS', 'Passive', 'Steal a set amount of Fortunewhenever your attacks hit an enemy', '[{"label":"Key","value":"PASSIVE"},{"label":"Fortune Gained Per Target Hit (Feline Fury)","value":"50, up to 50"},{"label":"Fortune Gained Per Target Hit (Claw Whip)","value":"50, up to 100"},{"label":"Fortune Gained Per Target Hit (Phantom Pursuit)","value":"125, up to 125"},{"label":"Fortune Gained Per Hit (Turn Of Fortune)","value":"300"},{"label":"Fortune Gained Per Hit (Calling Card)","value":"300"},{"label":"Fortune Lost Upon Death","value":"Lose 50% of Fortune when defeated, with a minimum deduction of 200"},{"label":"Fortune Gained Per Hit (Feline Alliance)","value":"50, up to 100"}]'::jsonb, 18),
  (36243, 'black-cat', null, null, 'FELINE ALLIANCE', 'Team-Up Ability', 'Base Effect: Taking damage accumulates Vibranium Energy. Upon reaching a specific threshold, Black Cat can unleash a violent explosion, damaging and Knocking back surrounding enemies while gaining a brief Speed Boost and Bonus Health. Enhanced Effect: When teaming up with Black Panther, this explosion is no longer restricted by the energy threshold and can be triggered at any time.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Damage Taken Threshold","value":"50"},{"label":"Spell Field Range","value":"8m spherical radius spell field"},{"label":"Spell Field Damage","value":"45"},{"label":"Movement Boost","value":"3 m/s, decaying to 0 over 3s"},{"label":"Bonus Health","value":"25"},{"label":"Special Effect","value":"No longer limited by energy accumulation ratio; can be cast anytime"}]'::jsonb, 19),
  (36244, 'black-cat', null, null, 'BINDING TIES', 'Team-Up Ability', 'Base Effect: Turn of Fortune is replaced by Spider-Web Grapple, which has 2 charges. Landing the grapple on an enemy steals Fortune and applies a Spider-Tracer. If Black Cat hits an enemy carrying a Spider-Tracer with any other ability, she triggers the mark to deal bonus damage. Enhanced Effect: When teaming up with Spider-Man, using Spider-Web Grapple to hit an enemy already marked with a Spider-Tracer temporarily Immobilizes them in place.', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"2 charges, 5s each"},{"label":"Bonus Damage On Mark Trigge","value":"45"},{"label":"Imprison Duration","value":"0.5s"}]'::jsonb, 20),
  (36245, 'white-fox', null, null, 'YEOWOO GUSEUL', 'Normal Attack', 'Fire a Fox Marble forward that bounces off terrain or heroes, then homes in on nearby heroes. It damages enemies, heals allies, and restores Spirit Tail energy', '[{"label":"Key","value":"Left Click"},{"label":"Projectile Speed","value":"120m/s"},{"label":"Bounce Projectile Speed","value":"80m/s"},{"label":"Maximum Distance","value":"35m"},{"label":"Bounce Projectile Max Distance","value":"6m"},{"label":"Healing Amount","value":"Direct hit: 55 per round; bounce hit: 40 per round"},{"label":"Damage","value":"Direct hit: 40 per round; bounce hit: 25 per round"},{"label":"Fire Rate","value":"0.45s per round"}]'::jsonb, 0),
  (36246, 'white-fox', null, null, 'CLAW STRIKE', 'Normal Attack', 'While Awakened, slash forward with a flurry of attacks', '[{"label":"Key","value":"Left Click"},{"label":"Attack Interval","value":"0.45s per use"},{"label":"Damage","value":"35 per hit"},{"label":"Attack Range","value":"4m"}]'::jsonb, 1),
  (36247, 'white-fox', null, null, 'SPECTRAL SURGE', 'Ability', 'Consume one Spirit Tail to send a spectral fox forward. It heals and grants invulnerability to allies it passes through, damages and Charms enemies, forcing foes to move toward White Fox', '[{"label":"Key","value":"Right Click"},{"label":"Projectile Speed","value":"60m/s"},{"label":"Damage/Healing Radius","value":"3m"},{"label":"Charm/Invincibility Radius","value":"0.6m"},{"label":"Damage","value":"65"},{"label":"Healing Amount","value":"65"},{"label":"Cooldown","value":"6s"},{"label":"Charm Duration","value":"0.4s"},{"label":"Allies'' Invincibility Duration","value":"0.4s"},{"label":"Maximum Distance","value":"35m"},{"label":"Self Healing Amount","value":"50"}]'::jsonb, 2),
  (36248, 'white-fox', null, null, 'FOX FORM AWAKENING', 'Ability', 'Enter Awakened state, transforming Spirit Tails into physical tails. While active, continuously drain Spirit Tail energy and heal nearby allies. Striking enemies provides additional area healing', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"15s"},{"label":"Attack Generated Healing Spell Field Range","value":"10m radius spherical spell field"},{"label":"Healing Amount","value":"40 per hit"},{"label":"Healing Spell Field That Surrounds The Caster","value":"10m radius spherical spell field"},{"label":"Healing Amount","value":"25/s"},{"label":"Ability Duration","value":"Transform 3 tails: 9s; 2 tails: 8s; 1 tail: 7s"}]'::jsonb, 3),
  (36249, 'white-fox', null, null, 'SPIRIT SANCTUARY', 'Ability', 'Teleport to a chosen ally, instantly healing allies in the area while generating a shield', '[{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"15s"},{"label":"Summon Health","value":"200"},{"label":"One-Time Healing Amount","value":"50"},{"label":"Maximum Distance","value":"30m"},{"label":"Healing Spell Field Range","value":"5m radius spherical spell field"},{"label":"Maximum Duration For Summons","value":"5s"},{"label":"Special Effect","value":"While the shield is active, it provides 20/s Healing Over Time to allies (including White Fox) within the shield''s range"}]'::jsonb, 4),
  (36250, 'white-fox', null, null, 'TAIL SWEEP', 'Ability', 'While Awakened, sweep forward tails to launch up hit enemies', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"3s"},{"label":"Attack Range","value":"5m"},{"label":"Damage","value":"50"}]'::jsonb, 5),
  (36251, 'white-fox', null, null, 'Predatory Pounce', 'Ability', 'While Awakened, dash forward. Hit an enemy to slow them, enabling a second dash that knocks back enemies', '[{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"6s"},{"label":"Dash Duration","value":"10m"},{"label":"Damage","value":"40"},{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"6s"},{"label":"Dash Duration","value":"15m"},{"label":"Damage","value":"40"}]'::jsonb, 6)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36252, 'white-fox', null, null, 'KUMIHO UNLEASHED', 'Ultimate', 'Manifest the full Nine-Tailed Fox form and continuously heal nearby allies. Cannot receive healing effects from others while in this form', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"4300"},{"label":"Maximum Health","value":"1200"},{"label":"Continuous Healing Spell Field Range","value":"10m radius spherical spell field"},{"label":"Healing Amount","value":"85/s"},{"label":"Special Effect","value":"After casting, automatically apply the Blessed by the Nine effect to all allies within a 10m radius for 3s."}]'::jsonb, 7),
  (36253, 'white-fox', null, null, 'SPIRIT FOX WARD', 'Team-Up Ability', 'White Fox grants Luna Snow a spirit fox for protection. Luna can activate it for a burst of speed and fire it forward, healing allies in its path while applying Charm to enemies', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"10% Healing Boost"}]'::jsonb, 8),
  (36254, 'white-fox', null, null, 'NINE-TAILED AURA', 'Team-Up Ability', 'Black Cat shares her luck with her allies. When White Fox embraces her newfound fortune, she unleashestracking Spirit Tails to grant Healing and Speed to allies, while damaging and Slowing foes. When Captain America enjoys his luck, his shield''s block radius expands and allows him to aim deflectedProjectiles directly toward his target', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20"},{"label":"Range","value":"10m spherical radius spell field"},{"label":"Movement Boost","value":"30% for 2s"},{"label":"Slow Effect","value":"30% for 2s"},{"label":"One-Time Healing","value":"60"},{"label":"One-Time Damage","value":"40"},{"label":"Passive Energy Recover","value":"1"}]'::jsonb, 9),
  (36255, 'white-fox', null, null, 'NINEFOLD SLAM', 'Normal Attack', 'In Kumiho Form, slam the ground, causing an explosive shockwave. Hitting enemies or summons grants One-Time Healing to self and nearby allies', '[{"label":"Key","value":"Left Click"},{"label":"Max Attack Range","value":"5m"},{"label":"Damage","value":"50 per hit"},{"label":"Explosion Damage","value":"50 per hit"},{"label":"Attack Interval","value":"1 per second"},{"label":"Attack Generated Healing Spell Field Range","value":"10m radius spherical spell field"},{"label":"Explosion Spell Field Range","value":"6m radius spherical spell field"},{"label":"Healing Amount","value":"100 per hit"}]'::jsonb, 10),
  (36256, 'white-fox', null, null, 'BLESSED BY THE NINE', 'Ability', 'In Kumiho Form, select an ally to grant Continuous Healing, Unstoppable, and Life-Steal for a short time', '[{"label":"Key","value":"Right Click"},{"label":"Maximum Select Distance","value":"50m"},{"label":"Healing Over Time Amount","value":"40/s"},{"label":"Unstoppable State Duration","value":"3s"},{"label":"Life-Steal Ratio","value":"0.25"},{"label":"Cooldown","value":"2s"}]'::jsonb, 11),
  (36257, 'white-fox', null, null, 'LUCKY LOAN', 'Team-Up Ability', 'Base Effect: White Fox receives an Orb of Life from Black Cat. Upon use, it recovers Spirit Tail energy and converts life energy into Nine-Tailed Aura that shoots out in all directions. This automatically tracks nearby allies and enemies, granting Speed and Healing to allies while damaging and Slowing enemies. nhanced Effect: When teaming up with Black Cat, using the Orb triggers a state where Spirit Tail Energy is no longer consumed for a duration, allowing free use of Spectral Surge and Fox Form Awakening.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"25s"},{"label":"Spell Field Duration","value":"5s"},{"label":"Damage","value":"10/s"},{"label":"Healing Amount","value":"15/s"},{"label":"Slow Rate","value":"20% for 2s"},{"label":"Movement Boost","value":"20% for 2s"},{"label":"Passive Energy Recover","value":"1"},{"label":"Duration","value":"6s"}]'::jsonb, 12),
  (36258, 'white-fox', null, null, 'PSIONIC FOX', 'Team-Up Ability', 'Base Effect: Activating Fox Form Awakening no longer consumes Spirit Tail energy, and grants the maximum possible duration immediately upon use. Enhanced Effect: When teaming up with Psylocke, the cooldown for Fox Form Awakening is drastically reduced.', '[{"label":"Key","value":"Passive"},{"label":"Fox Form Awakening Cd","value":"15s"},{"label":"Duration","value":"10s"},{"label":"Enhanced Fox Form Awakening Cd","value":"12s"}]'::jsonb, 13),
  (36259, 'elsa-bloodstone', null, null, 'DOUBLE-BARREL BLASTER', 'Normal Attack', 'Fire your shotgun forward', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Shotgun projectiles that hit instantly"},{"label":"Damage","value":"4.5 per round"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 70% at 30m"},{"label":"Bullets Fired Each Cast","value":"10"},{"label":"Crosshair Spread Radius(At 10m)","value":"0.13m"},{"label":"Fire Rate","value":"The firing interval between shots is 0.12s, with an interval of 0.8s between each round of shooting"},{"label":"Ammo","value":"12"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36260, 'elsa-bloodstone', null, null, 'MONSTER-PIERCER', 'Normal Attack', 'Unleash your elephant gun forward. Bullets pierce enemies and deal high damage', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Shotgun projectiles that hit instantly"},{"label":"Damage","value":"12+0.8% of enemy''s maximum health"},{"label":"Bullets Fired Each Cast","value":"5"},{"label":"Crosshair Spread Radius (At 10m)","value":"6m"},{"label":"Critical Hit","value":"No"}]'::jsonb, 1),
  (36261, 'elsa-bloodstone', null, null, 'INHERITED INSTINCT', 'Passive', 'Dealing damage increases hunting Instinct. Defeating enemies caught by Smoky Snare grants additional Instinct. Higher Instinct reduces the cooldown of Helix Advance', '[{"label":"Key","value":"PASSIVE"},{"label":"Instinct From Kos","value":"100"},{"label":"Additional Instinct From Kos Caught By Smoky Snare","value":"200"},{"label":"Damage/Instinct Conversion Rate","value":"0.009"},{"label":"Special Effect 1","value":"Instinct levels up when it reaches 100, up to 3 levels"},{"label":"Special Effect 2","value":"For each Instinct level gained, reduce the cooldown of Helix Advance by 2s"}]'::jsonb, 2),
  (36262, 'elsa-bloodstone', null, null, 'RUTHLESS PURSUIT', 'Ability', 'Dash forward, gaining Bonus Health and launching enemies hit. Follow up with a Double-Barrel Blaster shot that propels you backward and Slows enemies. Using either stage empowers your next Double-Barrel Blaster, transforming it into Monster-Piercer', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Movement-based damage ability"},{"label":"Max Dash Speed","value":"40m/s"},{"label":"Max Dash Duration","value":"0.3s"},{"label":"Damage","value":"30"},{"label":"Cooldown","value":"8s"},{"label":"Special Effect 1","value":"Launch up enemies hit, and activate the follow up in 5s"},{"label":"Special Effect 2","value":"Using either stage empowers your next Double-Barrel Blaster, transforming it into Monster-Piercer"},{"label":"Bonus Health","value":"Every unleash of Ruthless Pursuit and Helix Advance grants 25 bonus health. Max bonus health is 75"},{"label":"Key","value":"E"},{"label":"Max Damage Distance","value":"8m"},{"label":"Damage","value":"30"},{"label":"Dash Speed","value":"15 m/s"}]'::jsonb, 3),
  (36263, 'elsa-bloodstone', null, null, 'HELIX ADVANCE', 'Ability', 'Dash forward. Your next Double-Barrel Blaster becomes Monster-Piercer', '[{"label":"Key","value":"Shift"},{"label":"Max Dash Speed","value":"27.5m/s"},{"label":"Max Dash Duration","value":"0.28s"},{"label":"Special Effect","value":"In 6s after unleashing Helix Advance, the next Double-Barrel Blaster becomes Monster-Piercer"},{"label":"Special Effect 2","value":"Every unleash of Ruthless Pursuit and Helix Advance grants 25 bonus health. Max bonus health is 75"},{"label":"Cooldown","value":"11s"}]'::jsonb, 4),
  (36264, 'elsa-bloodstone', null, null, 'LIVING BULLET', 'Ability', 'Fire a Living Bullet round that splits upon impact, seeking nearby enemies and marking each with a Spectral Sigil. Hitting marked targets with Double-Barrel Blaster or Monster-Piercer grants Elsa a brief Speed boost. Living Bullets deal extra damage to shields and enemies with Bonus Health', '[{"label":"Key","value":"Right Click"},{"label":"Projectile Speed","value":"60m/s"},{"label":"Projectile Damage","value":"60"},{"label":"Special Effect 1","value":"After hits an enemy, the projectile splits to several bullets to trace the enemies in range"},{"label":"Tracing Range","value":"8m radius spherical spell field"},{"label":"Maximum Splits","value":"3"},{"label":"Cooldown","value":"8s"},{"label":"Special Effect 2","value":"Projectile deals 40 extra damage to shields and enemies with bonus health"},{"label":"Speed Boost","value":"Increase movement speed by 40% for 1s"}]'::jsonb, 5),
  (36265, 'elsa-bloodstone', null, null, 'SMOKY SNARE', 'Ability', 'Launch a trap containing the monster Diablo. Once deployed, it becomes Invisible and Invulnerable. When an enemy triggers it, Diablo Immobilizes and Damages them. Use to dash to the trapped enemy. Enemies can destroy Diablo to break free', '[{"label":"Key","value":"F"},{"label":"Cooldown","value":"12s"},{"label":"Trap Health","value":"100"},{"label":"Maximum Immobilizing Duration","value":"1.2s"},{"label":"Special Effect 1","value":"The trap becomes Invisible and Invulnerable after one-second deployment"},{"label":"Triggered Trap Damage","value":"Cause 5 damage every 0.2s, last 1.2s"},{"label":"Summons'' Health","value":"50"},{"label":"Special Effect 2","value":"Defeat the summon to end the Immobolized state early"},{"label":"Special Effect 3","value":"Elsa can dash to the enemy who triggers the trap"},{"label":"Maximum Select Distance","value":"30m"},{"label":"Maximum Dash Duration","value":"0.25s"},{"label":"Maximum Dash Speed","value":"60m/s"}]'::jsonb, 6),
  (36266, 'elsa-bloodstone', null, null, 'APEX PREDATOR', 'Ultimate', 'Summon the Glartrox to charge forward. The Glartrox can be recalled to charge back toward Elsa. When colliding with terrain or upon return, it bites fiercely, dealing heavy damage', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"3400"},{"label":"Glartrox Health","value":"400"},{"label":"Glartrox Seize Damage","value":"75"},{"label":"Glartrox Bite Damage","value":"125"},{"label":"Special Effect 1","value":"Enemies seized by Glartrox cannot use their abilities until it stops moving"},{"label":"Special Effect 2","value":"Elsa can recall Glartrox at any time"},{"label":"Special Effect 3","value":"When the Glartrox collides with terrain, returns, or reaches its maximum dash duration, it bites fiercely, dealing massive damage. If Glartrox is defeated, the bite will not be triggered"},{"label":"Glartrox Movement Speed","value":"15m/s"},{"label":"Glartrox Maximum Dash Duration","value":"Maximum durations for dashing and returning are 3.5s each"},{"label":"Special Effect","value":"Glartrox cannot be critical hit. Drag 8 targets at most"}]'::jsonb, 7),
  (36267, 'elsa-bloodstone', null, null, 'BLOODSTONE''S BOOMBOX BULLETS', 'Team-Up Ability', 'Deadpool hands Jeff the Land Shark a plushie. Jeff can spit it ahead where it''ll continuously Taunt nearby enemies and Block Vision, while allies in range are healed! Elsa Bloodstone''s Living Bullet changes to special rounds that Taunt targets with Deadpool''s chatter, while Slowing, and damaging nearby enemies over time. Elsa can recall the rounds to heal based on damage dealt', '[{"label":"Key","value":"Right Click"},{"label":"Projectile Speed","value":"60m/s"},{"label":"Projectile Damage","value":"First hit: 60; second hit: 40"},{"label":"Second Hit Damage Over Time","value":"20/s for 2s"},{"label":"Slow Effect","value":"Reduce movement speed by 35% for 2s"},{"label":"Taunt Duration","value":"2s"},{"label":"Damage/Healing Conversion Rate","value":"30%"}]'::jsonb, 8),
  (36268, 'elsa-bloodstone', null, null, 'PREHISTORIC TRAP', 'Team-Up Ability', 'Base Effect: After deploying the Smoky Snare trap, Diablo will monitor the area. If enemies approach, Diablo Immobilizes and Damages them. He also releases a lethal gas, causing continuous area damage. Enhanced Effect: When teaming up with Devil Dinosaur, Elsa can store and deploy two Smoky Snares.', '[{"label":"Key","value":"F"},{"label":"Cooldown","value":"15s"},{"label":"Trap Trigger Range","value":"5m radius"},{"label":"Trap Damage","value":"30"},{"label":"Lethal Gas Range","value":"3m radius"},{"label":"Lethal Gas Duration","value":"2s"},{"label":"Lethal Gas Damage","value":"35/s"},{"label":"Special Effect","value":"Up to 2 Smoky Snares can exist on the field simultaneously"}]'::jsonb, 9),
  (36269, 'elsa-bloodstone', null, null, 'LOUDMOUTH MERCS', 'Team-Up Ability', 'Base Effect: Living Bullet changes to special rounds that Taunt targets with Deadpool''s chatter, while Slowing, and damaging nearby enemies over time. After a timer, the bullet auto-recalls, healing Elsa based on the damage dealt while adding one extra gauge block to her Inherited Instinct passive cap. Enhanced Effect: When teaming up with Deadpool, Deadpool breaks the fourth wall, significantly boosting Instinct acquisition rate.', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"8s"},{"label":"Projectile Damage","value":"60"},{"label":"Split Bullet Damage","value":"40"},{"label":"Damage Over Time","value":"20/s for 2s"},{"label":"Slow Effect","value":"25% for 2s"},{"label":"Enhanced Key","value":"Passive"},{"label":"Energy Gain Multiplier From Damage","value":"0.0012"}]'::jsonb, 10),
  (36270, 'deadpool', null, null, 'DUAL DESERT EAGLES - VANGUARD', 'Normal Attack', 'Nobody lays a finger on my teammates! Anyone tries, and I''m firing these big boy bullets straight at their face!', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Rapid-fire projectile."},{"label":"Damage","value":"36 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 15m, decreasing to 75% at 30m"},{"label":"Fire Rate","value":"2.5 rounds per second"},{"label":"Ammo","value":"30"}]'::jsonb, 0),
  (36271, 'deadpool', null, null, 'THE BAN HAMMER', 'Ultimate', 'You! Yeah, you - the hyper one! Eyes off my friends. I sentence you to...whatever! Get ready to be taunted. I get bonus HP and healing, and if you whiff your abilities, you take damage, and I get even more HP!', '[{"label":"Key","value":"Q"},{"label":"Damage From Per Ability Missed","value":"35"},{"label":"Bonus Health From Per Ability Missed","value":"60 per ability missed"},{"label":"Ability Duration","value":"8s"},{"label":"Bonus Health Gained Upon Activation","value":"300"},{"label":"Healing Over Time During Activation","value":"35/s"},{"label":"Cooldown","value":"60s"}]'::jsonb, 1),
  (36272, 'deadpool', null, null, 'MAGICAL UNICORN SHIELD!', 'Ability', 'Plushie power! It stops every single attack those chumps throw, giving my team a safety bubble. It''s cute AND bulletproof', '[{"label":"Key","value":"Right Click"},{"label":"Summons'' Health","value":"300"},{"label":"Maximum Duration For Summons","value":"4s"},{"label":"Cooldown","value":"12s"}]'::jsonb, 2),
  (36273, 'deadpool', null, null, 'BUNNY BOUNCE', 'Ability', 'Yup, I can double jump in midair! During The Big Test and its upgrade, I can also stomp heads and wall jump to reset its cooldown. Stomp enemies so hard they won''t get near my team!', '[{"label":"Key","value":"Space"},{"label":"Cooldown","value":"6s"},{"label":"Maximum Jump Distance","value":"16m"},{"label":"Maximum Dash Distance","value":"16m"}]'::jsonb, 3),
  (36274, 'deadpool', null, null, 'HEALING FACTOR', 'Passive', 'Out of combat? I''m healing up, staying battle-ready to protect my team. And if I''m about to croak? Surprise! I get a free pass, and my health zooms back up. Nice try, villains', '[{"label":"Key","value":"PASSIVE"},{"label":"Healing Over Time","value":"25/s"},{"label":"Healing Over Time From Activated Healing Factor","value":"50/s"},{"label":"Cooldown","value":"45s"},{"label":"Special Effect","value":"The healing factor kicks in after Deadpool has been out of combat for 5s. If Deadpool takes more than 200 damage within a two-second window, the healing factor activates and boosts the healing"},{"label":"Enhanced Cooldown","value":"30s"}]'::jsonb, 4),
  (36275, 'deadpool', null, null, 'MAXIMUM FLAIR', 'Passive', 'Listen up, eyes on the prize, don''t wander off! Every time my abilities land on a bad guy, the style points shoot up a notch! When it''s full, I can pop my ultimate! With me on the team, you''re all staying alive and fabulous!', '[{"label":"Key","value":"Passive"},{"label":"Special Effect","value":"The ultimate ability can be unleashed after reaching an S rating. The rating is cleared if Deadpool is defeated."},{"label":"Enhanced Special Effect","value":"The ultimate ability can be unleashed after reaching an S rating. The rating is cleared if Deadpool is defeated"}]'::jsonb, 5),
  (36276, 'deadpool', null, null, 'UPGRADE!', 'Ability', 'I''m here to smack baddies, get XP, and shield my friends! When my XP is full, I get to upgrade an ability! Bonus: Score the final hit and force your foe into a selfie—more XP for me! I''m invincible while striking my best duckface. No photobombs!', '[{"label":"Key","value":"F"},{"label":"Special Effect","value":"Accumulate XP in battle. When maxed, choose an ability to upgrade for powerful boosts"},{"label":"Enhanced Special Effect","value":"Accumulate XP in battle. When maxed, choose an ability to upgrade for powerful boosts."}]'::jsonb, 6)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36277, 'deadpool', null, null, 'DEADPOOL IN YOUR AREA - VANGUARD', 'Ability', 'Want to hurt my team? Good luck! I hit you with a taunt, mess up your vision, and burn your health nonstop! Best part: my swords and guns go full turbo for the duration. Blink and you''ll miss it', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"12s"},{"label":"Ability Duration","value":"5s"},{"label":"Special Effect","value":"Disrupt enemies'' vision in range and gain XP. Enemies can damage Deadpool to end the disruption. Increase left-click attack speed for the duration."},{"label":"Damage Needed To Remove The Disruption","value":"100"},{"label":"Spell Field Damage","value":"10/s"},{"label":"Spell Field Range","value":"A cylindrical spell field with a 6m radius and a height of 6m."},{"label":"Enhanced Spell Field Range","value":"A cylindrical spell field with a 6m radius and a height of 6m"}]'::jsonb, 7),
  (36278, 'deadpool', null, null, 'Comical Chaos', 'Team-Up Ability', 'Deadpool hands Jeff the Land Shark a plushie with attitude. Jeff can spit it ahead where it''ll continuously Taunt nearby enemies and Block Vision, while allies in range enjoy a plush-powered healing party!', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"+50 Max Health"},{"label":"Enhanced Team-Up Bonus","value":"5% Damage Boost"},{"label":"Enhanced Team-Up Bonus","value":"+5% Healing Bonus"}]'::jsonb, 8),
  (36279, 'deadpool', null, null, 'KICK@$$ KATANA - VANGUARD', 'Normal Attack', 'Protecting my team means my katanas go full savage. No mercy for the baddies!', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"30 per hit"},{"label":"Attack Interval","value":"First strike: 0.6s; second strike: 0.53s; third strike: 0.6s"},{"label":"Maximum Distance","value":"4m"}]'::jsonb, 9),
  (36280, 'deadpool', null, null, 'THE BIG TEST', 'Ultimate', 'Wake the #!&% up, hero! We''ve got a game to win! Speed and healing buffs for starters, bonus Hazardous Hijinks for me, and extra HP for me and my nearby friends. Hit enough baddies with the right abilities exactly as I ask, and you unlock mega speed and healing, plus reset my Healing Factor cooldown!. Team protection mode: activated!', '[{"label":"Key","value":"Q"},{"label":"Ability Duration","value":"The challenge lasts 12s. The buff lasts 6s after you complete it."},{"label":"Boost Spell Field Range","value":"6m radius spherical spell field"},{"label":"Bonus Health","value":"Self: 350; allies: 50"},{"label":"Healing Over Time","value":"Upon activation: 50/s; challenge completed: 100/s"},{"label":"Movement Boost","value":"Upon activation: 15%; challenge completed: 30%"},{"label":"Cooldown","value":"60s"}]'::jsonb, 10),
  (36281, 'deadpool', null, null, 'HAZARDOUS HIJINKS - VANGUARD', 'Ability', 'Try getting to my teammates, I dare you! My dash slash knocks fools down, and if I hit, I get to do it again. Up to three times, baby!', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"10s"},{"label":"Special Effect","value":"Refresh the cooldown if it hits an enemy for up to 2 times."},{"label":"Damage","value":"40"},{"label":"Dash Duration","value":"Up to 12m"}]'::jsonb, 11),
  (36282, 'deadpool', null, null, 'DUAL DESERT EAGLES - VANGUARD UPGRADED', 'Normal Attack', 'I rack up shots, then, BOOM! A mind-blowing bubble bomb for all the enemies. Teammate security: maximum', '[{"label":"Key","value":"Left Click"},{"label":"Beam Damage","value":"40 damage per round"},{"label":"Beam Attack Interval","value":"2.5 rounds per second"},{"label":"Ammo","value":"40"},{"label":"Projectile Attack Interval","value":"After every 5 beam bullets fired, the next shot fires 1 additional projectile"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Spell Field Damage","value":"25"},{"label":"Spell Field Range","value":"3m radius spherical spell field"}]'::jsonb, 12),
  (36283, 'deadpool', null, null, 'KICK@$$ KATANA - VANGUARD UPGRADED', 'Normal Attack', 'Relax, you''ve got Deadpool on your side! Swords out, baddies out. My stab hits crit, and a Bad Bunny hit makes the next swing a stabby special', '[{"label":"Key","value":"Left Click"},{"label":"Damage","value":"35 per hit"},{"label":"Attack Interval","value":"First strike: 0.5s; second strike: 0.43s; third strike: 0.5s"},{"label":"Maximum Distance","value":"4m"}]'::jsonb, 13),
  (36284, 'deadpool', null, null, 'DEADPOOL IN YOUR AREA - VANGUARD UPGRADED', 'Ability', 'Teammates, stay safe! Dummies, look here! It''s showtime: I taunt, blind you, and hit warp speed with my swords and guns. Plus, my crew gets a damage reduction buff, so they''re basically invincible. Dummies that stick around too long will even have their UI taped over!', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"12s"},{"label":"Ability Duration","value":"5s"},{"label":"Special Effect","value":"Disrupt enemies'' vision in range and gain XP. Enemies can damage Deadpool to end the disruption. Increase left-click attack speed for the duration."},{"label":"Damage Needed To Remove The Disruption","value":"100"},{"label":"Spell Field Damage","value":"10/s"},{"label":"Spell Field Range","value":"A cylindrical spell field with a 6m radius and a height of 6m"},{"label":"Damage Reduction","value":"Self: 35%; allies: 25%"}]'::jsonb, 14),
  (36285, 'deadpool', null, null, 'HAZARDOUS HIJINKS - VANGUARD UPGRADED', 'Ability', 'Watch this pro bodyguard in action! I dash forward, nail the bad guy, and bounce in any direction I want. Oh, and I can do this two more times real quick!', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"2 charges, with each charge taking 10s to recharge."},{"label":"Special Effect","value":"Refresh the cooldown if it hits an enemy for up to 2 times. Deadpool bounces as the ability hits an enemy."},{"label":"Damage","value":"40"},{"label":"Dash Duration","value":"Up to 12m"}]'::jsonb, 15),
  (36286, 'deadpool', null, null, 'MAGICAL UNICORN SHIELD! - UPGRADED', 'Ability', 'My ultra-cool, super shiny, extra huggable, and totally blinged-out plushy. Toss it ahead, and it lands as an invincible sphere of awesomeness! Blocking attacks and keeping my team safe inside our furry fortress', '[{"label":"Key","value":"Right Click"},{"label":"Summons'' Health","value":"400"},{"label":"Maximum Duration For Summons","value":"4s"},{"label":"Cooldown","value":"12s"}]'::jsonb, 16),
  (36287, 'deadpool', null, null, 'THE BIG TEST - UPGRADED', 'Ultimate', 'Hey, player! Warm-up''s over, time for the main event! Speed, healing, dashes, for me, and bonus HP for all! Smash enough baddies with the skills I say, and you unlock super buffs (massive speed and healing), plus Healing Factor resets. For some time after, each hit means more HP for the crew and you. Don''t mess this up!', '[{"label":"Key","value":"Q"},{"label":"Ability Duration","value":"The challenge lasts 12s. The buff lasts 8s after you complete it."},{"label":"Boost Spell Field Range","value":"6m radius spherical spell field"},{"label":"Bonus Health","value":"Self: 350; allies: 50"},{"label":"Healing Over Time","value":"Upon activation: 50/s; challenge completed: 100/s"},{"label":"Movement Boost","value":"Upon activation: 15%; challenge completed: 30%"},{"label":"Cooldown","value":"60s"},{"label":"Damage/Health Conversion","value":"100%"}]'::jsonb, 17),
  (36288, 'deadpool', null, null, 'THE BAN HAMMER - UPGRADED', 'Ultimate', 'Upgraded courtroom drama! Congrats, unlucky one! You''re my pick; enjoy the taunt! I score bonus health and healing, and you take ongoing damage. If you miss an ability while court is in session, it''s a double whammy. You get more pain, AND I get more extra HP! Thanks in advance!', '[{"label":"Key","value":"Q"},{"label":"Damage From Per Ability Missed","value":"35"},{"label":"Bonus Health From Per Ability Missed","value":"70 per ability missed"},{"label":"Ability Duration","value":"8s"},{"label":"Bonus Health Upon Activation","value":"300"},{"label":"Healing During Activation","value":"35/s"},{"label":"Cooldown","value":"60s"},{"label":"Damage Over Time","value":"25/s"}]'::jsonb, 18),
  (36289, 'deadpool', null, null, 'DUAL DESERT EAGLES - DUELIST', 'Normal Attack', 'Bang! Bang! Unleash two hand cannons left and right, because one gun is never enough. Pew pew, baby!', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Rapid-fire projectile"},{"label":"Damage","value":"42 per hit"},{"label":"Damage Falloff","value":"Falloff begins at 18m, decreasing to 80% at 30m"},{"label":"Fire Rate","value":"2.5 rounds per second"},{"label":"Ammo","value":"30"}]'::jsonb, 19),
  (36290, 'deadpool', null, null, 'SKILL ISSUE', 'Ultimate', 'Let''s play judge! Pick a dumb-dumb and slap a taunt. They miss an ability? Boom! Gavel drops, and I slap them with pain and snark', '[{"label":"Key","value":"Q"},{"label":"Damage From Per Ability Missed","value":"60"},{"label":"Ability Duration","value":"8s"},{"label":"Cooldown","value":"45s"}]'::jsonb, 20),
  (36291, 'deadpool', null, null, 'HEADSHOT! - DUELIST', 'Ability', 'Ever seen someone throw their own face? Watch me KO a crowd, then catch my mug on the rebound!. Don''t lose your head over it', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact that also generates a spell field"},{"label":"Projectile Damage","value":"Unleash: 30; return: 25"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Spell Field Damage","value":"15/s"},{"label":"Spell Field Range","value":"4m spherical radius spell field"},{"label":"Spell Field Duration","value":"1s"},{"label":"Cooldown","value":"10s"}]'::jsonb, 21),
  (36292, 'deadpool', null, null, 'BUNNY HOP', 'Ability', 'Hippity-hoppity, Deadpool''s on your property! Watch me squeeze in a second jump midair! Hop on heads or kick off walls with Bunny Hop to refresh the cooldown, and if I land on someone? Free health for me, and a headache for them. Whee!', '[{"label":"Key","value":"Space"},{"label":"Damage","value":"25"},{"label":"Bonus Health","value":"25, up to 50"},{"label":"Cooldown","value":"6s"},{"label":"Special Effect","value":"Refresh the cooldown if it hits an enemy."},{"label":"Enhanced Special Effect","value":"Refresh the cooldown if it hits an enemy or an ally. Transform the next katana base attack to a Stab."}]'::jsonb, 22),
  (36293, 'deadpool', null, null, 'DEADPOOL IN YOUR AREA - DUELIST', 'Ability', 'True heroes taunt face-to-face! I roast nearby baddies, mess up their vision, and tank their hits like a boss. Try me!', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"12s"},{"label":"Ability Duration","value":"5s"},{"label":"Special Effect","value":"Disrupt enemies'' vision in range and gain XP. Enemies can damage Deadpool to end the disruption."},{"label":"Damage Needed To Remove The Disruption","value":"100"},{"label":"Self Damage Reduction","value":"20%"},{"label":"Spell Field Damage","value":"15/s"},{"label":"Spell Field Range","value":"A cylindrical spell field with a 6m radius and a height of 6m"}]'::jsonb, 23),
  (36294, 'deadpool', null, null, 'KICK@$$ KATANA - DUELIST', 'Normal Attack', 'Slicey, dicey, twice as nicey! Swing both swords at whoever gets too close. Sushi, anyone?', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"40 per hit"},{"label":"Attack Interval","value":"First strike: 0.6s; second strike: 0.53s; third strike: 0.6s"},{"label":"Maximum Distance","value":"4m"}]'::jsonb, 24),
  (36295, 'deadpool', null, null, 'POP QUIZ!', 'Ultimate', 'Hey, you! Yeah, you! Ready for a challenge? Free speed and healing just for trying. Nail enough hits with the right abilities and unlock the deluxe speed-heal package. It''s an A+ in chaos!', '[{"label":"Key","value":"Q"},{"label":"Ability Duration","value":"The challenge lasts 12s. The buff lasts 6s after you complete it."},{"label":"Healing Over Time","value":"Upon activation: 25/s; challenge completed: 50/s"},{"label":"Movement Boost","value":"Upon activation: 15%; challenge completed: 30%"},{"label":"Cooldown","value":"45s"}]'::jsonb, 25),
  (36296, 'deadpool', null, null, 'HAZARDOUS HIJINKS - DUELIST', 'Ability', 'Blink, and you''ll miss my deadly dash combo. Slash, dash, repeat! Hit someone? You get to go again! (Up to 2 more times. Don''t get greedy.) Who says I can''t multitask?', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"2 charges, with each charge taking 10s to recharge."},{"label":"Special Effect","value":"Refresh the cooldown if it hits an enemy for up to 2 times."},{"label":"Damage","value":"40"},{"label":"Dash Duration","value":"Up to 12m"}]'::jsonb, 26),
  (36297, 'deadpool', null, null, 'DUAL DESERT EAGLES - DUELIST UPGRADED', 'Normal Attack', 'Keep blasting till you trigger a BOOM. My thoughts literally explode onto the battlefield. Talk about mind-blowing firepower!', '[{"label":"Key","value":"Left Click"},{"label":"Beam Damage","value":"46 damage per round"},{"label":"Beam Attack Interval","value":"2 rounds per second"},{"label":"Ammo","value":"40"},{"label":"Projectile Attack Interval","value":"After every 5 beam bullets fired, the next shot fires 1 additional projectile"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Spell Field Damage","value":"25"},{"label":"Spell Field Range","value":"3m radius spherical spell field"}]'::jsonb, 27),
  (36298, 'deadpool', null, null, 'KICK@$$ KATANA - DUELIST UPGRADED', 'Normal Attack', 'Now with extra chop! Stabs can go straight for the noggin. Heads up! Do a Bunny Hop and POW! Stabby Stabby action guaranteed! Run while you can!', '[{"label":"Key","value":"Left Click"},{"label":"Damage","value":"45 per hit"},{"label":"Attack Interval","value":"First strike: 0.5s; second strike: 0.43s; third strike: 0.5s"},{"label":"Maximum Distance","value":"4m"}]'::jsonb, 28),
  (36299, 'deadpool', null, null, 'DEADPOOL IN YOUR AREA - DUELIST UPGRADED', 'Ability', 'Check out the best trash talk in the Chronoverse! Keep taunting and melting their HP! I even block their screen, so they can''t see squat. Plus, I tank hits like a champ. Enemies that stick around too long get the bottom of their screen taped up. By the end, they won''t even find their health bar and whatnot. Good luck fighting what you can''t see, suckers!', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"12s"},{"label":"Ability Duration","value":"5s"},{"label":"Special Effect","value":"Disrupt enemies'' vision in range and gain XP. Enemies can damage Deadpool to end the disruption."},{"label":"Damage Needed To Remove The Disruption","value":"100"},{"label":"Self Damage Reduction","value":"35%"},{"label":"Spell Field Damage","value":"15/s"},{"label":"Spell Field Range","value":"A cylindrical spell field with a 6m radius and a height of 6m"}]'::jsonb, 29),
  (36300, 'deadpool', null, null, 'HAZARDOUS HIJINKS - DUELIST UPGRADED', 'Ability', 'Now with bouncy castle action! Slash, bounce, repeat. It''s like the world''s deadliest pinball!. Cooldowns? Never heard of ''em. Keep going as long as you hit stuff, just don''t let me fall flat on my ass!', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"2 charges, with each charge taking 10s to recharge."},{"label":"Special Effect","value":"Refresh the cooldown if it hits an enemy. Deadpool bounces as the ability hits an enemy."},{"label":"Damage","value":"40"},{"label":"Dash Duration","value":"Up to 12m"}]'::jsonb, 30),
  (36301, 'deadpool', null, null, 'HEADSHOT! - DUELIST UPGRADED', 'Ability', 'Juggle my noggin for extra throws! If you catch it thrice, it goes kaboom. Everyone gets a piece of my mind', '[{"label":"Key","value":"Right Click"},{"label":"Projectile Damage","value":"Unleash: 30; return: 25"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Spell Field Damage","value":"15/s"},{"label":"Third Unleash Explosion Damage","value":"45"},{"label":"Spell Field Duration","value":"First unleash: 1s; second unleash: 1s; third unleash: 2s"},{"label":"Cooldown","value":"10s"}]'::jsonb, 31)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36302, 'deadpool', null, null, 'POP QUIZ! - UPGRADED', 'Ultimate', 'Don''t just stand there, you blockhead! The challenge''s still rolling. But don''t worry, I''m not one of those money-hungry scam artists. The buffs are on the house, no price hike. Take on this challenge, and you''ll get three freebies: a little Speed boost, Continuous Healing, and Damage Up. Hit enough baddies with the right abilities exactly as I ask, and you unlock the ultimate bundle (Super Speed, Super Healing, Damage Boost AND reset all your cooldowns (except Healing Factor; no cheating!). Now THAT''S love', '[{"label":"Key","value":"Q"},{"label":"Ability Duration","value":"The challenge lasts 12s. The buff lasts 8s after you complete it."},{"label":"Healing Over Time","value":"Upon activation: 35/s; challenge completed: 70/s"},{"label":"Movement Boost","value":"Upon activation: 15%; challenge completed: 30%"},{"label":"Damage Boost","value":"Upon activation: 15%; challenge completed: 30%"},{"label":"Cooldown","value":"45s"}]'::jsonb, 32),
  (36303, 'deadpool', null, null, 'SKILL ISSUE - UPGRADED', 'Ultimate', 'Dumbpoochu, I choose you! Taunt time! Their HP melts away, and if they whiff an ability, they get bonus pain AND Vulnerability. Double whammy! Objection? Overruled!', '[{"label":"Key","value":"Q"},{"label":"Damage From Per Ability Missed","value":"60"},{"label":"Vulnerability Ration From Ability Missed","value":"10% for each stack. Up to 4 stacks."},{"label":"Ability Duration","value":"8s"},{"label":"Damage Over Time","value":"25/s"},{"label":"Cooldown","value":"45s"}]'::jsonb, 33),
  (36304, 'deadpool', null, null, 'DUAL DESERT EAGLES - STRATEGIST', 'Normal Attack', 'Nobody lays a finger on my teammates! Anyone tries, and I''m firing these big boy bullets straight at their face!', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Rapid-fire projectile"},{"label":"Damage","value":"25 damage per round"},{"label":"Healing","value":"45 per round"},{"label":"Fire Rate","value":"2.5 rounds per second"},{"label":"Ammo","value":"30"}]'::jsonb, 34),
  (36305, 'deadpool', null, null, 'PWNAGE POUND', 'Ultimate', 'You! Yeah, you - the hyper one! Eyes off my friends. I sentence you to...whatever! Get ready to be taunted. I get bonus HP and healing, and if you whiff your abilities, you take damage, and I get even more HP!', '[{"label":"Key","value":"Q"},{"label":"Damage From Per Ability Missed","value":"60"},{"label":"Ability Duration","value":"8s"},{"label":"Healing Over Time","value":"80/s"},{"label":"Healing From Per Ability Missed","value":"80 per ability missed"},{"label":"Healing Spell Field Range","value":"8m radius spherical spell field"},{"label":"Cooldown","value":"60s"}]'::jsonb, 35),
  (36306, 'deadpool', null, null, 'BOUNCING BOBBLEHEAD - STRATEGIST', 'Ability', 'Plushie power! It stops every single attack those chumps throw, giving my team a safety bubble. It''s cute AND bulletproof', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact that also generates a spell field"},{"label":"Projectile Damage","value":"Unleash: 20; return: 20"},{"label":"Projectile Healing","value":"Unleash: 40; return: 40"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Spell Field Damage","value":"10/s"},{"label":"Spell Field Healing","value":"50/s"},{"label":"Spell Field Range","value":"4m spherical radius spell field"},{"label":"Spell Field Duration","value":"1s"},{"label":"Cooldown","value":"8s"}]'::jsonb, 36),
  (36307, 'deadpool', null, null, 'HEALING HOP', 'Ability', 'Yup, I can double jump in midair! During The Big Test and its upgrade, I can also stomp heads and wall jump to reset its cooldown. Stomp enemies so hard they won''t get near my team!', '[{"label":"Key","value":"Space"},{"label":"Damage","value":"25"},{"label":"Healing","value":"35"},{"label":"Cooldown","value":"6s"},{"label":"Special Effect","value":"Refresh the cooldown if it hits an enemy or an ally. Transform the next katana base attack to a Stab."}]'::jsonb, 37),
  (36308, 'deadpool', null, null, 'DEADPOOL IN YOUR AREA - STRATEGIST', 'Ability', 'Want to hurt my team? Good luck! I hit you with a taunt, mess up your vision, and burn your health nonstop! Best part: my swords and guns go full turbo for the duration. Blink and you''ll miss it', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"10s"},{"label":"Ability Duration","value":"5s"},{"label":"Special Effect","value":"Disrupt enemies'' vision in range and gain XP. Enemies can damage Deadpool to end the disruption."},{"label":"Damage Needed To Remove The Disruption","value":"100"},{"label":"Spell Field Damage","value":"10/s"},{"label":"Spell Field Healing","value":"60/s"},{"label":"Spell Field Range","value":"A cylindrical spell field with a 6m radius and a height of 6m"}]'::jsonb, 38),
  (36309, 'deadpool', null, null, 'KICK@$$ KATANA - STRATEGIST', 'Normal Attack', 'Protecting my team means my katanas go full savage. No mercy for the baddies!', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"30 per hit"},{"label":"Attack Interval","value":"First strike: 0.6s; second strike: 0.53s; third strike: 0.6s"},{"label":"Maximum Distance","value":"4m"},{"label":"Healing Spell Field Range","value":"5m radius spherical spell field"},{"label":"Healing Amount","value":"32"}]'::jsonb, 39),
  (36310, 'deadpool', null, null, 'FINAL EXAM', 'Ultimate', 'Wake the #!&% up, hero! We''ve got a game to win! Speed and healing buffs for starters, bonus Healing Hijinks for me, and extra HP for me and my nearby friends. Hit enough baddies with the right abilities exactly as I ask, and you unlock mega speed and healing, plus reset my Healing Factor cooldown!. Team protection mode: activated!', '[{"label":"Key","value":"Q"},{"label":"Ability Duration","value":"The challenge lasts 12s. The buff lasts 6s after you complete it."},{"label":"Healing Amount","value":"Upon activation: 70/s; challenge completed: 100/s"},{"label":"Healing Spell Field Range","value":"8m radius spherical spell field"},{"label":"Cooldown","value":"60s"}]'::jsonb, 40),
  (36311, 'deadpool', null, null, 'HEALING HIJINKS - STRATEGIST', 'Ability', 'Try getting to my teammates, I dare you! My dash slash knocks fools down, and if I hit, I get to do it again. Up to three times, baby!', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"2 charges, with each charge taking 10s to recharge."},{"label":"Damage","value":"30"},{"label":"Dash Duration","value":"Up to 12m"},{"label":"Healing Amount","value":"45"},{"label":"Healing Spell Field Range","value":"5m spherical radius spell field"}]'::jsonb, 41),
  (36312, 'deadpool', null, null, 'HEALING HOP', 'Ability', 'Yup, I can double jump in midair! During Final Exam and its upgrade, I can also stomp heads and wall jump to reset its cooldown. Stomp enemies so hard they won''t get near my team!', '[{"label":"Key","value":"Space"},{"label":"Damage","value":"25"},{"label":"Healing","value":"35"},{"label":"Cooldown","value":"6s"},{"label":"Special Effect","value":"Refresh the cooldown if it hits an enemy or an ally. Transform the next katana base attack to a Stab."}]'::jsonb, 42),
  (36313, 'deadpool', null, null, 'DUAL DESERT EAGLES - STRATEGIST UPGRADED', 'Normal Attack', 'I rack up shots, then, BOOM! A mind-blowing bubble bomb for all the enemies. Teammate security: maximum', '[{"label":"Key","value":"Left Click"},{"label":"Beam Damage","value":"28"},{"label":"Beam Healing","value":"50"},{"label":"Beam Attack Interval","value":"2.5 rounds per second"},{"label":"Ammo","value":"40"},{"label":"Projectile Attack Interval","value":"After every 5 beam bullets fired, the next shot fires 1 additional projectile"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Projectile Healing","value":"15"},{"label":"Spell Field Healing","value":"40"},{"label":"Spell Field Damage","value":"20"},{"label":"Spell Field Range","value":"3m radius spherical spell field"}]'::jsonb, 43),
  (36314, 'deadpool', null, null, 'KICK@$$ KATANA - STRATEGIST UPGRADED', 'Ability', 'Relax, you''ve got Deadpool on your side! Swords out, baddies out. My stab hits crit, and a Healing Hop hit makes the next swing a stabby special', '[{"label":"Key","value":"Left Click"},{"label":"Damage","value":"35 per hit"},{"label":"Attack Interval","value":"First strike: 0.5s; second strike: 0.43s; third strike: 0.5s"},{"label":"Maximum Distance","value":"4m"},{"label":"Healing Spell Field Range","value":"8m radius spherical spell field"},{"label":"Healing Amount","value":"35"}]'::jsonb, 44),
  (36315, 'deadpool', null, null, 'DEADPOOL IN YOUR AREA - STRATEGIST UPGRADED', 'Ability', 'Teammates, stay safe! Dummies, look here! It''s showtime: I taunt, blind you, and hit warp speed with my swords and guns. Plus, my crew gets a damage reduction buff, so they''re basically invincible. Dummies that stick around too long will even have their UI taped over!', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"12s"},{"label":"Ability Duration","value":"5s"},{"label":"Special Effect","value":"Disrupt enemies'' vision in range and gain XP. Enemies can damage Deadpool to end the disruption."},{"label":"Damage Needed To Remove The Disruption","value":"100"},{"label":"Spell Field Healing","value":"70/s"},{"label":"Spell Field Damage","value":"10/s"},{"label":"Spell Field Range","value":"A cylindrical spell field with a 6m radius and a height of 6m."},{"label":"Damage Boost","value":"20%"}]'::jsonb, 45),
  (36316, 'deadpool', null, null, 'HEALING HIJINKS - STRATEGIST UPGRADED', 'Ability', 'Watch this pro bodyguard in action! I dash forward, nail the bad guy, and bounce in any direction I want. Oh, and I can do this two more times real quick!', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"2 charges, with each charge taking 10s to recharge."},{"label":"Special Effect","value":"Refresh the cooldown if it hits an enemy for up to 2 times. Deadpool bounces as the ability hits an enemy."},{"label":"Damage","value":"40"},{"label":"Dash Duration","value":"Up to 12m"},{"label":"Healing Spell Field Range","value":"8m radius spherical spell field"},{"label":"Healing Amount","value":"55"}]'::jsonb, 46),
  (36317, 'deadpool', null, null, 'BOUNCING BOBBLEHEAD - STRATEGIST UPGRADED', 'Ability', 'My ultra-cool, super shiny, extra huggable, and totally blinged-out plushy. Toss it ahead, and it lands as an invincible sphere of awesomeness! Blocking attacks and keeping my team safe inside our furry fortress', '[{"label":"Key","value":"Right Click"},{"label":"Projectile Damage","value":"Unleash: 25; return: 20"},{"label":"Projectile Healing","value":"Unleash: 45; return: 30"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Spell Field Damage","value":"10/s"},{"label":"Spell Field Healing","value":"55/s"},{"label":"Third Unleash Explosion Damage","value":"20"},{"label":"Third Unleash Explosion Healing","value":"70"},{"label":"Spell Field Duration","value":"First unleash: 1s; second unleash: 1s; third unleash: 2s"},{"label":"Cooldown","value":"8s"}]'::jsonb, 47),
  (36318, 'deadpool', null, null, 'FINAL EXAM - UPGRADED', 'Ultimate', 'Hey, player! Warm-up''s over, time for the main event! Speed, healing, dashes, for me, and bonus HP for all! Smash enough baddies with the skills I say, and you unlock super buffs(massive speed and healing), plus Healing Factor resets. For some time after, each hit means more HP for the crew and you. Don''t mess this up!', '[{"label":"Key","value":"Q"},{"label":"Ability Duration","value":"The challenge lasts 12s. The buff lasts 8s after you complete it."},{"label":"Healing Amount","value":"80/s upon activation; 120/s after completing the challenge"},{"label":"Healing Spell Field Range","value":"8m radius spherical spell field"},{"label":"Bonus Health From Completing The Challenge","value":"300"},{"label":"Cooldown","value":"60s"}]'::jsonb, 48),
  (36319, 'deadpool', null, null, 'PWNAGE POUND - UPGRADED', 'Ultimate', 'Upgraded courtroom drama! Congrats, unlucky one! You''re my pick; enjoy the taunt! I score bonus health and healing, and you take ongoing damage. If you miss an ability while court is in session, it''s a double whammy. You get more pain, AND I get more extra HP! Thanks in advance!', '[{"label":"Key","value":"Q"},{"label":"Damage From Per Ability Missed","value":"60"},{"label":"Ability Duration","value":"8s"},{"label":"Healing Over Time","value":"100/s"},{"label":"Healing From Per Ability Missed","value":"90 per ability missed"},{"label":"Healing Spell Field Range","value":"8m radius spherical spell field"},{"label":"Cooldown","value":"60s"}]'::jsonb, 49),
  (36320, 'deadpool', null, null, '"HEL-YEAH, HONEY"', 'Team-Up Ability', 'Base Effect: Receive upgrades from Hel, allowing the Desert Eagles or Katanas to be upgraded one additional time. Hel-Yeah Desert Eagles: Duelist and Vanguard gain pierce, and the thought bubbles transform into homing death-rattle bubbles. Strategist death-rattle bubbles also home in on allies, exploding to provide healing. Hel-Yeah Katanas: Every strike injects undead energy into the enemy. Hitting an enemy three times with the Katanas detonates the energy, dealing percentage-based true damage scaling off their max Health. Enhanced Effect: When teaming up with Hela, BOTH the Desert Eagles and Katanas can be upgraded one extra time.', '[{"label":"Key","value":"Passive"},{"label":"Vanguard Detonation Damage","value":"5 + 1.5% of target''s Max Health"},{"label":"Duelist Detonation Damage","value":"5 + 2% of target''s Max Health"},{"label":"Strategist Detonation Damage","value":"5 + 0.5% of target''s Max Health"},{"label":"Strategist Detonation Self-Healing","value":"5"},{"label":"Special Effect","value":"Both Desert Eagle and Katana can be further upgraded"}]'::jsonb, 50),
  (36321, 'deadpool', null, null, 'GUMBO CHIMICHANGAS', 'Team-Up Ability', 'Base Effect: Activate for kinetic energy, propelling Deadpool in a forward leap. Upon landing, he scatters a ring of kinetically charged chimichangas that deal damage to enemies. Enhanced Effect: When teaming up with Gambit, the kinetic energy causes Deadpool''s landing to inflict a Stun effect on enemies in the blast radius.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Vanguard Spell Field Damage","value":"60"},{"label":"Duelist Spell Field Damage","value":"90"},{"label":"Strategist Spell Field Damage","value":"35"},{"label":"Strategist Spell Field Healing","value":"65"},{"label":"Spell Field Range","value":"5m spherical radius"},{"label":"Stun Duration","value":"0.3s"},{"label":"Enhanced Cooldown","value":"10s"},{"label":"Enhanced Vanguard Spell Field Damage","value":"90"}]'::jsonb, 51),
  (36322, 'rogue', null, null, 'Power Surge Punch', 'Normal Attack', 'Punch forward with both fists', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"The first two strikes deal 35 damage, while the third strike deals 45 damage"},{"label":"Maximum Distance","value":"4.5m"},{"label":"Attack Speed","value":"The first two strikes: 0.33s/hit; the third strike: 0.73s/hit"}]'::jsonb, 0),
  (36323, 'rogue', null, null, 'Defensive Stance', 'Ability', 'Absorb nearby projectiles and reduce incoming damage; absorbed damage powers up your next Southern Brawl', '[{"label":"Key","value":"Right Click"},{"label":"Damage Reduction","value":"60%"},{"label":"Maximum Energy","value":"100"},{"label":"Energy Recovery Speed","value":"25/s"},{"label":"Energy Consumption","value":"60/s"},{"label":"Energy Required To Activate The Ability","value":"30"},{"label":"Special Effect","value":"The reduced damage transforms into backlash energy that powers up the next Southern Brawl."},{"label":"Reduced Damage-Backlash Energy Conversion Ratio","value":"0.55"},{"label":"Maximum Backlash Energy","value":"100"},{"label":"Maximum Backlash Energy Falloff","value":"20/s"}]'::jsonb, 1),
  (36324, 'rogue', null, null, 'Southern Brawl', 'Ability', 'While in Defensive Stance, dash forward and slam enemies in front, dealing area damage', '[{"label":"Key","value":"Left Click"},{"label":"Dash Distance","value":"8m"},{"label":"Base Damage","value":"40"},{"label":"Backlash Energy-Extra Damage Conversion Ratio","value":"0.75"},{"label":"Special Effect","value":"Launch up the enemies hit"},{"label":"Maximum Distance","value":"8m"},{"label":"Cooldown","value":"6s"}]'::jsonb, 2),
  (36325, 'rogue', null, null, 'Chrono Kick Combo', 'Ability', 'Dash forward and launch the enemy, entering flight; activate again to Knock Down nearby enemies. Your next two Power Surge Punch attacks become ranged, piercing enemies and granting Bonus Health', '[{"label":"Key","value":"E"},{"label":"Spell Field Range","value":"Box shaped spell field. Length: 6.5m; Width: 4.5m; Height: 2m"},{"label":"Spell Field Damage","value":"30"},{"label":"Special Effect","value":"Launch up the enemy hit, entering flight. The next two Power Surge Punch attacks become ranged, and Chrono Kick Combo can be unleashed again."},{"label":"Maximum Flight Duration","value":"3s"},{"label":"Knock Down Spell Field Damage","value":"30"},{"label":"Knock Down Spell Field Range","value":"6m radius spherical spell field"},{"label":"Projectile Damage","value":"60"},{"label":"Projectile Speed","value":"100 m/s"},{"label":"Projectile Maximum Flying Distance","value":"20m"},{"label":"Cooldown","value":"10s"}]'::jsonb, 3),
  (36326, 'rogue', null, null, 'Fatal Attraction', 'Ability', 'Dash forward. Press again to unleash a burst of Chronovium Power, dealing continuous damage to nearby foes; after a delay, the energy retracts, pulling all enemies towards Rogue', '[{"label":"Key","value":"SHIFT"},{"label":"Dash Distance","value":"10m"},{"label":"Dash Damage","value":"30"},{"label":"Special Effect","value":"Launch up enemies hit"},{"label":"Spreading Spell Field Range","value":"Cylindrical Spell Field with a height of 3m, whose radius will expand to 8m after 0.8s"},{"label":"Spreading Spell Field Damage","value":"40/s"},{"label":"Retrieve Spell Field Damage","value":"30"},{"label":"Cooldown","value":"12s"}]'::jsonb, 4)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36327, 'rogue', null, null, 'Ability Absorption', 'Ability', 'Dash forward to knock down your target and absorb their energy; after absorbing, replace Ability Absorption with one of their abilities or refresh Fatal Attraction. Also absorb Health and stats based on their role', '[{"label":"Key","value":"F"},{"label":"Dash Distance","value":"10m"},{"label":"Special Effect","value":"Knock down the target. Rogue becomes Unstoppable during the absorption."},{"label":"Absorption Damage Over Time","value":"30/s"},{"label":"Absorption Healing Over Time","value":"60/s"},{"label":"Absorbed Ability Duration","value":"10s"},{"label":"Boost From Vanguard Ability Absorption","value":"150 Maximum Health"},{"label":"Debuff To The Vanguard Absorption Target","value":"Reduce 20 Maximum Health"},{"label":"Boost From Duelist Ability Absorption","value":"20% Damage Boost"},{"label":"Debuff To The Duelist Absorption Target","value":"Reduce 3% damage dealt"},{"label":"Boost From Strategist Ability Absorption","value":"Self healing 20/s"},{"label":"Debuff To The Strategist Absorption Target","value":"Reduce 4% healing dealt"},{"label":"Absorption Process","value":"0.75s"},{"label":"Special Effect","value":"After absorbing, replace Ability Absorption with one of their abilities or refresh Fatal Attraction."},{"label":"Cooldown","value":"25s"}]'::jsonb, 5),
  (36328, 'rogue', null, null, 'Heartbreaker', 'Ultimate', 'Continuously absorb Ultimate Ability Energy from nearby enemies and steal stats based on their role', '[{"label":"Key","value":"Q"},{"label":"Duration","value":"8s"},{"label":"Energy Cost","value":"3400"},{"label":"Ultimate Ability Energy Absorption Speed","value":"Absorb 4% of ultimate ability energy per second"},{"label":"Maximum Stats Stolen From Vanguards","value":"400 maximum health"},{"label":"Maximum Stats Stolen From Duelists","value":"35% damage boost"},{"label":"Maximum Stats Stolen From Strategists","value":"Self healing 75/s"},{"label":"Spell Field Range","value":"8m radius spherical spell field"},{"label":"Spell Field Damage","value":"15/s"}]'::jsonb, 6),
  (36329, 'rogue', null, null, 'HEARTS AS ONE', 'Team-Up Ability', 'Gambit shares kinetic energy with Magneto and Rogue. When Magneto activates this ability, Iron Volley is replaced with Ace Greatsword, which detonates upon striking enemies. The explosion leaves residual kinetic energy within the target, inflicting secondary damage after a brief delay. When Rogue activates the ability, each of her attacks causes a kinetic explosion that damages nearby enemies and heals nearby allies', '[{"label":"Key","value":"C"},{"label":"Spell Field Duration","value":"8s"},{"label":"Cooldown","value":"30s"},{"label":"Spell Field Damage","value":"5+targets'' 2% Maximum Health"},{"label":"Spell Field Healing","value":"25"},{"label":"Spell Field Range","value":"8m radius spherical spell field"}]'::jsonb, 7),
  (36330, 'rogue', null, null, 'MR. & MRS. X', 'Team-Up Ability', 'Base Effect: After activation, every attack triggers a kinetic explosion, dealing area damage to surrounding enemies while simultaneously healing nearby allies. Enhanced Effect: When teaming up with Gambit, Rogue remains permanently locked in the "Hearts as One" state.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"30s"},{"label":"Duration","value":"8s"},{"label":"Spell Field Range","value":"8m spherical radius"},{"label":"Damage","value":"5+Target''s 1% Maximum Health"},{"label":"Healing","value":"15"},{"label":"Enhanced Key","value":"Passive"},{"label":"Special Effect","value":"Permanently maintains the Hearts as One state"}]'::jsonb, 8),
  (36331, 'rogue', null, null, 'EXPLOSIVE ENTANGLEMENT', 'Team-Up Ability', 'Base Effect: Defensive Stance is fortified. Activating the ability expands a magnetic field, drastically boosting the Damage Reduction ratio of Defensive Stance. Furthermore, all damage absorbed by the field is converted directly into damage for Southern Brawl. Enhanced Effect: When teaming up with Magneto, Southern Brawl Knocks back enemies. Extra damage is dealt if they''re propelled into a wall.', '[{"label":"Key","value":"Passive"},{"label":"Damage Reduction","value":"75%"},{"label":"Wall Collision Bonus Damage","value":"60"}]'::jsonb, 9),
  (36332, 'gambit', null, null, 'Kinetic Cards', 'Normal Attack', 'Launch three kinetic-charged cards in an arc ahead. Each card detonates on impact, creating a single-target explosion that damages enemies and heals allies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Projectile that fires in a straight trajectory"},{"label":"Cards Launched Per Unleash","value":"3 cards per unleash"},{"label":"Angle Between The Side Cards And The Center Card","value":"2°"},{"label":"Card Damage","value":"20 damage per round"},{"label":"Card Healing","value":"30 health per round"},{"label":"Fire Rate","value":"0.45s per round"},{"label":"Ammo","value":"21"},{"label":"Critical Hit","value":"No"},{"label":"Projectile Speed","value":"150 m/s"},{"label":"Maximum Distance","value":"60m"}]'::jsonb, 0),
  (36333, 'gambit', null, null, 'Ragin'' Royal Flush', 'Ultimate', 'Lock onto an ally within sight and unleash multiple Aces that heal and Purify. Both enter the Kinetic Transfer state, granting increased Movement Speed and Jump Boost, while enhancing attacks with additional single-target explosive damage and providing the ally with Ultimate Ability Charge Acceleration', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Targeted"},{"label":"Energy Cost","value":"4500"},{"label":"Range","value":"Cone shape spell field, angle range: 110°, length: 30m"},{"label":"Special Effect","value":"Gambit and the targeted ally receive the Purify and Jump Boost effect."},{"label":"One-Time Healing","value":"100"},{"label":"Movement Speed Boost Ratio","value":"30%"},{"label":"Enhanced Damage Ratio","value":"20%"},{"label":"Damage Trigger Interval","value":"0.5s"},{"label":"Healing Over Time","value":"55/s"},{"label":"Ultimate Abilities Charge Acceleration Ratio","value":"20%"},{"label":"Spell Field Duration","value":"8s"}]'::jsonb, 1),
  (36334, 'gambit', null, null, 'Cajun Charge', 'Ability', 'Side-step forward with bo staff in hand, dashing a short distance', '[{"label":"Key","value":"Shift"},{"label":"Casting","value":"Dash"},{"label":"Cooldown","value":"2 charges, with each charge taking 12.5s to recharge."},{"label":"Dash Duration","value":"8m"}]'::jsonb, 2),
  (36335, 'gambit', null, null, 'Healing Hearts', 'Ability', 'Conjure a Heart card by consuming one stack of Sleight of Hand to Heal and switch to the Healing Hearts deck', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"4 charges, with each charge taking 7s to recharge."},{"label":"Self Healing","value":"Heal 30 health per second within duration"},{"label":"Maximum Duration","value":"6s"},{"label":"Special Effect","value":"Within the duration, consume one stack of Sleight of Hand to use Bridge Boost and Purifying Pick-Up."}]'::jsonb, 3),
  (36336, 'gambit', null, null, 'Breaking Spades', 'Ability', 'Conjure a Spade card by consuming one stack of Sleight of Hand to gain Damage Boost and switch to the Breaking Spades deck', '[{"label":"Key","value":"F"},{"label":"Cooldown","value":"4 charges, with each charge taking 7s to recharge"},{"label":"Self Damage Boost","value":"10%"},{"label":"Maximum Duration","value":"6s"},{"label":"Special Effect","value":"Within the duration, consume one stack of Sleight of Hand to use Explosive Trick and Bidding Barrage"}]'::jsonb, 4),
  (36337, 'gambit', null, null, 'Bayou Bash', 'Ability', 'Channel kinetic energy into the bo staff, then slam it into the ground after a sweeping strike, creating a shockwave that damages nearby enemies and heals allies', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast spell field that surrounds the caster"},{"label":"Cooldown","value":"2 charges, with each charge taking 8s to recharge"},{"label":"Spell Field Range","value":"5m spherical radius"},{"label":"Damage","value":"60"},{"label":"Healing","value":"To allies: 60; self: 60"},{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Dash"},{"label":"Dash Distance","value":"12m"},{"label":"Spell Field Generation Quantity","value":"3"},{"label":"Spell Field Generation Interval","value":"0.1"},{"label":"Range","value":"5m spherical radius"},{"label":"Damage","value":"25 per field"},{"label":"Healing","value":"To allies and self: 15/hit"}]'::jsonb, 5),
  (36338, 'gambit', null, null, 'ACE OF ACES', 'Team-Up Ability', 'Gambit charges Magneto''s greatsword with kinetic energy. When Magneto activates this ability, Iron Volley is replaced with Ace Greatsword, which detonates upon striking enemies. The explosion leaves residual kinetic energy within the target, inflicting secondary damage after a brief delay', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"5% Healing Boost"}]'::jsonb, 6),
  (36339, 'gambit', null, null, 'Bridge Boost', 'Ability', 'While Healing Hearts deck is active, trigger Flush Empowerment to card spring and fire a full deck forward. Cards bounce between allies on impact, granting Health and a Healing Boost', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Projectile that fires in a straight trajectory."},{"label":"Special Effect","value":"The projectile automatically tracks allies and will bounce between allies on impact. Bridge Boost bounces on a single target are set to a maximum of 2"},{"label":"Projectile Speed","value":"120m/s"},{"label":"Max Number Of Ricochets","value":"6"},{"label":"Healing","value":"55 per round"},{"label":"Healing Boost Ratio","value":"0.15"},{"label":"Duration","value":"4s"}]'::jsonb, 7),
  (36340, 'gambit', null, null, 'Purifying Pick-Up', 'Ability', 'While Healing Hearts deck is active, trigger Raise Empowerment to launch a cluster of cards in an arc ahead. Explosions heal nearby allies and Purify them', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Projectile that generates a spell field upon impact."},{"label":"Number Of Generated Projectiles","value":"10"},{"label":"Projectile Speed","value":"100 m/s"},{"label":"Maximum Distance","value":"15m"},{"label":"Spell Field Range","value":"5m spherical radius"},{"label":"Spell Field Healing","value":"70 per field"},{"label":"Special Effect","value":"The spell field applies Purify to allies upon impact. This can take effect on allies a maximum of 2 times and on himself once."}]'::jsonb, 8),
  (36341, 'gambit', null, null, 'Explosive Trick', 'Ability', 'While Breaking Spades deck is active, trigger Flush Empowerment to fire a full set of cards forward. Cards explode on impact, dealing damage while inflicting Reduced Healing', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"150 m/s"},{"label":"Spell Field Range","value":"5m spherical radius"},{"label":"Damage","value":"70"},{"label":"Reduced Healing Ratio","value":"0.25"},{"label":"Reduced Healing Duration","value":"4s"}]'::jsonb, 9),
  (36342, 'gambit', null, null, 'Bidding Barrage', 'Ability', 'While Breaking Spades deck is active, trigger Raise Empowerment to scattering cards in an arc in all directions. Explosions damage enemies and Launch them up', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Projectile that generates a spell field upon impact"},{"label":"Number Of Projectiles","value":"10"},{"label":"Projectile Speed","value":"100 m/s"},{"label":"Maximum Distance","value":"15m"},{"label":"Spell Field Range","value":"5m spherical radius"},{"label":"Damage","value":"70"},{"label":"Special Effect","value":"Launch enemies up on hit, which can take effect only once."}]'::jsonb, 10),
  (36343, 'gambit', null, null, 'FAVORABLE ODDS', 'Team-Up Ability', 'Base Effect: Throw two magnetic playing cards forward. Upon hitting the environment or a character, the two cards magnetically repel and unfurl, spinning in place for a duration. They heal allies they hit, while damaging and Launchingenemies. Enhanced Effect: When teaming up with Magneto, after the duration ends, the magnetic poles of the two cards reverse. They violently slam back together and explode, providing an extra burst of healing to allies and damage to enemies.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Spell Field Range","value":"5m spherical radius"},{"label":"Spell Field Duration","value":"5s"},{"label":"Healing Amount","value":"55/s"},{"label":"Damage","value":"50/s"},{"label":"One-Time Damage","value":"40"},{"label":"One-Time Healing","value":"60"}]'::jsonb, 11),
  (36344, 'gambit', null, null, 'SPARKLING STAFF', 'Team-Up Ability', 'Base Effect: Twirl your firework-energy enhanced bo staff. The radiating firework sparks provide healing to nearby allies. Concurrently, the staff deals damage to close-range enemies, and the rapid spinning blocks incoming damage from most projectiles. Enhanced Effect: When teaming up with Jubilee, both Bayou Bashand Big Easy Impactgain an additional Continuous Healingaura.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Duration","value":"2s"},{"label":"Damage Spell Field Range","value":"5m spherical radius"},{"label":"Damage","value":"45/s"},{"label":"Healing Spell Field Range","value":"8m spherical radius spell field"},{"label":"Healing Amount","value":"70/s"},{"label":"Enhanced Key","value":"Passive"},{"label":"Bonus Healing","value":"10/s for 3s"}]'::jsonb, 12),
  (36345, 'daredevil', null, null, 'JUSTICE JAB', 'Normal Attack', 'Swing Billy Clubs forward. Gain Fury on hit', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"35"},{"label":"Maximum Distance","value":"4.5m"},{"label":"Special Effect","value":"Gain 15 Fury on hit"}]'::jsonb, 0),
  (36346, 'daredevil', null, null, 'RIGHTEOUS CROSS', 'Normal Attack', 'Cross your Billy Clubs and surge forward. Gain Fury on hit', '[{"label":"Key","value":"Left Click"},{"label":"Maximum Dash Distance","value":"6m"},{"label":"Spell Field Damage","value":"50"},{"label":"Spell Field Maximum Distance","value":"6m"},{"label":"Special Effect","value":"Gain 15 Fury on hit"}]'::jsonb, 1),
  (36347, 'daredevil', null, null, 'OBJECTION!', 'Ability', 'Whirl billy clubs in a tight guard to block frontal damage and reflect projectiles, becoming immune to all incoming harm during this stance and gain Fury', '[{"label":"Key","value":"Right Click"},{"label":"Duration","value":"1.2s"},{"label":"Cooldown","value":"12s"},{"label":"Special Effect","value":"Block frontal damage and reflect projectiles, becoming immune to all incoming harm during this stance. Gain 60 Fury when successfully blocking an attack."}]'::jsonb, 2),
  (36348, 'daredevil', null, null, 'DEVIL''S LATCH', 'Ability', 'Fire a grappling line that reels Daredevil and his target toward each other. On completion, gain Fury and temporarily enables Cross Interrogation', '[{"label":"Key","value":"SHIFT"},{"label":"Cooldown","value":"12"},{"label":"Maximum Distance","value":"25m"},{"label":"Projectile Speed","value":"180m/s"},{"label":"Special Effect","value":"Enable Righteous Cross within 5 seconds after using this ability. Gain 30 Fury"}]'::jsonb, 3),
  (36349, 'daredevil', null, null, 'INFERNAL FURY', 'Ability', 'Expend Fury to unleash Devil''s Chain or Devil''s Throw. Devil''s Chain converts damage into Bonus Health, while Devil''s Throw Slows enemies on hit and temporarily enables Cross Interrogation', '[{"label":"Key","value":"E"},{"label":"Special Effect","value":"During the activation, Daredevil can unleash Devil''s Chain or Devil''s Throw. Enable Righteous Cross within 5 seconds after using this ability"},{"label":"Fury Required For Activation","value":"60"},{"label":"Bonus Max Health","value":"100"},{"label":"Bonus Health Falloff","value":"Falloff begins at 5s and decreases by 30/s"},{"label":"Key","value":"Left Click"},{"label":"Spell Field Range","value":"Box shaped spell field. Length: 8m; Width: 4m; Height: 4m"},{"label":"High Damage Spell Field Range","value":"2m spherical radius spell field at the end"},{"label":"Damage/Bonus Health Conversion","value":"0.7"},{"label":"Bonus Health Gained","value":"25"},{"label":"Damage","value":"40. Cause 65 damage when the target caught in the high damage range"},{"label":"Key","value":"Right Click"},{"label":"Projectile Speed","value":"150m/s"},{"label":"Projectile Damage","value":"30"},{"label":"Max Number Of Ricochets","value":"4. Up to 2 ricochets if there are no targets"},{"label":"Special Effect","value":"Devil''s Throw slows enemies on hit"},{"label":"Slow Rate","value":"20%"},{"label":"Bonus Health Gained","value":"50"}]'::jsonb, 4),
  (36350, 'daredevil', null, null, 'Sonic Pursuit', 'Ability', 'Locks onto a target, gaining increased Speed; and Damage Reduction when attacked. While in range, dash to the target, Blinding them and restore Fury', '[{"label":"Key","value":"F"},{"label":"Movement Boost","value":"2.1m/s. Falloff begins at 10m away from the target, decreasing to 0.9m/s at 40m from the target"},{"label":"Self Damage Reduction","value":"10%"},{"label":"Select Range","value":"40m"},{"label":"Dash Cooldown","value":"15s"},{"label":"Dash Select Range","value":"12m"},{"label":"Max Dash Speed","value":"100m/s"},{"label":"Dash Damage Range","value":"1m spherical radius spell field"},{"label":"Dash Damage","value":"20"},{"label":"Special Effect","value":"If Daredevil defeats the target, refresh the cooldown. Gain 60 Fury after the dash"}]'::jsonb, 5),
  (36351, 'daredevil', null, null, 'RADAR SENSE', 'Passive', 'Detect enemy movements within a set radius', '[{"label":"Key","value":"Passive"},{"label":"Maximum Detection Distance","value":"40m"}]'::jsonb, 6)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36352, 'daredevil', null, null, 'BLIND ASCENT', 'Ability', 'Run along walls and spring off them to reposition', '[{"label":"Key","value":"Space"},{"label":"Wall-Crawling Speed","value":"10 m/s"}]'::jsonb, 7),
  (36353, 'daredevil', null, null, 'LET THE DEVIL OUT', 'Ultimate', 'Embrace the Beast within. Enemies in Daredevil''s line of sight take damage and suffer a ramping Blind effect. Continually gain Fury while active', '[{"label":"Key","value":"Q"},{"label":"Time Required To Reach The Maximum Blind Range And Damage","value":"3s"},{"label":"Spell Field Duration","value":"8s"},{"label":"Maximum Distance","value":"15m"},{"label":"Energy Cost","value":"3400"},{"label":"Damage","value":"50/s. Cause 85 damage per second when reaching the max damage"},{"label":"Blind Effect","value":"Visual range 35m, decreasing to 10m when the Blind effect reaches its maximum"},{"label":"Fury Recovery Speed","value":"30/s"}]'::jsonb, 8),
  (36354, 'daredevil', null, null, 'BLIND VERDICT', 'Team-Up Ability', 'Daredevil shares the location of his Sonic Pursuit target with The Punisher. At the same time, The Punisher can launch a devil-infused shock grenade to damage and blind enemies', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"5% damage boost"}]'::jsonb, 9),
  (36355, 'daredevil', null, null, 'COMPREHENSIVE DEFENSE', 'Team-Up Ability', 'Base Effect: Objection! is enhanced. Whirling billy clubs now damage all enemies in range while deflecting Projectiles from all directions. Successfully deflecting attacks recovers Fury. Enhanced Effect: When teaming up with Iron Fist, Daredevil passively recovers Health for the entire duration of the ability.', '[{"label":"Key","value":"Right Click"},{"label":"Special Effect","value":"Deflects projectiles from all directions while becoming invincible"},{"label":"Healing Amount","value":"60/s"}]'::jsonb, 10),
  (36356, 'daredevil', null, null, 'DEVILISH AFFAIR', 'Team-Up Ability', 'Base Effect: Swings Devil''s Chain in a criss-cross pattern, dealing damage to enemies in front and inflicting a Slow. Enhanced Effect: When teaming up with Black Widow, the damage radius is expanded, and landing hits recovers Fury.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Spell Field Range","value":"8.5m radius, 5m tall, 120° cone spell field"},{"label":"Damage","value":"55"},{"label":"Slow Rate","value":"40% for 1.5s"},{"label":"Enhanced Spell Field Range","value":"8.5m radius, 5m tall, 180° cone spell field"}]'::jsonb, 11),
  (36357, 'angela', null, null, 'Spear of Ichors', 'Normal Attack', 'Lunge forward with your spear, dealing damage that increases with Attack Charge. At full charge, Spear of Ichor can launch up enemies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"45"},{"label":"Charge-Damage Conversion Ratio","value":"35%"},{"label":"Maximum Distance","value":"7m"},{"label":"Attack Interval","value":"0.96s per hit"},{"label":"Special Effect","value":"At full charge, Spear of Ichor can launch up enemies and cause 20 extra damage."}]'::jsonb, 0),
  (36358, 'angela', null, null, 'Axes Of Ichors', 'Normal Attack', 'Alternate powerful strikes forward with twin axes, dealing increased damage as Attack Charge grows. The fourth strike propels you forward in a swift dash', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"First three strikes: 30; the forth strike: 50."},{"label":"Charge-Damage Conversion Ratio","value":"45%"},{"label":"Maximum Distance","value":"4m"},{"label":"Attack Interval","value":"First three strikes: 0.4s per hit; the forth strike: 0.6s per hit."},{"label":"Special Effect","value":"The fourth strike propels you forward in a swift dash."}]'::jsonb, 1),
  (36359, 'angela', null, null, 'SHIELDED STANCE', 'Ability', 'Transform Ichors into a shield, gaining Attack Charge when absorbing damage', '[{"label":"Key","value":"Right Click"},{"label":"Maximum Shield Value","value":"350"},{"label":"Cooldown","value":"1s"},{"label":"Cooldown After Destroyed","value":"4s"},{"label":"Delayed Recovery After Release","value":"2s"},{"label":"Recovery Speed","value":"60/s"},{"label":"Damage Resisted-Charge Conversion Ratio","value":"35%"}]'::jsonb, 2),
  (36360, 'angela', null, null, 'Seraphic Soar', 'Passive', 'Glide freely through the air. Continuous flight builds Attack Charge', '[{"label":"Key","value":"PASSIVE"},{"label":"Time Required To Enter Glide","value":"0.1s"},{"label":"Glide Activation Condition","value":"Maintain the forward speed faster than 5m/s for 1s"},{"label":"Glide Speed","value":"10m/s"},{"label":"Passive Energy Gained During Glide","value":"22.2/s"}]'::jsonb, 3),
  (36361, 'angela', null, null, 'Divine Judgement', 'Ability', 'Dive downward, switch to twin axes and infuse the ground with Ichors to create a Divine Judgement Zone upon impact. Within the zone, gain enhanced Speed and attacks grant Bonus Health to self and nearby allies', '[{"label":"Key","value":"E"},{"label":"Damage","value":"Hit damage: 30; damage over time: 12.5/s"},{"label":"Damage Over Time Spell Field Range","value":"A cylindrical spell field with a radius of 8m and a height of 2m."},{"label":"Cooldown","value":"12s"},{"label":"Movement Boost (Self)","value":"35%"},{"label":"Spell Field Duration","value":"6s"},{"label":"Bonus Health","value":"Within the Divine Judgement zone, Angela’s each Axes of Ichors hit grants 50 Bonus Health to herself and 25 Bonus Health to allies within the area."},{"label":"Bonus Max Health","value":"200"}]'::jsonb, 4),
  (36362, 'angela', null, null, 'Wingblade Ascent', 'Ability', 'Take to the skies, switching back to Spear of Ichors', '[{"label":"Key","value":"E"},{"label":"Ascent Height","value":"8m"},{"label":"Ascent Duration","value":"0.35s"},{"label":"Ascent Elevation Angle","value":"60°"}]'::jsonb, 5),
  (36363, 'angela', null, null, 'Assassin''s Charge', 'Ability', 'Enter an accelerated dash state, enemies struck head-on are carried through the air for a short distance', '[{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"4s"},{"label":"Maximum Energy","value":"100"},{"label":"Energy Recovery Speed","value":"12.5/s"},{"label":"Energy Cost","value":"25/s; 75/s when piercing an enemy"},{"label":"One-Time Energy Cost","value":"20"},{"label":"Energy Required To Activate The Ability","value":"30"},{"label":"Recover Delay","value":"2"},{"label":"Dash State Speed","value":"18 m/s"},{"label":"Maximum Enemies Could Be Carried","value":"2"},{"label":"Passive Energy Gained During The Dash","value":"25/s"},{"label":"Special Effect","value":"Every enemy pierced grants Angela with a 50/s passive energy recovery."},{"label":"Piercing Damage","value":"30"}]'::jsonb, 6),
  (36364, 'angela', null, null, 'Heven''s Retribution', 'Ultimate', 'Wrap your spear in ribbons and hurl it with force. Upon impact, the ribbons bind nearby enemies. Angela can leap to the spear''s location, damaging surrounding enemies and creating a Divine Judgement Zone', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"3100"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Spell Field Damage","value":"40"},{"label":"Spell Field Range","value":"8m spherical radius"},{"label":"Hit Ground Damage","value":"100"},{"label":"Hit Ground Spell Field Range","value":"8m spherical radius"},{"label":"Special Effect","value":"Mobility abilities of enemies bound by the ribbons will be disabled. Enemies within a certain distance around the spear will be slowed."},{"label":"Slow Rate","value":"80%"},{"label":"Projectile Damage","value":"30"},{"label":"Summons'' Health","value":"650"}]'::jsonb, 7),
  (36365, 'angela', null, null, 'Celestial Command', 'Team-Up Ability', 'Angela shares fragments of her Ichors with Thor, empowering him to hurl a Thunder Spear that restores Thorforce for each enemy struck. Afterward, Thor can leap to the spear''s explosion point, dealing a second wave of damage to all enemies within range', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"+100 Max Health"}]'::jsonb, 8),
  (36366, 'angela', null, null, 'ASGARDIANS OF THE GALAXY', 'Team-Up Ability', 'Base Effect: Activation grants Reveal within a targeted area. Activating the ability again performs a slam attack; enemies hit by the slam are Grounded. Enhanced Effect: When teaming up with Star-Lord, Angela gains Bonus Health scaling with the number of enemies struck by the slam.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"25s"},{"label":"Reveal Spell Field Range","value":"50m spherical radius spell field"},{"label":"Ground Slam Spell Field Range","value":"10m spherical radius spell field"},{"label":"Ground Slam Damage","value":"65"},{"label":"Ground Bind Duration","value":"2s"},{"label":"Bonus Health","value":"Gain 75 Bonus Health per target hit, up to 200"}]'::jsonb, 9),
  (36367, 'angela', null, null, 'ODIN''S UNACKNOWLEDGED', 'Team-Up Ability', 'Base Effect: Project an Illusion forward. The illusion utilizes Assassin''s Charge to thrust at enemies. Enemies struck head-on will be carried through the air for a short while. Enhanced Effect: When teaming up with Loki, the ability gains two charges.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Illusion Max Damage Absorbed","value":"150"},{"label":"Special Effect","value":"The ability gains 2 charges"}]'::jsonb, 10),
  (36368, 'blade', null, null, 'Ancestral Sword', 'Normal Attack', 'Slash forward with Blade''s Ancestral Sword', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"Cause 26 damage per single slash; double strike cause 13 damage per hit"},{"label":"Maximum Distance","value":"5m"},{"label":"Attack Interval","value":"2 strikes per second"}]'::jsonb, 0),
  (36369, 'blade', null, null, 'Hunter''s Shotgun', 'Normal Attack', 'Fire at enemies using your Shotgun', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Projectile that fires in a straight trajectory, which breaks into shrapnel after reaching a certain distance"},{"label":"Initial Projectile Maximum Distance","value":"8m"},{"label":"Initial Projectile Speed","value":"180 m/s"},{"label":"Initial Projectile Damage","value":"45"},{"label":"Shrapnel Amount","value":"11"},{"label":"Damage Per Shrapnel Hit","value":"8"},{"label":"Shrapnel Projectile Speed","value":"150 m/s"},{"label":"Shrapnel Damage Falloff","value":"Falloff begins at 15m, decreasing to 50% at 30m"}]'::jsonb, 1),
  (36370, 'blade', null, null, 'Scarlet Shroud', 'Ability', 'Parry with Ancestral Sword to become Unstoppable for a brief period, reducing damage taken from the front and decreasing the cooldown of Daywalker Dash', '[{"label":"Key","value":"Right Click"},{"label":"Maximum Energy","value":"120"},{"label":"Energy Cost","value":"60/s"},{"label":"Energy Recovery Speed","value":"15/s"},{"label":"Activation Cost","value":"15"},{"label":"Cooldown","value":"3s"},{"label":"Unstoppable Duration","value":"1s after activation"},{"label":"Damage Reduction","value":"80%"},{"label":"Special Effect","value":"Every 200 damage resisted grants 1 charge for Daywalker Dash"}]'::jsonb, 2),
  (36371, 'blade', null, null, 'Bloodline Awakening', 'Ability', 'Awaken the Dhampir bloodline, enhancing slash speed during continuous attacks and triggering Whirlwind Slash.If all Whirlwind Slash strikes hit, your Attack Speed will further increase. While under this state, you suffer Reduced Healing, but attacks gain Lifesteal', '[{"label":"Key","value":"E"},{"label":"Special Effect","value":"Left Click/Shift key ability hits accumulate attack speed buff levels; within the Bloodline Awakening duration, attacks gain Lifesteal and movement speed boost but suffer Reduced Healing"},{"label":"Lifesteal Proportion","value":"70%, Affected by Healing Reduction"},{"label":"Self Reduce Healing Proportion","value":"25%"},{"label":"Movement Speed Boost","value":"1.5 m/s"},{"label":"Max Attack Speed Boost Buff Stack","value":"10"},{"label":"Left Click Hit Buff Stack","value":"1"},{"label":"Shift Hit Buff Stack","value":"5"},{"label":"Attack Speed Boost Proportion From Each Buff Stack","value":"10%"},{"label":"Duration Of Each Buff Stack","value":"1s"},{"label":"Whirlwind Slash Damage","value":"64"},{"label":"Hits To Trigger The Whirlwind Slash","value":"5"},{"label":"Special Effect","value":"Landing all four hits of Whirlwind Slash grants 1 slash speed stack; Excess lifesteal grants Bonus Health( max 75; conversion rate 50%)"}]'::jsonb, 3),
  (36372, 'blade', null, null, 'Daywalker Dash', 'Ability', 'Dash forward. If wielding your gun, shoot at enemies upon impact, applying a Healing Reduction effect. If wielding your sword, deliver a cleaving strike that inflicts Slow', '[{"label":"Key","value":"Shift"},{"label":"Casting","value":"Dash. Cause damage and special effects to the enemies hit"},{"label":"Dash Distance","value":"15m"},{"label":"Damage","value":"30"},{"label":"Special Effect","value":"Hit while wielding the gun, inflict Slow effect to the enemy; hit while wielding the sword, deal Healing Reduction to the enemy"},{"label":"Healing Reduction Proportion","value":"apply 8% Healing Reduction per strike (32% total if all hit)"},{"label":"Healing Reduction Duration","value":"4s"},{"label":"Slow Rate","value":"40%"},{"label":"Slow Duration","value":"1.5s"},{"label":"Gun Second Hit Damage","value":"50"},{"label":"Sword Second Hit Damage","value":"10 per hit, 4 hits in total"},{"label":"Second Hit Damage Range","value":"6.5m"}]'::jsonb, 4),
  (36373, 'blade', null, null, 'Thousand-Fold Slash', 'Ultimate', 'Charge power and swiftly draw the Sword of Dracula, executing a powerful Iaido strike as you dash forward, leaving behind a slashing zone where the sword automatically strikes enemies. Enemies hit suffer Reduced Healing', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"2800"},{"label":"Self Slow","value":"25%"},{"label":"Maximum Charge Time","value":"3s"},{"label":"Charge Time For Max Distance","value":"1s"},{"label":"Dash Distance","value":"10m, maximum distance 24m after fully charged."},{"label":"Direct Hit Damage","value":"100"},{"label":"Spell Field Damage Over Time","value":"225/s"},{"label":"Spell Field Range","value":"Length: Maximum dash distance; Width: 6m; Height: 4.5m"},{"label":"Spell Field Duration","value":"2s"},{"label":"Healing Reduction Proportion","value":"20%"},{"label":"Healing Reduction Duration","value":"4s"}]'::jsonb, 5),
  (36374, 'blade', null, null, 'ECLIPSE EDGE', 'Team-Up Ability', 'Blessed by Khonshu, Blade gains a new ability. When activated, Blade swings his Ancestral Sword in a powerful slash, dashing forward a short distance. At the end of the dash, he swiftly slashes four times, each strike sending a Darkmoon Blade forward. When a Darkmoon Blade hits an enemy, it bounces to nearby targets', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Dash Duration","value":"8m"},{"label":"Dash Damage","value":"30"},{"label":"Number Of Projectiles","value":"4"},{"label":"Projectile Speed","value":"150m/s"},{"label":"Damage","value":"40"},{"label":"Bounce Range","value":"8m"},{"label":"Damage Falloff Per Bounce","value":"20% per bounce"},{"label":"Maximum Times Of Bounce","value":"3"}]'::jsonb, 6),
  (36375, 'blade', null, null, 'BLADE OF KHONSHU', 'Team-Up Ability', 'Base Effect: Perform a heavy forward cleave with the Ancestral Sword while performing a short dash. At the end of the dash, swiftly slash four times, each strike sending a Darkmoon Blade forward. When a Darkmoon Blade hits an enemy, it bounces to nearby targets. Enhanced Effect: When teaming up with Moon Knight, each Whirlwind Slash triggered generates one additional Darkmoon Blade.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Dash Duration","value":"0.15"},{"label":"Max Dash Speed","value":"60 m/s"},{"label":"Dash Damage","value":"30"},{"label":"Darkmoon Blade Damage","value":"40"},{"label":"Darkmoon Blade Flight Speed","value":"150 m/s"},{"label":"Darkmoon Blades Fired","value":"4"},{"label":"Damage Falloff Per Bounce","value":"-35%"},{"label":"Special Effect","value":"Each Whirlwind Slash generates an additional Crescent Blade"}]'::jsonb, 7),
  (36376, 'blade', null, null, 'BLEED FOR BATTLE', 'Team-Up Ability', 'Base Effect: For every set amount of damage taken, Blade builds a stack of Bloodline Awakening. Enhanced Effect: When teaming up with Captain America, taking critical damage instantly triggers the Bloodline Awakening state, gaining bonus stacks while raising the overall stack cap.', '[{"label":"Key","value":"Passive"},{"label":"Bloodline Awakening Stacks Gained From Damage Taken","value":"40 per stack"},{"label":"Bloodline Awakening Max Stacks Increase","value":"2"},{"label":"Enhanced Bloodline Awakening Max Stacks Increase","value":"4"},{"label":"Health Percentage Threshold","value":"65%"},{"label":"Bonus Stacks Gained","value":"5"}]'::jsonb, 8)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36377, 'phoenix', null, null, 'Cosmic Flames', 'Normal Attack', 'Launch a fiery projectile forward, applying 1 Spark to enemies hit. Critical hits apply 2 Sparks. At 3 Sparks, Phoenix triggers a fiery explosion that applies 1 Spark to enemies around and Healing Over Time to self. Sparks from explosions will not stack within a brief period', '[{"label":"Key","value":"Left Click"},{"label":"Damage","value":"65"},{"label":"Damage Falloff","value":"Falloff begins at 10m, decreasing to 65% at 30m"},{"label":"Fire Rate","value":"0.435s per round"},{"label":"Special Effect","value":"Apply 1 Spark to enemies hit. Critical hits apply 2 Sparks. At 3 Sparks, Phoenix triggers a fiery explosion that applies 1 Spark to enemies around. Sparks from explosions will not stack within a brief period."},{"label":"Explosion Direct Damage","value":"45"},{"label":"Explosion Range Damage","value":"20"},{"label":"Explosion Range","value":"4m spherical radius spell field"},{"label":"Self Bonus Health After The Explosion","value":"5/s for 4 s"}]'::jsonb, 0),
  (36378, 'phoenix', null, null, 'Telekinesis Burst', 'Ability', 'Mark a targeted area with psionic energy, followed by a series of fiery explosions. The first blast Stuns enemies, while the subsequent two explosions inflict Slow. Applies 1 Spark to enemies hit', '[{"label":"Key","value":"Right Click"},{"label":"Target Explosion Damage","value":"20"},{"label":"Target Explosion Range","value":"A cylindrical spell field with a 2m radius and a height of 4m."},{"label":"Subsequent Explosion Damage","value":"20"},{"label":"Subsequent Explosion Range","value":"A cylindrical spell field with a 3m radius and a height of 6m."},{"label":"Special Effect","value":"The first blast Stuns enemies, while the subsequent two explosions inflict Slow."},{"label":"Stun Duration","value":"0.3s"},{"label":"Slow Effect","value":"Inflict 30% Slow for 2 seconds."},{"label":"Cooldown","value":"10s"}]'::jsonb, 1),
  (36379, 'phoenix', null, null, 'Dark Ascent', 'Ability', 'Merge with the Phoenix, entering a state of free flight. Gain a Movement Boost', '[{"label":"Key","value":"E"},{"label":"Special Effect","value":"Enter a state of free flight within the duration. Gain a 50% Movement Boost"},{"label":"Cooldown","value":"1s"},{"label":"Maximum Energy","value":"1200"},{"label":"Energy Cost","value":"400/s"},{"label":"Energy Recovery","value":"120/s"}]'::jsonb, 2),
  (36380, 'phoenix', null, null, 'Telepathic Illusion', 'Ability', 'Leave behind an illusion and instantly teleport in the desired direction, followed by detonating the illusion. Enemies hit are applied with 1 Spark', '[{"label":"Key","value":"SHIFT"},{"label":"Dash Distance","value":"8m"},{"label":"Detonation Damage","value":"50"},{"label":"Detonation Range","value":"3m spherical radius spell field"},{"label":"Special Effect","value":"The detonation applies 1 Spark to enemies hit."},{"label":"Cooldown","value":"12s"}]'::jsonb, 3),
  (36381, 'phoenix', null, null, 'Endsong Inferno', 'Ultimate', 'Soar into the sky with the Phoenix and crash down onto a selected area, dealing devastating damage to enemies while creating a shockwave that destroys enemy summons, shields, and any Bonus Health. Enemies hit are applied with 1 Spark', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"3100"},{"label":"Explosion Damage","value":"150"},{"label":"Explosion Range","value":"10m spherical radius spell field"},{"label":"Shockwave Damage","value":"50"},{"label":"Summons'' Health","value":"500"},{"label":"Special Effect","value":"The shockwave destroys enemy summons, shields, and any Bonus Health. Enemies hit by the spell field and the shockwave are applied with 2 Spark."},{"label":"Self Healing Amount","value":"250"}]'::jsonb, 4),
  (36382, 'phoenix', null, null, 'Mind''s Grace', 'Team-Up Ability', 'Jean Grey imbues Wolverine with the awe-inspiring Phoenix Force', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"10% damage boost"}]'::jsonb, 5),
  (36383, 'phoenix', null, null, 'CIRCLE OF LIFE', 'Team-Up Ability', 'Base Effect: Psionic Detonation is replaced by Phoenix Netherfire, applying a Telekinetic Mark to the targeted location. Upon hitting, it triggers an initial small explosion that briefly Stuns enemies, followed by two larger explosions that apply a Healing Reduction effect. Every single blast inflicts Sparks onto the enemies. Enhanced Effect: When teaming up with Hela, every blast in the sequence applies multiple stacks of Sparks to enemies caught within.', '[{"label":"Key","value":"Right Click"},{"label":"Cooldown","value":"10s"},{"label":"First Spell Field Damage","value":"15"},{"label":"2nd & 3rd Spell Field Damage","value":"20"},{"label":"Stun Duration","value":"0.3s"},{"label":"Healing Reduction Amount","value":"40%"},{"label":"Healing Reduction Duration","value":"3s"},{"label":"Ember Stacks Added Per Hit","value":"2"}]'::jsonb, 6),
  (36384, 'phoenix', null, null, 'TELEKINETIC BEATDOWN', 'Team-Up Ability', 'Base Effect: Fire a telekinetic shockwave forward. If it lands, the Phoenix Force rushes the enemy and delivers a powerful punch. If there are other targets nearby, the Phoenix Force rapidly blinks between them to strike them as well, inflicting Sparks on each victim while healing Phoenix. Enhanced Effect: When teaming up with Rogue, the width of the telekinetic shockwave expands, and the Phoenix Force''s target detection range is increased.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"10s"},{"label":"Direct Hit Damage","value":"55"},{"label":"Bounce Damage","value":"55"},{"label":"Bounce Spell Field Detection Range","value":"8m radius"},{"label":"Self Health Recovery","value":"50"},{"label":"Spark Stacks Added Per Hit","value":"1"},{"label":"Maximum Number Of Bounces","value":"3"},{"label":"Spark Stacks Added On Hit","value":"2"},{"label":"Enhanced Maximum Number Of Bounces","value":"4"},{"label":"Self Healing Amount","value":"65"}]'::jsonb, 7),
  (36385, 'ultron', null, null, 'ENCEPHALO-RAY', 'Normal Attack', 'Unleash a burning energy beam', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"First constant beam; Second single-cast cylindrical spell field"},{"label":"Ammo","value":"6"},{"label":"Damage","value":"First beam 6 rounds in 0.5s, 12 per hit; second single-cast spell field 75 per hit"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 75% at 30m"},{"label":"Fire Rate","value":"1.58s per round"}]'::jsonb, 0),
  (36386, 'ultron', null, null, 'IMPERATIVE: FIREWALL', 'Ability', 'Deploy drones to an ally marked by Imperative: Patch, granting them increased Speed and Damage. Additionally, all allies within range of you and the chosen teammate receive Bonus Health.', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Instant Cast"},{"label":"Bonus Health To Ultron","value":"40"},{"label":"Bonus Health To Allies Near Ultron And The Drones","value":"40"},{"label":"Cooldown","value":"12s"},{"label":"Range","value":"8m spherical radius spell field"},{"label":"Bonus Health Falloff Begins At","value":"3s"},{"label":"Bonus Health Falloff Speed","value":"40/s"},{"label":"Special Effect","value":"Grant bonus health to Ultron and Allies within range, centered around Ultron and the drones; the selected ally gains a 20% Movement Speed and 10% Damage boost"},{"label":"Self Healing Amount","value":"20 per second"},{"label":"Self Healing Duration","value":"3s"}]'::jsonb, 1),
  (36387, 'ultron', null, null, 'IMPERATIVE: PATCH', 'Ability', 'Command up to 2 giant drones to follow 2 allies, constantly healing allies within its radius, with more healing for the designated allies.', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Targeted"},{"label":"Target Distance","value":"25m"},{"label":"Healing Amount To The Targeted Ally","value":"40/s"},{"label":"Healing Amount To Other Allies Within Range","value":"35/s"},{"label":"Drone Healing Range","value":"8m spherical radius spell field"},{"label":"Maximum Vision","value":"30m"},{"label":"Max Tolerance Duration Out Of Sight","value":"5s"},{"label":"Special Effect","value":"Imperative: Patch can deploy up to 2 drones, allowing support for two allies at once"}]'::jsonb, 2),
  (36388, 'ultron', null, null, 'DYNAMIC FLIGHT', 'Ability', 'Fly quickly in the direction of movement and then enter an Accelerated state', '[{"label":"Key","value":"Shift"},{"label":"Casting","value":"Dash"},{"label":"Special Effect","value":"Dynamic Flight can trigger a one-time dash followed by an constant accelerated effect."},{"label":"Dash Direction","value":"Reticle direction combined with key input"},{"label":"Cooldown","value":"8s"},{"label":"Dash Distance","value":"12m"},{"label":"Accelerate Duration","value":"6s"},{"label":"Movement Boost","value":"40%"},{"label":"Bonus Health (Self)","value":"50"}]'::jsonb, 3),
  (36389, 'ultron', null, null, 'RAGE OF ULTRON', 'Ultimate', 'Summon Ultron Drones to fire Encephalo-Rays, damaging enemies or healing allies', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact."},{"label":"Projectile Speed","value":"120m/s"},{"label":"Beam Damage","value":"Ultron''s Encephalo-Rays 18, Drone''s Encephalo-Rays 12"},{"label":"Damage Falloff","value":"Starts at 1.5m after Encephalo-Rays explode, with a max falloff to 50% at 3m"},{"label":"Beam Healing Amount","value":"40"},{"label":"Total Ray Amount","value":"5"},{"label":"Ray Amount Per Shot","value":"5"},{"label":"Fire Interval Between Shots","value":"0.2s"},{"label":"Ultimate Total Fire Rounds","value":"5 rounds"},{"label":"Fire Interval Between Rounds","value":"0.5s"},{"label":"Spell Field Range","value":"3m spherical radius spell field"},{"label":"Duration","value":"9s"},{"label":"Energy Cost","value":"4300"},{"label":"Ultimate Self-Healing","value":"50/s"},{"label":"Special Effect","value":"Within the ultimate duration, Ultron grants an Unstoppable effect; Deals 125% damage to Bonus Health"}]'::jsonb, 4),
  (36390, 'ultron', null, null, 'NANO RAY', 'Team-Up Ability', 'When Iron Man, Ultron and Squirrel Girl team up, Ultron''s Encephalo-Ray upgrades to Nano-Ray, firing a beam that pierces through all characters, dealing continuous damage to foes while healing allies; Squirrel Girl gains the Squirrel Missile ability. She directs a squirrel to ride Iron Man''s nanotech glove as a homing missile. Upon hit, the squirrel flees just before a fiery explosion!', '[{"label":"Key","value":"C"},{"label":"Casting","value":"Channeled"},{"label":"Ammo","value":"Infinite"},{"label":"Critical Hit","value":"No"},{"label":"Range","value":"2.5m radius, infinite length cylindrical spell field"},{"label":"Damage","value":"70/s"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 75% at 30m"},{"label":"Heal","value":"85/s"},{"label":"Cooldown","value":"30s"},{"label":"Spell Field Duration","value":"8s"}]'::jsonb, 5),
  (36391, 'ultron', null, null, 'STARK PROTOCOL', 'Team-Up Ability', 'Base Effect: Upgrade Encephalo-Ray to Nano-Ray, firing multiple damaging nano-projectiles forward. Enhanced Effect:When teaming up with Iron Man, Imperative: Firewall fires powerful homing missiles at enemies in range, causing area damage.', '[{"label":"Key","value":"C"},{"label":"Ability Duration","value":"8s"},{"label":"Cooldown","value":"20s"},{"label":"Ray Damage","value":"70/s"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 75% at 30m"},{"label":"Ray Healing Amount","value":"70/s"},{"label":"Enhanced Key","value":"Right Click"},{"label":"Missiles Fired","value":"4"},{"label":"Missile Explosion Damage Range","value":"1.5m spherical radius"},{"label":"Missile Explosion Damage","value":"10"},{"label":"Enhanced Cooldown","value":"12"}]'::jsonb, 6),
  (36392, 'ultron', null, null, 'SP//DR SYNC', 'Team-Up Ability', 'Base Effect: Apply Imperative: Patch to all allies. Enhanced Effect: When teaming up with Peni Parker, Imperative: Firewall applies to all Drones, allowing the ability effects to be triggered multiple times simultaneously.', '[{"label":"Key","value":"C"},{"label":"Ability Duration","value":"3s"},{"label":"Cooldown","value":"20s"},{"label":"Healing Amount To The Targeted Ally","value":"40/s"},{"label":"Healing Amount To Other Allies Within Range","value":"15/s"},{"label":"Enhanced Key","value":"Right Click"},{"label":"Right-Click Cooldown","value":"12s"}]'::jsonb, 7),
  (36393, 'emma-frost', null, null, 'TELEPATHIC PULSE', 'Normal Attack', 'Fire a psionic beam to deal damage; the longer the beam hits, the higher the damage', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Channeled"},{"label":"Ammo","value":"70"},{"label":"Damage","value":"Damage increases with energy: 0 - 70/s, 99 - 110/s, full energy - 140/s"},{"label":"Attack Range","value":"20m"},{"label":"Ammo Consumption","value":"10/s"},{"label":"Special Effect","value":"Energy gain: Hero hit: 12/s; Sentience hit: 18/s; Common summons hit: 5/s; Shield hit: 6/s. Falloff begins 4s after not hitting an enemy, at a rate of 30/s"}]'::jsonb, 0),
  (36394, 'emma-frost', null, null, 'MIND''S AEGIS', 'Ability', 'Create a levitating barrier at the designated location', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Deployable Shield"},{"label":"Maximum Shield Value","value":"400"},{"label":"Recovery Speed","value":"80/s"},{"label":"Delayed Recovery After Release","value":"2s"},{"label":"Reposition Cooldown","value":"1s"},{"label":"Cooldown After Destroyed","value":"4s"}]'::jsonb, 1),
  (36395, 'emma-frost', null, null, 'PSYCHIC SPEAR', 'Ability', 'Seize control of an enemy''s sentience—damage dealt to the sentience cascades to the physical form and can be pierced by Telepathic Pulse. When the sentience shatters, it unleashes extra damage on its owner', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Single-cast delayed projectile"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Maximum Distance","value":"24m"},{"label":"Sentience Health","value":"Target''s 25% Current Health"},{"label":"Damage","value":"Deal 5 damage per direct hit. When the sentience shatters, it deals damage to the target, which is equal to 25% of the target''s maximum health"},{"label":"Special Effect","value":"When the distance between the target and its sentience is more than 15m, their linkage can be broken"}]'::jsonb, 2),
  (36396, 'emma-frost', null, null, 'DIAMOND FORM', 'Ability', 'Activate Diamond Form to transform your attack style while gaining Damage Reduction and becoming Unstoppable', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Switch Form"},{"label":"Duration","value":"8s"},{"label":"Special Effect","value":"25% Damage Reduction in Diamond form"},{"label":"Cooldown","value":"15s"}]'::jsonb, 3),
  (36397, 'emma-frost', null, null, 'FACETED FURY', 'Ability', 'In Diamond Form, deliver a crushing double-fisted strike to enemies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast Spell Field"},{"label":"Damage","value":"First & second hit: 50; third hit: 70; fourth hit: 80"},{"label":"Attack Range","value":"4m"}]'::jsonb, 4),
  (36398, 'emma-frost', null, null, 'CRYSTAL KICK', 'Ability', 'In Diamond Form, unleash a flying kick forward and knock back enemies; extra damage is dealt if they''re propelled into a wall', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast Spell Field"},{"label":"Hit Range","value":"5m"},{"label":"Damage","value":"Hit damage: 40; damage increases to 90 when the target is knocked into walls"},{"label":"Cooldown","value":"2s"},{"label":"Special Effect","value":"Maximum knockback distance: 10m"}]'::jsonb, 5),
  (36399, 'emma-frost', null, null, 'CARBON CRUSH', 'Ability', 'In Diamond Form, lunge forward to grab an enemy, then execute a back slam to inflict damage', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Dash Based Control"},{"label":"Damage","value":"30"},{"label":"Maximum Distance","value":"8.5m"},{"label":"Cooldown","value":"6s"},{"label":"Special Effect","value":"Control effect duration: 1.6s"}]'::jsonb, 6),
  (36400, 'emma-frost', null, null, 'PSIONIC SEDUCTION', 'Ultimate', 'Project a forward psychic assault that stuns foes and prevents them from unleashing their Ultimate Abilities; if the effect lingers, it gradually commandeers their mind, forcing them to move toward Emma Frost', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Large-ranged Persistent Spell Field"},{"label":"Duration","value":"6s"},{"label":"Range","value":"Cone shape spell field, angle range: 80°, length: 30m"},{"label":"Damage","value":"Basic damage 80/s; distance falloff: falloff begins at 10m, decreasing to 70% at 30m; angle falloff: falloff begins at 7° from the center of view, decreasing to 80% at 20°"},{"label":"Energy Cost","value":"3100"},{"label":"Special Effect","value":"When exposed to the ability, enemies accumulate 10 stacks per second, and the stacks decrease by 10 stacks per second when they leave the exposure. At 15 stacks, a control effect is triggered. Each enemy can only be controlled once per ultimate activation. Gain 25% Damage Reduction during the ability."}]'::jsonb, 7),
  (36401, 'emma-frost', null, null, 'ICED OUT DIAMOND', 'Team-Up Ability', 'Luna Snow grants Winter''s Chill to Iron Fist and Emma Frost. When Iron Fist activates Harmony Recovery, he can heal nearby allies with Lunar Chi. Emma Frost can project ice energy forward, dealing damage and slowing enemies. She can also enhance her diamond form, condensing frost into an Absolute Zero Diamond barrier that blocks enemy attacks and movement', '[{"label":"Key","value":"C"},{"label":"Summons'' Health","value":"250"},{"label":"Spell Field Range","value":"A fan-shaped spell field with a radius of 12m, a height of 3m, and an angle of 60°"},{"label":"Spell Field Damage","value":"60"},{"label":"Slow Rate","value":"45%"},{"label":"Slow Duration","value":"3s"},{"label":"Cooldown","value":"20s"}]'::jsonb, 8)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36402, 'emma-frost', null, null, 'SPIRIT BREAKER', 'Team-Up Ability', 'Base Effect: Deals damage to the summoned Soul Crystal, which can be converted into Bonus Healthfor yourself. Enhanced Effect: When Emma Frost teams up with Mantis, shattering the Soul Crystalgrants a one-time Bonus Healthand reduces the cooldown of Mind Control.', '[{"label":"Key","value":"E"},{"label":"Bonus Health Conversion Rate From Damage","value":"150%"},{"label":"Mind Control Cd Reduction","value":"2s"},{"label":"One-Time Bonus Health","value":"100"}]'::jsonb, 9),
  (36403, 'emma-frost', null, null, 'ICED OUT DIAMOND', 'Team-Up Ability', 'Base Effect: Emma Frost releases winter energy forward, dealing damage and Slowto enemies. She can also enhance her diamond form, condensing frost in front of her to form Zero Diamondthat blocks enemy attacks and movement. Enhanced Effect: When Emma Frost teams up with Luna Snow, after activating Diamond Form, all ability damage applies Slow, and Soul Wavealso applies Slow.', '[{"label":"Key","value":"C"},{"label":"Summons'' Health","value":"350"},{"label":"Spell Field Range","value":"8m radius, 3m tall, 60° cone spell field"},{"label":"Spell Field Damage","value":"50"},{"label":"Slow Rate","value":"25% for 2s"},{"label":"Cooldown","value":"12s"},{"label":"Enhanced Key","value":"Passive"},{"label":"Diamond Form Damage Slow Amount","value":"20% for 2s"},{"label":"Telepathic Pulse Added Slow Effect","value":"Scales with energy, up to 10% at 100 energy"}]'::jsonb, 10),
  (36404, 'the-thing', null, null, 'Rocky Jab', 'Normal Attack', 'Rapidly punch forward', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast Spell Field"},{"label":"Damage","value":"Double strike, 40 per hit"},{"label":"Attack Range","value":"4m"},{"label":"Attack Interval","value":"Double strike 0.33s between attacks, 1s between sets."}]'::jsonb, 0),
  (36405, 'the-thing', null, null, 'Stone Haymaker', 'Ability', 'Deliver a devastating Heavy Blow. Can Knock Down flying enemies.', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast Spell Field"},{"label":"Damage","value":"55+8% of enemies'' max Health per hit"},{"label":"Attack Range","value":"8m"},{"label":"Special Effect","value":"Move forward 3 meters while punching; gain Bonus Health equal to damage dealt (up to 150); once hit, this ability can knock down flying enemies to the ground"}]'::jsonb, 1),
  (36406, 'the-thing', null, null, 'Yancy Street Charge', 'Ability', 'Continuously charge forward, launching up enemies and leaving behind a zone at the final position that prevents the use of mobility abilities', '[{"label":"Key","value":"SHIFT"},{"label":"Movement Boost","value":"100%"},{"label":"Duration","value":"5s"},{"label":"Damage","value":"Charge: 30; ground slam: 20; immobilization zone: 15 per/s"},{"label":"Spell Field Range","value":"Ground slam: 8m radius, 2.5m high cylindrical spell field. Immobilization zone: 8m radius, 4m high cylindrical spell field"},{"label":"Cooldown","value":"12s"},{"label":"Special Effect","value":"Gain 200 Bonus Health during skill activation"}]'::jsonb, 2),
  (36407, 'the-thing', null, null, 'Embattled Leap', 'Ability', 'Jump toward an ally and apply damage reduction to yourself and allies within the landing area', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"20m"},{"label":"Cooldown","value":"Basic Cooldown 3s, with a charge of 10s per use"},{"label":"Special Effect","value":"Apply a 20% damage reduction effect to self and 20% damage reduction to all allies within 5m of his landing point for 3s"}]'::jsonb, 3),
  (36408, 'the-thing', null, null, 'Battle Blitz', 'Ability', 'Jump toward an enemy and apply Vulnerability to enemies within the landing area', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"20m"},{"label":"Cooldown","value":"Basic Cooldown 3s, with a charge of 10s per use, shares the same Cooldown with the E Key ability"},{"label":"Special Effect","value":"Apply a 20% Vulnerability to all enemies within 5m of his landing point for 3s"}]'::jsonb, 4),
  (36409, 'the-thing', null, null, 'Clobberin'' Time', 'Ultimate', 'Use immense power to launch up all enemies in front of the Thing into the air', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"2800"},{"label":"Range","value":"Step spell field: 3m high, 10m wide, advancing 2m every 0.1 seconds, up to a maximum of 18m"},{"label":"Damage","value":"100"},{"label":"Special Effect","value":"Stun duration 2.5s"}]'::jsonb, 5),
  (36410, 'the-thing', null, null, 'Unyielding Will', 'Passive', 'Immune to launch-up, knock-back, and other displacement effects', '[{"label":"Key","value":"PASSIVE"},{"label":"Special Effect","value":"Immune to launch-up, knock-back, and other displacement effects"}]'::jsonb, 6),
  (36411, 'the-thing', null, null, 'Cosmic Fastball', 'Team-Up Ability', 'Wolverine and The Thing can interact with each other. Once both parties confirm, The Thing can lift Wolverine and press the key to hurl him forward', '[{"label":"Key","value":"Z"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"20m"},{"label":"Cooldown","value":"3s when not thrown, 15s when thrown"}]'::jsonb, 7),
  (36412, 'the-thing', null, null, 'GAMMA CHARGE', 'Team-Up Ability', 'Hulk charges Black Panther and The Thing with gamma radiation. When Black Panther''s health is low, he gains a gamma shield, becoming Unstoppable and blocking attacks. The Thing gains Gamma Gauntlets, boosting Damage and range of his Rocky Jab and Stone Haymaker. Dealing damage with these attacks grants Bonus Health, and maximum Bonus Health cap is increased', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"25s"},{"label":"Ability Duration","value":"8s"},{"label":"Left Click Spell Field Max Distance","value":"5m"},{"label":"Left Click Spell Field Damage","value":"45"},{"label":"Right Click Spell Field Max Distance","value":"9m"},{"label":"Right Click Spell Field Damage","value":"60+11% of enemy''s maximum health"},{"label":"Max Bonus Health","value":"120"},{"label":"Damage/Health Conversion","value":"1"}]'::jsonb, 8),
  (36413, 'the-thing', null, null, 'Flying Thing', 'Team-Up Ability', 'Human Torch can lift The Thing into the air and slam him down, dealing damage, launching enemies, and creating a zone that disables mobility abilities', '[{"label":"Key","value":"X"},{"label":"Cooldown","value":"Successfully interacted: 30s; fail to interact: 3s"},{"label":"Maximum Distance","value":"20m"},{"label":"Flight Speed","value":"15m/s"},{"label":"Slam Down Initial Horizontal Velocity","value":"15m/s"},{"label":"Maximum Flight Duration","value":"8s"},{"label":"Damage","value":"Launch-up spell field causes 30 damage; mobility abilities disabling spell field causes 15 damage per second"},{"label":"Launch Up Range","value":"A cylindrical spell field with a radius of 8m and a height of 1m"},{"label":"Mobility Abilities Disabling Range","value":"A cylindrical spell field with a radius of 8m and a height of 8m"}]'::jsonb, 9),
  (36414, 'the-thing', null, null, 'TWO IN ONE', 'Team-Up Ability', 'Base Effect: Enter an enhanced state upon activation. For the duration, The Thing''s fists are violently engulfed in flames. Every Rocky Jab deals splash damage, and every Stone Haymaker creates an explosion, dealing damage in a frontal cone. Enhanced Effect: When teaming up with Human Torch, Human Torch can lift The Thing into the air and slam him down, dealing damage and Stun to enemies. The Thing then automatically enters his flaming enhanced state upon landing.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"18s"},{"label":"Rock Jab Max Attack Range","value":"6m"},{"label":"Stone Haymaker Max Attack Range","value":"9.5m"},{"label":"Ability Duration","value":"8s"},{"label":"Special Effect","value":"Increases the cast speed of Rock Jab and Stone Haymaker"},{"label":"Enhanced Key","value":"X"},{"label":"Enhanced Cooldown","value":"30s"},{"label":"Spell Field Range","value":"8m spherical radius"},{"label":"Damage","value":"45"},{"label":"Stun Duration","value":"1s"},{"label":"Flight Speed","value":"12 m/s"}]'::jsonb, 10),
  (36415, 'the-thing', null, null, 'UNBREAKABLE FORCES', 'Team-Up Ability', 'Base Effect: Generate a layer of Psionic Armor upon activation, granting Bonus Health scaling off currently missing Health. Enhanced Effect: When teaming up Invisible Woman, the Psionic Armor is fortified. While active, every time The Thing takes a set amount of damage, the armor pulses out a wave of area healing for allies. Furthermore, the conversion ratio for missing Health into Bonus Health is increased.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Duration","value":"5s"},{"label":"Bonus Health Recovery","value":"15/hit"},{"label":"Bonus Health Generation Frequency","value":"5 times per second"},{"label":"Special Effect","value":"When Health reaches 50%, Bonus Health generation frequency increases by 100%"},{"label":"Enhanced Bonus Health Recovery","value":"20 per hit"},{"label":"Damage Taken Required To Trigger Healing","value":"125"},{"label":"Healing Amount","value":"80"},{"label":"Healing Spell Field Range","value":"8m radius"}]'::jsonb, 11),
  (36416, 'human-torch', null, null, 'Fire Cluster', 'Normal Attack', 'Launch forward a splittable fireball', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Burst Projectile"},{"label":"Charges","value":"6"},{"label":"Charge Speed","value":"Instantly recover all Fire Cluster energy after not using Fire Cluster for 1s"},{"label":"Fire Rate","value":"0.5s per round"},{"label":"Projectile Speed","value":"150m/s"},{"label":"Shot Damage","value":"5.5 per round"},{"label":"Damage Falloff","value":"Falloff begins at 15m, decreasing to 60% at 20m."},{"label":"Crosshair Spread Radius (At 10m)","value":"0.33m"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36417, 'human-torch', null, null, 'Blazing Blast', 'Ability', 'Launch a fireball to create a Flame Field at the targeted area', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Straight-line projectile that generates a spherical spell field upon impact."},{"label":"Charges","value":"3"},{"label":"Charge Speed","value":"2.5s per strike"},{"label":"Blazing Blast Projectile Speed","value":"80m/s"},{"label":"Blazing Blast Damage","value":"45"},{"label":"Flame Field Range","value":"3m spherical radius"},{"label":"Flame Field Duration","value":"6s"},{"label":"Flame Field Continuous Damage","value":"20/s"}]'::jsonb, 1),
  (36418, 'human-torch', null, null, 'Flaming Meteor', 'Ability', 'Dive towards the ground, dealing damage to enemies and detonating any Flame Fields hit', '[{"label":"Key","value":"F"},{"label":"Max Dash Speed","value":"80m/s"},{"label":"Range","value":"5m spherical radius"},{"label":"Damage","value":"40"},{"label":"Flame Field Detonation Range","value":"3m spherical radius"},{"label":"Flame Field Detonation Damage","value":"55"},{"label":"Bonus Health","value":"50"},{"label":"Cooldown","value":"15s"}]'::jsonb, 2),
  (36419, 'human-torch', null, null, 'Plasma Body', 'Ability', 'Enter a state of accelerated ascent', '[{"label":"Key","value":"SHIFT"},{"label":"Movement Boost","value":"2.5m/s"},{"label":"Duration","value":"4s"},{"label":"Maximum Distance","value":"10m"},{"label":"Cooldown","value":"2 charges, with each charge taking 8s to recharge"}]'::jsonb, 3),
  (36420, 'human-torch', null, null, 'Pyro-Prison', 'Ability', 'Form a fire wall between Fire Fields to burn enemies', '[{"label":"Key","value":"E"},{"label":"Max Link Distance","value":"40m"},{"label":"Max Link Height","value":"2m"},{"label":"Fire Wall Duration","value":"5s"},{"label":"Fire Wall Damage","value":"65"},{"label":"Pyro-Prison Continuous Damage","value":"40/s"},{"label":"Cooldown","value":"15s"}]'::jsonb, 4),
  (36421, 'human-torch', null, null, 'Supernova', 'Ultimate', 'Explode with cosmic fire to deal damage to enemies within range. Upon skill activation, all Flame Fields will transform into Flame Tornadoes, dealing extra damage', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"4000"},{"label":"Duration","value":"8s"},{"label":"Activation Shock Wave Range","value":"20m spherical radius"},{"label":"Activation Wave Damage","value":"75"},{"label":"Flame Tornado Unleash Speed","value":"0.7s per use"},{"label":"Flame Tornado Range","value":"3m spherical radius; 8m high capsule-shaped spell field."},{"label":"Flame Tornado Continuous Damage","value":"110/s"},{"label":"Supernova Damage Reduction","value":"-30%"}]'::jsonb, 5),
  (36422, 'human-torch', null, null, 'Storm Siblings', 'Team-Up Ability', 'The Invisible Woman taps into her powers, channeling Psionic Might to fortify the entire Fantastic Four team, granting damage resistance. Once activated, they can continually generate Bonus Health, making up for lost Health', '[{"label":"Key","value":"C"},{"label":"Duration","value":"5s"},{"label":"Cooldown","value":"25s"},{"label":"Bonus Health Growth","value":"Generate 5 Bonus Health per 0.1s"},{"label":"Bonus Max Health","value":"100"},{"label":"Team-Up Target","value":"Invisible Woman"}]'::jsonb, 6),
  (36423, 'human-torch', null, null, 'Pyrokinetic Energy', 'Team-Up Ability', 'Human Torch stores Pyrokinetic Energy in Spider-Man''s suit, enabling him to unleash an Inferno Blast that sprays a fiery web while performing a backflip to create distance. The flames damage enemies and apply a Burn-Tracer. Detonating these Burn-Tracers inflicts Damage Over Time', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"5% Damage Boost"}]'::jsonb, 7),
  (36424, 'human-torch', null, null, 'Two In One', 'Team-Up Ability', 'Human Torch can lift The Thing into the air and slam him down, dealing damage, launching enemies, and creating a zone that disables mobility abilities', '[{"label":"Key","value":"X"},{"label":"Cooldown","value":"Successfully interacted: 30s; fail to interact: 3s"},{"label":"Maximum Distance","value":"20m"},{"label":"Flight Speed","value":"15m/s"},{"label":"Slam Down Initial Horizontal Velocity","value":"15m/s"},{"label":"Maximum Flight Duration","value":"8s"},{"label":"Damage","value":"Launch-up spell field causes 30 damage; mobility abilities disabling spell field causes 15 damage per second"},{"label":"Launch Up Range","value":"A cylindrical spell field with a radius of 8m and a height of 1m"},{"label":"Mobility Abilities Disabling Range","value":"A cylindrical spell field with a radius of 8m and a height of 8m"}]'::jsonb, 8),
  (36425, 'human-torch', null, null, 'FIERY SPARKS', 'Team-Up Ability', 'Base Effect: Passively detect enemies in the immediate vicinity and launch tracking Sparks to chip away their health. Enhanced Effect: When teaming up with Jubilee, successfully landing a Firework Spark on an enemy grants Human Torch Bonus Health.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Ability Duration","value":"5s"},{"label":"Spell Field Range","value":"10m spherical radius"},{"label":"Tick Rate","value":"0.1s per use"},{"label":"Spark Damage","value":"7 per round"},{"label":"Bonus Health Gain Through Sparks","value":"4 per round"}]'::jsonb, 9),
  (36426, 'human-torch', null, null, 'STORMING IGNITION', 'Team-Up Ability', 'Base Effect: Unleash a storm-driven blaze of fire forward, generating a persistent Fire Vortex upon impact that continuously damages and pulls in enemies. Enhanced Effect: When teaming up with Storm, her Omega Hurricane ignites into a Burning Hurricane if it crosses a Flame Tornado. Furthermore, any Omega Hurricane, Jeff-Nado, or Flame Tornado that sweeps across a Flame Field left by Human Torch will instantly generate a new Flame Tornado.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Single-Cast Spell Field","value":"30"},{"label":"Damage Over Time","value":"5/hit, 5 times per second"},{"label":"Spell Field Duration","value":"4s"},{"label":"Spell Field Range","value":"5m radius"},{"label":"Enhanced Key","value":"Passive"},{"label":"Flame Nado Damage","value":"35/hit, 2 times per second"},{"label":"Flame Tornado Range","value":"3m radius, 6m height"},{"label":"Burning Hurricane Damage","value":"75 damage per hit, 2 hits per second"},{"label":"Duration Increase From Passing Through Flame Field","value":"2s"},{"label":"Burning Hurricane Max Duration","value":"11s"},{"label":"Burning Hurricane Radius","value":"10m"}]'::jsonb, 10)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36427, 'invisible-woman', null, null, 'Orb Projection', 'Normal Attack', 'Launch a force field orbs that can pierce heroes, flying to maximum distance before returning to Invisible Woman; damaging enemies and healing teammates', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact."},{"label":"Special Effect","value":"Orbs can pierce heroes and return to Invisible Woman after reaching their maximum distance. They damage enemies and heal teammates"},{"label":"Damage","value":"Deal 30 damage per hit upon being shot out and 15 damage per hit on its return journey."},{"label":"Damage Falloff","value":"No falloff"},{"label":"Healing Amount","value":"Heal 50 health per hit upon being shot out and 40 health per hit on its return journey."},{"label":"Fire Rate","value":"0.5s per hit"},{"label":"Projectile Speed","value":"150 m/s"},{"label":"Maximum Flight Distance","value":"35m"},{"label":"Ammo","value":"10"},{"label":"Critical Hit","value":"No"}]'::jsonb, 0),
  (36428, 'invisible-woman', null, null, 'Guardian Shield', 'Ability', 'Generate a force shield in front of a selected ally or in front of you. The shield can block damage and provide Healing Over Time to nearby allies. Enemies that pass through the shield are slowed', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Targeted"},{"label":"Healing Amount","value":"50/sec, self 20/sec"},{"label":"Range","value":"3m radius"},{"label":"Slow Rate","value":"35%"},{"label":"Slow Duration","value":"3s"},{"label":"Maximum Shield Value","value":"200"},{"label":"Special Effect 1","value":"Before the shield is destroyed, Invisible Woman can choose to reproject the shield onto a selected teammate at any time"},{"label":"Special Effect 2","value":"After the shield has been damaged, Invisible Woman can press the F key to reclaim the shield and restore its value"},{"label":"Special Effect 3","value":"If no Guardian Shield is present, pressing the recall key now deploys a shield in front of Invisible Woman"},{"label":"Recovery Shield Value Per Second","value":"34"},{"label":"Cooldown After Destroyed","value":"6s"}]'::jsonb, 1),
  (36429, 'invisible-woman', null, null, 'Psionic Vortex', 'Ability', 'Gather psionic energy and then cast it, upon impact or pressing the Ability key again, it erupts into a psionic vortex, continuously drawing in enemies and causing damage', '[{"label":"Key","value":"Shift"},{"label":"Casting","value":"Single-cast projectile with delayed impact that also generates a spell field"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Spell Field Range","value":"5m radius"},{"label":"Spell Field Damage","value":"35/sec"},{"label":"Spell Field Duration","value":"4s"},{"label":"Special Effect","value":"Applies a slow effect to enemies within the spell field; the closer they are to the center of the field, the greater the slow effect"},{"label":"Slow Rate","value":"Center 50%, Edge 0"},{"label":"Cooldown","value":"12s"}]'::jsonb, 2),
  (36430, 'invisible-woman', null, null, 'Force Physics', 'Ability', 'Manipulate psionic energy to push or pull enemies in front of her', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Cylindrical Spell Field"},{"label":"Range","value":"1.5m radius, 35m length"},{"label":"Damage","value":"50"},{"label":"Push Range","value":"10m"},{"label":"Pull-Range","value":"7m"},{"label":"Cooldown","value":"10s"}]'::jsonb, 3),
  (36431, 'invisible-woman', null, null, 'Invisible Boundary', 'Ultimate', 'Manifest an unseen force field within a chosen area, rendering allies inside undetectable by enemies and provide Healing Over Time. Enemies that pass through the field are slowed', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Targeted, generates a cylindrical spell field"},{"label":"Pass-Through Slow Rate","value":"55%"},{"label":"Slow Duration","value":"1s"},{"label":"Healing Amount","value":"200/sec"},{"label":"Range","value":"10m radius, 40m height"},{"label":"Duration","value":"8s"},{"label":"Special Effect","value":"Slows enemies within range by 20%"},{"label":"Energy Cost","value":"4300"}]'::jsonb, 4),
  (36432, 'invisible-woman', null, null, 'Covert Advance', 'Passive', 'Enter Invisible state some time after disengaging from combat and grant yourself Healing Over Time', '[{"label":"Key","value":"Passive"},{"label":"Healing Amount","value":"30/sec"}]'::jsonb, 5),
  (36433, 'invisible-woman', null, null, 'Veiled Step', 'Ability', 'Generate a force field at your feet, stepping on it propels her into the Invisible state', '[{"label":"Key","value":"Space"},{"label":"Cooldown","value":"6s"},{"label":"Special Effect","value":"For the first 1s after entering Invisible state, taking damage will no longer break stealth"}]'::jsonb, 6),
  (36434, 'invisible-woman', null, null, 'Fantasti-Force', 'Team-Up Ability', 'The Invisible Woman taps into her powers, channeling Psionic Might to fortify Mr.Fantastic. This formidable force bolsters Mr.Fantastic, granting damage resistance. Once activated, they can continually generate Bonus Health, making up for lost Health', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"15% Healing Boost"}]'::jsonb, 7),
  (36435, 'invisible-woman', null, null, 'UNITED SIBLINGS', 'Team-Up Ability', 'Base Effect: Generate a Flame Shield for a targeted ally that blocks incoming damage while providing a Continuous Healing aura to everyone nearby. Projectiles from teammates shot through the Flame Shield receive a Damage Boost. Enemies that pass though the shield are Slowed Enhanced Effect: When teaming up with Human Torch, the Flame Shield boasts a larger radius and heavily increased shield value.', '[{"label":"Key","value":"Right Click"},{"label":"Piercing Damage Boost Rate","value":"20%"},{"label":"Maximum Shield Value","value":"300"},{"label":"Enhanced Maximum Shield Value","value":"400"}]'::jsonb, 8),
  (36436, 'invisible-woman', null, null, 'FIRST FAMILY', 'Team-Up Ability', 'Base Effect: Invisible Woman and surrounding allies enter Invisible state, gaining healing and a Speed Boost. The effect ends if they take damage or the duration expires. Disengaging from combat for a duration will reenter the Invisible state. Enhanced Effect: When teaming up with Mister Fantastic, the healing and Speed Boost effects are enhanced, and the Invisible state duration is increased', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Ability Duration","value":"4s"},{"label":"Healing Amount","value":"25/s"},{"label":"Movement Boost","value":"1.2m/s"},{"label":"Enhanced Ability Duration","value":"6s"},{"label":"Enhanced Movement Boost","value":"1.8m/s"}]'::jsonb, 9),
  (36437, 'mister-fantastic', null, null, 'Stretch Punch', 'Normal Attack', 'Stretch out a forward punch to attack enemies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Straight Spell Field"},{"label":"Spell Field Damage","value":"70"},{"label":"Spell Field Range","value":"15m"},{"label":"Attack Interval","value":"1.1s per hit"},{"label":"Ammo","value":"Infinite"},{"label":"Critical Hit","value":"None"},{"label":"Gained Elasticity","value":"8"},{"label":"Special Mechanic","value":"Swinging your arms can attack multiple targets"}]'::jsonb, 0),
  (36438, 'mister-fantastic', null, null, 'Distended Grip', 'Ability', 'Extend arms forward to entangle an enemy, then press Primary Attack to pull the hit enemy toward him, or select and yank another enemy, Knocking Them Airborne against each other. Hit targets are Immobilized', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Projectile that fires in a straight trajectory"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Initial Projectile Range","value":"20m"},{"label":"Secondary Release Maximum Distance","value":"25m"},{"label":"Initial Projectile Damage","value":"20"},{"label":"Secondary Projectile Damage","value":"20"},{"label":"Single-Target Pull Range","value":"10m"},{"label":"Single-Target Pull Damage","value":"50"},{"label":"Dual-Target Pull Damage","value":"30"},{"label":"Gained Elasticity","value":"30"},{"label":"Cooldown","value":"6s"},{"label":"Special Effect","value":"After successfully pulling an enemy with Distended Grip, the target is afflicted with a 1-second immobilize effect"}]'::jsonb, 1),
  (36439, 'mister-fantastic', null, null, 'Flexible Elongation', 'Ability', 'Gain a Shield, select a target and dash towards them, dealing damage to enemies or granting a Shield to allies', '[{"label":"Key","value":"E"},{"label":"Maximum Select Distance","value":"15m"},{"label":"Bonus Health (Self)","value":"75"},{"label":"Bonus Health (Ally)","value":"75"},{"label":"Damage","value":"30"},{"label":"Cooldown","value":"6s"},{"label":"Gained Elasticity","value":"20"},{"label":"Charges","value":"2"}]'::jsonb, 2),
  (36440, 'mister-fantastic', null, null, 'Reflexive Rubber', 'Ability', 'Stretch the body to absorb damage before launching stored damage in the targeted direction', '[{"label":"Key","value":"SHIFT"},{"label":"Shield Value","value":"300"},{"label":"Maximum Duration","value":"3s"},{"label":"Self Slow Rate","value":"-35%"},{"label":"Damage Absorbed - Damage Reflected Conversion Rate","value":"60%"},{"label":"Reflected Projectile Speed","value":"80 m/s"},{"label":"Cooldown","value":"12s"}]'::jsonb, 3),
  (36441, 'mister-fantastic', null, null, 'Brainiac Bounce', 'Ultimate', 'Leap upward and smash the ground, slowing enemies within range. Mister Fantastic can leap again upon landing a hit', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Spherical Spell Field"},{"label":"Range","value":"10m spherical radius"},{"label":"Spell Field Damage","value":"Initial 70, Each Additional Leap +14, Max 140"},{"label":"Damage Falloff","value":"Start at 3m, 71.4% falloff at 10m"},{"label":"Slow Rate","value":"Per Leap -10%, Can Stack, Max -60%"},{"label":"Slow Duration","value":"3s"},{"label":"Minimum Leaps","value":"3"},{"label":"Maximum Leaps","value":"6"},{"label":"Energy Cost","value":"3100"},{"label":"Special Mechanic","value":"After the minimum number of leaps, each additional leap must hit an enemy to trigger the next one"},{"label":"Special Mechanic","value":"When Mister Fantastic uses Brainiac Bounce (Ultimate Ability), immediately gain Bonus Health equal to that gained when entering inflated state"}]'::jsonb, 4),
  (36442, 'mister-fantastic', null, null, 'Elastic Strength', 'Passive', 'Using abilities generates Elasticity, boosting attack power. Reaching full Elasticity triggers an Inflated state that increases Maximum Health, further boosts damage, and enables the use of Reflexive Rubber', '[{"label":"Key","value":"Passive"},{"label":"Max Elasticity","value":"100"},{"label":"Inflated Duration","value":"6s"},{"label":"Damage","value":"80"},{"label":"Maximum Distance","value":"8m"},{"label":"Attack Interval","value":"0.92s per hit"},{"label":"Special Effect","value":"gain 350 Maximum Health and a one-time heal of 350, which is removed upon exiting the Inflated state"},{"label":"Movement Boost","value":"20%"}]'::jsonb, 5),
  (36443, 'mister-fantastic', null, null, 'FANTASTIC AMPLIFIER', 'Team-Up Ability', 'Rocket Raccoon upgrades his B.R.B. for Star-Lord and Mister Fantastic. Star-Lord gets an Astral Jump device, allowing him to teleport to its deployment point from anywhere on the map. Mister Fantastic receives a Fantastic Amplifier, removing his Elasticity limit and letting him actively enter Inflation state', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"25s"},{"label":"Ability Duration","value":"10s"},{"label":"Energy Consumed Per Second During Inflation State","value":"16.67"}]'::jsonb, 6),
  (36444, 'mister-fantastic', null, null, 'FANTASTIC AMPLIFIER', 'Team-Up Ability', 'Base Effect: Equips the Fantastic Amplifier. For the duration, Mister Fantastic''s maximum Elasticity is increased, and he can actively enter Inflation State. Enhanced Effect: When teaming up with Rocket Raccoon, Brainiac Bounce Launches hit enemies.', '[{"label":"Key","value":"F"},{"label":"Active Inflation Cooldown","value":"8s"},{"label":"Max Elasticity","value":"200"},{"label":"Inflation State Elasticity Decay","value":"12.5 per second"},{"label":"Enhanced Key","value":"Q"},{"label":"Special Effect","value":"Brainiac Bounce knocks enemies airborne"}]'::jsonb, 7),
  (36445, 'mister-fantastic', null, null, 'CLOBBERIN'' RESEARCH DEPT.', 'Team-Up Ability', 'Base Effect: In brawler stance, Stretch Punch becomes a charged ability, firing a forward Brawling Punch. Hitting an enemy grants Bonus Health scaling with damage, and a full charge Launches hit enemies. Enhanced Effect: When teaming up with The Thing, while in the brawling stance, Distended Grip also becomes a charged ability, slamming down a Distended Hammer. Hitting enemies grants Bonus Health based on damage, and Launches enemies at full charge.', '[{"label":"Key","value":"C"},{"label":"Brawling Punch Damage","value":"65, 100 when fully charged"},{"label":"Time To Full Charge","value":"0.75s"},{"label":"Max Hold Time","value":"0.75s"},{"label":"Bonus Health Conversion Rate From Damage","value":"0.75"},{"label":"Max Bonus Health","value":"75"},{"label":"Distended Hammer Cooldown","value":"3s"},{"label":"Distended Hammer Damage","value":"70, 100 when fully charged"},{"label":"Enhanced Time To Full Charge","value":"1s"},{"label":"Enhanced Max Hold Time","value":"1s"}]'::jsonb, 8),
  (36446, 'squirrel-girl', null, null, 'Burst Acorn', 'Normal Attack', 'Shoot bouncing Burst Acorns', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Arced projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Spell Field Range","value":"3m spherical radius"},{"label":"Spell Field Damage","value":"110"},{"label":"Damage Falloff","value":"70% falloff at 3m"},{"label":"Fire Rate","value":"1.49 acorns per second"},{"label":"Ammo","value":"12"},{"label":"Critical Hit","value":"No"}]'::jsonb, 0),
  (36447, 'squirrel-girl', null, null, 'Unbeatable Squirrel Tsunami', 'Ultimate', 'Summon a horde of squirrels to charge forward, dealing damage while bouncing against structures', '[{"label":"Key","value":"Q"},{"label":"Duration","value":"10s"},{"label":"Range","value":"Length: 3m, Width: 5m, Height: 1.75m"},{"label":"Damage","value":"150"},{"label":"Squirrel Horde Health","value":"300"},{"label":"Squirrel Horde Movement Speed","value":"9 m/s"},{"label":"Energy Cost","value":"2800"},{"label":"Special Mechanic","value":"The squirrels will rush towards the nearest enemy after bouncing instead of bouncing randomly"}]'::jsonb, 1),
  (36448, 'squirrel-girl', null, null, 'Tail Bounce', 'Ability', 'Rocket upwards with a bounce of her tail', '[{"label":"Key","value":"SHIFT"},{"label":"Jump Height","value":"9m"},{"label":"Cooldown","value":"8s"}]'::jsonb, 2),
  (36449, 'squirrel-girl', null, null, 'Mammal Bond', 'Ability', 'Reload Burst Acorns and can use an ability without cooldown once in a short duration', '[{"label":"Key","value":"E"},{"label":"Maximum Duration","value":"5s"},{"label":"Cooldown","value":"12s"}]'::jsonb, 3),
  (36450, 'squirrel-girl', null, null, 'Squirrel Blockade', 'Ability', 'Launch an acorn to unleash Squirrel Guards, Imprisoning the first hit enemy', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Charged projectile with an arced trajectory"},{"label":"Maximum Charge Time","value":"1.5s"},{"label":"Projectile Speed","value":"20 - 60 m/s (Maximum speed is achieved after 0.7s of charging)"},{"label":"Damage","value":"50"},{"label":"Imprison Duration","value":"1.33s"},{"label":"Cooldown","value":"8s"}]'::jsonb, 4),
  (36451, 'squirrel-girl', null, null, 'Squirrel Missile', 'Team-Up Ability', 'When Iron Man, Ultron and Squirrel Girl team up, Ultron''s Encephalo-Ray upgrades to Nano-Ray, firing a beam that pierces through all characters, dealing continuous damage to foes while healing allies; Squirrel Girl gains the Squirrel Missile ability. She directs a squirrel to ride Iron Man''s nanotech glove as a homing missile. Upon hit, the squirrel flees just before a fiery explosion!', '[{"label":"Key","value":"C"},{"label":"Damage","value":"75"},{"label":"Damage Falloff","value":"Falloff begins at 4m, decreasing to 50% at 8m"},{"label":"Explosion Range","value":"8m spherical radius spell field"},{"label":"Projectile Speed","value":"40 m/s"},{"label":"Projectile Radius","value":"0.5m"},{"label":"Special Effect","value":"Automatically track enemies within a horizontal angle of 60°, a vertical angle of 60°, and a maximum distance of 60m"},{"label":"Cooldown","value":"20"}]'::jsonb, 5)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36452, 'squirrel-girl', null, null, 'SQUIRREL MISSILE', 'Team-Up Ability', 'Base Effect: Squirrel Girl gains the Squirrel Missile ability. She directs a squirrel to ride Iron Man''s nanotech glove as a homing missile. Upon hit, the squirrel flees just before a fiery explosion. Enhanced Effect: When teaming up with Iron Man, using Squirrel Blockade simultaneously fires a Squirrel Missile.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15"},{"label":"Damage","value":"70"},{"label":"Flight Speed","value":"40 m/s"},{"label":"Explosion Range","value":"8m radius"},{"label":"Special Effect","value":"When Squirrel Girl uses Squirrel Blockade, she simultaneously launches Squirrel Missiles"}]'::jsonb, 6),
  (36453, 'squirrel-girl', null, null, 'ESU ALUMNUS', 'Team-Up Ability', 'Base Effect: Spider-Man gives Squirrel Girl a web bomb. She can launch it to unleash an explosion upon contact with the environment or an enemy, briefly Slowing and damaging enemies caught in the blast. Enhanced Effect: When teaming up with Spider-Man, Squirrel Girl receives more Web Fluid. After throwing Webbed Acorn, viscous web fluid coats the ground alongside the explosion, leaving behind a sticky Web Area. Enemies within suffer a continuous Slow that scales into a Stun if they linger too long.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Spell Field Range","value":"4m spherical radius"},{"label":"Spell Field Damage","value":"65"},{"label":"Slow Duration","value":"3s"},{"label":"Slow Rate","value":"35%"},{"label":"Web Area Range","value":"4m spherical radius"},{"label":"Web Area Damage","value":"2.5/hit, 10 times per second"},{"label":"Web Area Duration","value":"3s"},{"label":"Special Effect","value":"Stunned after remaining in the web zone for 2s"}]'::jsonb, 7),
  (36454, 'black-widow', null, null, 'Widow''s Bite Baton', 'Normal Attack', 'Strike with the enhanced electric batons', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"45"},{"label":"Maximum Distance","value":"3m"},{"label":"Fire Rate","value":"2 strikes per second"}]'::jsonb, 0),
  (36455, 'black-widow', null, null, 'Red Room Rifle', 'Normal Attack', 'Attack with the Red Room Rifle', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast direct hit"},{"label":"Damage","value":"40 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 10m, decreasing to 65% at 40m"},{"label":"Fire Rate","value":"0.25s per hit"},{"label":"Ammo","value":"20"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 1),
  (36456, 'black-widow', null, null, 'ASSASSIN''S FOCUS', 'Ultimate', 'Switch the Red Room Rifle to sniper mode. Shots fired in this state pierce through targets and deal increased damage', '[{"label":"Key","value":"Q"},{"label":"Energy Cost","value":"3100"},{"label":"Bullet Damage","value":"160"},{"label":"Rounds","value":"6"},{"label":"Critical Hit","value":"Yes"},{"label":"Critical Hit Multiplier","value":"1.5x"},{"label":"Fire Rate","value":"0.8s/Round"},{"label":"Maximum Duration","value":"12s"}]'::jsonb, 2),
  (36457, 'black-widow', null, null, 'ELECTRO-PLASMA BLAST', 'Ability', 'Fire an electro-plasma round forward. Upon hitting the environment or an enemy, it explodes and applies a Slow effect', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Charged release, with delayed projectiles."},{"label":"Cooldown","value":"10s"},{"label":"Projectile Speed","value":"100 m/s"},{"label":"Explosion Range","value":"3.5m to 5m radius spherical spell field"},{"label":"Explosion Damage","value":"50~70"},{"label":"Slow Rate","value":"-0.40"},{"label":"Maximum Charge Time","value":"1s"}]'::jsonb, 3),
  (36458, 'black-widow', null, null, 'EDGE DANCER', 'Ability', 'Unleash a spinning kick to Launch Up enemies. Landing the hit will allow her to zip to the target with a grappling hook for a second kick', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Melee"},{"label":"Spinning Kick Damage","value":"35"},{"label":"Maximum Distance","value":"5m"},{"label":"Flying Kick Distance","value":"12m"},{"label":"Second Flying Kick Damage","value":"35"},{"label":"Flying Kick Stun Duration","value":"0.2s"},{"label":"Flying Kick Casting Window","value":"5s"},{"label":"Cooldown","value":"15s"}]'::jsonb, 4),
  (36459, 'black-widow', null, null, 'WIDOW''S BITE SLAM', 'Ability', 'Leap toward a target area and slam the ground with her Widow''s Bite gauntlet, dealing damage to enemies within range', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Targeted"},{"label":"Damage","value":"30"},{"label":"Cooldown","value":"15s"},{"label":"Damage Range","value":"5m radius"}]'::jsonb, 5),
  (36460, 'black-widow', null, null, 'ALLIED AGENTS', 'Team-Up Ability', 'Base Effect: Landing hits with Red Room Rifle builds Focus. At three stacks, enter a Focused state where the next bullet gains the Hunter''s Sight effect, granting Damage Boost and pierce effects. Enhanced Effect: When teaming up with Hawkeye, landing a critical hit prevents the Focused state from expiring, allowing continuous enhanced fire until missing a crit.', '[{"label":"Key","value":"Passive"},{"label":"Focus Gained On Crit","value":"2 stacks"},{"label":"Focus Gained On Red Room Rifle Hit","value":"1 stack"},{"label":"Focused State Bullet Damage","value":"55 damage per round"},{"label":"Special Effect","value":"Landing a critical hit prevents the Focused state from expiring, allowing continuous enhanced fire until missing a crit."}]'::jsonb, 6),
  (36461, 'black-widow', null, null, 'BURNING BULLETS', 'Team-Up Ability', 'Base Effect: Activation grants the Red Room Rifle a Fire Rate Boost. Additionally, the Plasma Cannon projectile becomes a hitscan laser that no longer requires charging. Enhanced Effect: When teaming up with Phoenix, her Plasma Cannon gains a second ability charge.', '[{"label":"Key","value":"Passive"},{"label":"Fire Rate Increase","value":"15%"},{"label":"Plasma Cannon Damage","value":"70"},{"label":"Plasma Cannon Cooldown","value":"10s"},{"label":"Plasma Cannonrange","value":"5m spherical radius"},{"label":"Plasma Cannon Slow Effect","value":"40% for 3s"},{"label":"Special Effect","value":"Plasma Cannon has 2 charges"}]'::jsonb, 7),
  (36462, 'wolverine', null, null, 'Savage Claw', 'Normal Attack', 'Slash with Adamantium claws for a Claw Strike. Unleashing Feral Leap will enhance it to Berserk Claw Strike for a brief period', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Base Damage","value":"18 damage per strike"},{"label":"Percentage Damage","value":"Deal damage equal to 1.5% of the target''s Max Health, with an extra 0.062% damage for each point of Rage"},{"label":"Maximum Distance","value":"3.5m"},{"label":"Attack Interval","value":"The first three strikes have an interval of 0.27s between them, while the fourth strike has a 0.84s interval from the third strike"}]'::jsonb, 0),
  (36463, 'wolverine', null, null, 'Last Stand', 'Ultimate', 'Knock enemies ahead airborne and spiral through the air, sweeping up enemies along the path and delivering a devastating impact at the landing point', '[{"label":"Key","value":"Q"},{"label":"Knockback Range","value":"8m spherical radius"},{"label":"Knockback Damage","value":"50"},{"label":"Snatching Damage Over Time","value":"20/s"},{"label":"Impact Range","value":"8m spherical radius"},{"label":"Impact Base Damage","value":"50"},{"label":"Impact Percentage Damage","value":"Deal damage equal to 10% of the target''s Max Health, with an extra 0.3% damage for each point of Rage"},{"label":"Knockdown Time","value":"0.75s"},{"label":"Energy Cost","value":"2800"}]'::jsonb, 1),
  (36464, 'wolverine', null, null, 'Feral Leap', 'Ability', 'Leap like an animal to snatch the first enemy upon impact and Smash them to the ground. Unleashing this ability will enhance his normal attack to Berserk Claw Strike for a brief period', '[{"label":"Key","value":"SHIFT"},{"label":"Snatch Damage","value":"35"},{"label":"Smash Damage","value":"35"},{"label":"Knockdown Duration","value":"0.75s"},{"label":"Berserk Claw Strike Duration","value":"5s"},{"label":"Berserk Claw Strike Base Damage","value":"8 damage per strike"},{"label":"Berserk Claw Strike Percentage Damage","value":"Deal damage equal to 1% of the target''s Max Health, with an extra 0.025% damage for each point of Rage"},{"label":"Berserk Claw Strike Maximum Distance","value":"3.5m"},{"label":"Berserk Claw Strike Attack Interval","value":"5.88 strikes per second"},{"label":"Cooldown","value":"12s"}]'::jsonb, 2),
  (36465, 'wolverine', null, null, 'Undying Animal', 'Ability', 'Unleash a fierce howl to briefly reduce incoming damage', '[{"label":"Key","value":"E"},{"label":"Duration","value":"5s"},{"label":"Damage Reduction","value":"40%"},{"label":"Cooldown","value":"16s"}]'::jsonb, 3),
  (36466, 'wolverine', null, null, 'Vicious Rampage', 'Ability', 'Dash forward and unleash a Claw Strike', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Movement-based damage ability"},{"label":"Average Speed","value":"44m/s"},{"label":"Maximum Distance","value":"7.5m"},{"label":"Range","value":"3m"},{"label":"Base Damage","value":"15 damage per strike"},{"label":"Percentage Damage","value":"Deal damage equal to 1.5% of the target''s Max Health, with an extra 0.057% damage for each point of Rage"},{"label":"Cooldown","value":"3s"}]'::jsonb, 4),
  (36467, 'wolverine', null, null, 'Regenerative Healing Factor', 'Passive', 'Begin to heal and rise with a hefty Bonus Health, shaking off all debuffs. After a brief moment, any remaining Bonus Health morphs into a one-off heal, zeroing out his Rage. Assists in KOs reduce this cooldown', '[{"label":"Key","value":"Passive"},{"label":"Bonus Health","value":"300"},{"label":"Bonus Health Duration","value":"3s"},{"label":"Bonus Health/Healing Conversion","value":"1"},{"label":"Cooldown Reduction Per Ko Engaged","value":"10s"},{"label":"Cooldown","value":"90s"}]'::jsonb, 5),
  (36468, 'wolverine', null, null, 'Berserker Rage', 'Passive', 'Rage builds when Wolverine attacks or takes hits, boosting the damage of his Claw Strikes and the Bonus Health from his regenerative healing factor', '[{"label":"Key","value":"Passive"},{"label":"Max Rage","value":"100"},{"label":"Rage Per Savage Claw Hit","value":"10"},{"label":"Rage Per Vicious Rampage Hit","value":"15"},{"label":"Rage Per Feral Leap Snatch","value":"10"},{"label":"Rage Per Berserk Claw Strike Hit","value":"5"},{"label":"Rage Per Last Stand Knockback","value":"25"},{"label":"Rage Per Hit Taken","value":"8"},{"label":"Rage Gain From Taking Hits","value":"2 per second"}]'::jsonb, 6),
  (36469, 'wolverine', null, null, 'Phoenix Warrior', 'Team-Up Ability', 'Wolverine and Hulk can interact with each other. Once both parties confirm, Hulk can lift Wolverine and press the key to hurl him forwardJean Grey imbues Wolverine with the awe-inspiring Phoenix Force. With this power, Wolverine''s Feral Leap transforms into Phoenix Warrior. While active, he is enveloped in Phoenix flames that continuously scorch him and nearby enemies, dealing Percentage Damage. In this state, Wolverine''s abilities gain Lifesteal when inflicting damage', '[{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"15s"},{"label":"Spell Field Range","value":"3m spherical radius spell field"},{"label":"Spell Field Damage","value":"Deal damage equals to target''s 1% Maximum Health per second"},{"label":"Lifesteal Proportion","value":"0.33"},{"label":"Snatch Damage","value":"35"},{"label":"Smash Damage","value":"35"},{"label":"Knockdown Duration","value":"0.75s"},{"label":"Berserk Claw Strike Duration","value":"5s"},{"label":"Berserk Claw Strike Base Damage","value":"6 damage per strike"},{"label":"Berserk Claw Strike Percentage Damage","value":"Deal damage equal to 1% of the target''s Max Health, with an extra 0.035% damage for each point of Rage."},{"label":"Berserk Claw Strike Maximum Distance","value":"3.5m"},{"label":"Berserk Claw Strike Attack Interval","value":"5.88 strikes per second"}]'::jsonb, 7),
  (36470, 'wolverine', null, null, 'Kinetic Claws', 'Team-Up Ability', 'Cyclops supercharges Wolverine''s claws, extending his attack range. While active, Wolverine''s Vicious Rampage is replaced with Kinetic Claws, granting him a brief forward lunge that unleashes a flurry of slashes around him', '[{"label":"Key","value":"X"},{"label":"Ability Cooldown","value":"20s"},{"label":"Ability Duration","value":"8s"},{"label":"Attack Range Bonus:","value":"1m"},{"label":"Kinetic Claws Cooldown","value":"3s"},{"label":"Kinetic Claws Damage Tick Rate:","value":"0.1s"},{"label":"Kinetic Claws Damage:","value":"5 + 0.01% Max HP per Rage point"},{"label":"Kinetic Claws Duration:","value":"1.5s"}]'::jsonb, 8),
  (36471, 'wolverine', null, null, 'BLAST SLASH', 'Team-Up Ability', 'Base Effect: Activation extends the attack range of Savage Claw and Berserk Claw Strike. Vicious Rampage is replaced with Kinetic Claws, granting a brief forward lunge that unleashes a flurry of slashes around. Enhanced Effect: When teaming up with Cyclops, Blast Slash is permanently active.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20"},{"label":"Ability Duration","value":"8s"},{"label":"Attack Range Increase","value":"1m"},{"label":"Kinetic Claws Cooldown","value":"3s"},{"label":"Kinetic Claws Damage","value":"5 + 0.012% of Max Health as damage per Rage point"},{"label":"Kinetic Claws Duration","value":"1s"},{"label":"Special Effect","value":"Blast Slash is permanently active."}]'::jsonb, 9),
  (36472, 'wolverine', null, null, 'PAIR OF THREES', 'Team-Up Ability', 'Base Effect: Upon activation, Wolverine receives Kinetic Enhancement, gaining increased Movement Speed and a Jump Boost. Attacking enemies applies Kinetic Particles that detonate after a short delay for bonus damage. The effect lasts for duration. Enhanced Effect: When teaming up with Gambit, Wolverine receives Continuous Healing for the entire duration of the ability.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Ability Duration","value":"5s"},{"label":"Movement Boost","value":"35%"},{"label":"Bonus Jump Height","value":"350"},{"label":"Bonus Damage Tick Interval","value":"0.5"},{"label":"Bonus Damage","value":"15%"},{"label":"Healing Amount","value":"25/s"}]'::jsonb, 10),
  (36473, 'cloak-and-dagger', null, null, 'Darkforce Cloak', 'Normal Attack', 'Inflict continuous damage on an enemy', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Cylindrical Spell Field"},{"label":"Special Effect","value":"Attacks will target the nearest enemy to the crosshair, dealing damage"},{"label":"Damage","value":"80/s"},{"label":"Range","value":"20m"},{"label":"Ammo","value":"∞"},{"label":"Critical Hit","value":"No"}]'::jsonb, 0),
  (36474, 'cloak-and-dagger', null, null, 'Eternal Bond', 'Ultimate', 'Perform four rapid dashes, healing allies and damaging enemies along the path', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Persistent Spell Field"},{"label":"Damage","value":"30/s"},{"label":"Healing Amount","value":"250/s"},{"label":"Range","value":"A cylindrical spell field with a 4m radius and 15m in length"},{"label":"Duration","value":"11s"},{"label":"Energy Cost","value":"4500"},{"label":"Enhanced Duration","value":"13s"}]'::jsonb, 1),
  (36475, 'cloak-and-dagger', null, null, 'Light''s Embrace', 'Ability', 'Switch to Dagger', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Instant Cast"}]'::jsonb, 2),
  (36476, 'cloak-and-dagger', null, null, 'Terror Cape', 'Ability', 'Deploy a Veil of Darkforce to damage enemies upon touch, applying Blind to narrow their sight and Vulnerability to amplify damage received', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Spell Field"},{"label":"Special Effect","value":"The spell field advances along the casting path"},{"label":"Damage","value":"55"},{"label":"Blinding Duration","value":"1.5s"},{"label":"Range","value":"Visibility is obstructed beyond 10m"},{"label":"Vulnerability","value":"20%"},{"label":"Vulnerability Duration","value":"3s"},{"label":"Range","value":"Width: 6m, Height: 4.5m"},{"label":"Movement Speed","value":"20m/s"},{"label":"Maximum Distance","value":"25m"},{"label":"Cooldown","value":"Veil of Lightforce & Terror Cape share charges, capped out at 2 with each taking 10s to recharge. After using either, both abilities enter a 2s cooldown"}]'::jsonb, 3)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36477, 'cloak-and-dagger', null, null, 'Dark Teleportation', 'Ability', 'Enshroud nearby allies in the Darkforce Dimension, plunging them into the Phased state, making them untargetable and invisible to enemies and granting them a Movement Boost', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Persistent Spell Field"},{"label":"Special Effect","value":"Allies within the area gain Invisibility and Movement Boost"},{"label":"Duration","value":"2s"},{"label":"Range","value":"10m spherical radius"},{"label":"Cooldown","value":"12s"}]'::jsonb, 4),
  (36478, 'cloak-and-dagger', null, null, 'FROM SHADOW TO LIGHT', 'Team-Up Ability', 'Cloak & Dagger inject light and dark energy into Hawkeye''s katana. When Hawkeye uses Crescent Slash, enemies hit are launched back, and a blade wave filled with light and energy sweeps forward. This wave passes through both allies and enemies: it heals and boosts healing for allies, while damaging enemies and applying Vulnerability', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"15% Healing Boost"}]'::jsonb, 5),
  (36479, 'cloak-and-dagger', null, null, 'Lightforce Dagger', 'Normal Attack', 'Unleash a bouncing Lightforce Dagger to damage enemies and heal nearby allies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast projectile that generates a spell area upon impact"},{"label":"Special Effect","value":"The projectile features an attraction effect, pulling in the closest target to the crosshair and creating a spell field upon impact. This spell field provides healing effects"},{"label":"Damage","value":"18 damage per round"},{"label":"Healing Per Hit","value":"15 per hit"},{"label":"Area Of Effect Healing","value":"20 per hit"},{"label":"Range","value":"8m spherical radius"},{"label":"Fire Rate","value":"2.27 hits per second"},{"label":"Ammo","value":"12"},{"label":"Critical Hit","value":"No"}]'::jsonb, 6),
  (36480, 'cloak-and-dagger', null, null, 'Shadow''s Embrace', 'Ability', 'Switch to Cloak', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Instant Cast"}]'::jsonb, 7),
  (36481, 'cloak-and-dagger', null, null, 'Veil of Lightforce', 'Ability', 'Deploy a Veil of Lightforce to heal allies upon touch and grant them a Healing Boost', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Spell Field"},{"label":"Special Effect","value":"The spell field advances along the casting path"},{"label":"Healing Amount","value":"50"},{"label":"Healing Boost","value":"20%"},{"label":"Duration","value":"4s"},{"label":"Range","value":"Width: 6m, Height: 4.5m"},{"label":"Movement Speed","value":"20m/s"},{"label":"Maximum Distance","value":"25m"},{"label":"Cooldown","value":"Veil of Lightforce & Terror Cape share charges, capped out at 2 with each taking 10s to recharge. After using either, both abilities enter a 2s cooldown"}]'::jsonb, 8),
  (36482, 'cloak-and-dagger', null, null, 'Dagger Storm', 'Ability', 'Launch a volley of daggers, creating a Healing Over Time field in the impact area', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact that also generates a spell field"},{"label":"Healing Amount","value":"50/s"},{"label":"Duration","value":"6s"},{"label":"Range","value":"5m spherical radius"},{"label":"Cooldown","value":"12s"},{"label":"Special Effect","value":"When a Spell Field is created, allies in range get a One-Time Healing of 60"}]'::jsonb, 9),
  (36483, 'cloak-and-dagger', null, null, 'OBLIVION SHROUD', 'Team-Up Ability', 'Base Effect: Veil of Lightforce and Terror Cape are warped by hellfire energy, changing into Veil of Light and Veil of Darkness while retaining their original effects. After traveling a set distance, the veils halt in place. Enemy damage passing through the Veil of Light is weakened, while enemy healing passing through the Veil of Darkness suffers Healing Reduction. Enhanced Effect: When teaming up with The Hood, the width of both the Veil of Light and Veil of Darkness expands. Additionally, allies passing through the veils are empowered by hellfire energy, gaining Damage Boost for a duration.', '[{"label":"Key","value":"E"},{"label":"Light Veil Enemy Damage Reduction","value":"20%"},{"label":"Dark Veil Enemy Healing Reduction","value":"20%"},{"label":"Veil Duration","value":"4s"},{"label":"Veil Range","value":"6m wide, 4.5m tall"},{"label":"Damage Boost","value":"15%"},{"label":"Enhanced Veil Range","value":"8m wide, 6m tall"}]'::jsonb, 10),
  (36484, 'cloak-and-dagger', null, null, 'FROZEN HAVEN', 'Team-Up Ability', 'Base Effect: Channel frost energy outward to encase yourself in an absolute block of ice. This offers great protection, but Freezes you in place. While frozen, you can be healed and emit a weak healing aura to nearby allies. Enhanced Effect: When teaming up with Luna Snow, the healing aura provided to allies while Frozen becomes significantly stronger.', '[{"label":"Key","value":"C"},{"label":"Ability Duration","value":"2s"},{"label":"Spell Field Range","value":"8m radius"},{"label":"Healing Amount","value":"50/s"},{"label":"Cooldown","value":"20s"},{"label":"Enhanced Healing Amount","value":"90/s"}]'::jsonb, 11),
  (36485, 'iron-fist', null, null, 'Jeet Kune Do', 'Normal Attack', 'Strike the targeted enemy with Jeet Kune Do, reducing the cooldown of Block and Strike with every hit', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"The first four strikes each deal 38 damage, while the fifth strike deals 60 damage"},{"label":"Maximum Distance","value":"3m"},{"label":"Attack Interval","value":"The first four strikes have an interval of 0.45s between them, while the fifth strike has a 0.67s interval from the fourth strike"},{"label":"Maximum Pull-In Distance","value":"6m"},{"label":"Dragon''S Defense Cooldown Reduction Per Hit","value":"1.2s"}]'::jsonb, 0),
  (36486, 'iron-fist', null, null, 'Yat Jee Chung Kuen', 'Normal Attack', 'Dash forward to pursue the targeted enemy and unleash a flurry of attacks', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Duration","value":"5s"},{"label":"Maximum Pull-In Distance","value":"11m"},{"label":"Dashing Speed Without Target","value":"12 m/s"},{"label":"Dashing Distance Without Target","value":"3m"},{"label":"Range","value":"3m"},{"label":"Damage","value":"8 base damage + 3.1% of the enemy''s Max Health per strike"},{"label":"Attack Speed","value":"7 strikes per second"}]'::jsonb, 1),
  (36487, 'iron-fist', null, null, 'Living Chi', 'Ultimate', 'Become living Chi to boost his speed, damage, and attack range, delivering stronger punches while reducing the cooldown of Dragon''s Defense', '[{"label":"Key","value":"Q"},{"label":"Duration","value":"12s"},{"label":"Yat Jee Chung Kuen Bonus Range","value":"100%"},{"label":"K''Un-Lun Kick Bonus Range","value":"100%"},{"label":"Damage Boost","value":"30%"},{"label":"Movement Boost","value":"20%"},{"label":"Yat Jee Chung Kuen Cooldown Reduction","value":"-80%"},{"label":"Energy Cost","value":"3100"}]'::jsonb, 2),
  (36488, 'iron-fist', null, null, 'K''un-Lun Kick', 'Ability', 'Dash forward, delivering a flying kick when hitting an enemy or reaching full range, dealing damage to nearby enemies. Damage increases with lower enemy health', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Movement-based damage ability"},{"label":"Dashing Speed","value":"40 m/s"},{"label":"Maximum Dash Distance","value":"12m"},{"label":"First Flying Kick Damage","value":"40"},{"label":"Second Flying Kick Damage","value":"35 - 70 (Maximum damage is achieved when the target is at 50% Health)"},{"label":"Cooldown","value":"10s"}]'::jsonb, 3),
  (36489, 'iron-fist', null, null, 'Harmony Recovery', 'Ability', 'Cross legs and channel Chi, slowly gaining Bonus Health', '[{"label":"Key","value":"E"},{"label":"Duration","value":"3s"},{"label":"Healing Per Second","value":"100"},{"label":"Excess Healing/Max Health Conversion","value":"100"},{"label":"Cooldown","value":"12s"}]'::jsonb, 4),
  (36490, 'iron-fist', null, null, 'Crane Leap', 'Ability', 'Perform up to three consecutive jumps while airborne', '[{"label":"Key","value":"Space"},{"label":"Cooldown","value":"3 charges, with each charge taking 1s to recharge"}]'::jsonb, 5),
  (36491, 'iron-fist', null, null, 'Dragon''s Defense', 'Ability', 'Assume a defensive stance with a boost of Chi to block incoming attacks and gain Damage Reduction, then strike back with Yat Jee Chung Kuen', '[{"label":"Key","value":"Right Click"},{"label":"Block Time","value":"1.2s"},{"label":"Damage Reduction","value":"30%"},{"label":"Bonus Health/Damage Blocked Conversion","value":"1.3"},{"label":"Max Health/Damage Blocked Conversion","value":"175"},{"label":"Cooldown","value":"15s"}]'::jsonb, 6),
  (36492, 'iron-fist', null, null, 'Wall Runner', 'Ability', 'Run horizontally along the walls', '[{"label":"Key","value":"Space"},{"label":"Wall-Crawling Speed","value":"9 m/s"}]'::jsonb, 7),
  (36493, 'iron-fist', null, null, 'Chi Absorption', 'Passive', 'Assists in taking down enemies allow him to absorb their Chi and gain Bonus Health', '[{"label":"Key","value":"Passive"},{"label":"Bonus Health","value":"50"}]'::jsonb, 8),
  (36494, 'iron-fist', null, null, 'Lunar Chi', 'Team-Up Ability', 'Luna Snow grants Winter''s Chill to Hawkeye and Iron Fist. When Iron Fist activates Harmony Recovery, he can heal nearby allies with Lunar Chi', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Cylindrical Spell Field"},{"label":"Special Effect","value":"Excess healing converts to Bonus Health."},{"label":"Cooldown","value":"12s"},{"label":"Healing Range","value":"A cylindrical spell field with a 10m radius and a height of 10m."},{"label":"Healing Amount","value":"55/s"},{"label":"Duration","value":"3s"},{"label":"Bonus Health Falloff Delay","value":"2s"},{"label":"Bonus Health Falloff Speed","value":"15/s"}]'::jsonb, 9),
  (36495, 'iron-fist', null, null, 'IRON & STONE', 'Team-Up Ability', 'Base Effect: Unleash a powerful uppercut to Launch Up enemies. Enhanced Effect: When teaming up The Thing, unleashing the uppercut can be chained directly into a sweeping leg sweep for a follow-up attack.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"8s"},{"label":"Damage Distance","value":"5m"},{"label":"Damage","value":"45"},{"label":"Enhanced Key","value":"Left Click"},{"label":"Enhanced Damage","value":"50"}]'::jsonb, 10),
  (36496, 'iron-fist', null, null, 'KUMIHO PALM', 'Team-Up Ability', 'Base Effect: Hitting an enemy with Yat Jee Chung Kuen provides a burst of healing to nearby allies. Enhanced Effect: When teaming up White Fox, the lock-on distance for Yat Jee Chung Kuen is significantly increased.', '[{"label":"Key","value":"Passive"},{"label":"Healing Amount","value":"6"},{"label":"Spell Field Range","value":"6m spherical radius"},{"label":"Targetless Dash Speed Increase","value":"4 m/s"},{"label":"Target Selection Max Range Increase","value":"2m"},{"label":"Enhanced Healing Amount","value":"7.5"}]'::jsonb, 11),
  (36497, 'psylocke', null, null, 'Psionic Crossbow', 'Normal Attack', 'Unleash bolts with psionic crossbows to damage enemies and reduce the cooldowns of all her abilities', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Double projectile with spread"},{"label":"Damage","value":"12 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 8m, decreasing to 70% at 30m"},{"label":"Bullets Fired Each Cast","value":"4"},{"label":"Crosshair Spread Radius (At 10m)","value":"0.2m"},{"label":"Fire Rate","value":"The firing interval between shots is 0.2s, with an interval of 0.6s between each round of shooting"},{"label":"Ammo","value":"16"},{"label":"Critical Hit","value":"Yes"},{"label":"Critical Damage","value":"150%"},{"label":"Cooldown Reduction On Hit","value":"0.3s per hit"}]'::jsonb, 0),
  (36498, 'psylocke', null, null, 'Dance of the Butterfly', 'Ultimate', 'Slash nearby enemies with a psionic katana, dealing massive damage', '[{"label":"Key","value":"Q"},{"label":"Range","value":"10m spherical radius"},{"label":"Duration","value":"4s"},{"label":"Slow Rate","value":"-15%"},{"label":"Attack Interval","value":"2 hits per second"},{"label":"Damage","value":"160 damage per hit"},{"label":"Energy Cost","value":"3400"},{"label":"Special Mechanic","value":"Psylocke will slash a random enemy, giving priority to the one who has been hit the least"}]'::jsonb, 1),
  (36499, 'psylocke', null, null, 'Psi-Blade Dash', 'Ability', 'Dash forward and slice through enemies along the path with psionic blades', '[{"label":"Key","value":"Shift"},{"label":"Average Speed","value":"43 m/s"},{"label":"Maximum Distance","value":"12m"},{"label":"Damage","value":"50"},{"label":"Cooldown","value":"12s"},{"label":"Charges","value":"2"},{"label":"Special Mechanic","value":"Casting this ability will automatically recall the Wing Shurikens. The shurikens will first travel to Psylocke''s starting position before returning to her"}]'::jsonb, 2),
  (36500, 'psylocke', null, null, 'Psychic Stealth', 'Ability', 'Enter stealth and gain a Movement Boost', '[{"label":"Key","value":"E"},{"label":"Duration","value":"2s"},{"label":"Movement Boost","value":"50%"},{"label":"Cooldown","value":"15s"},{"label":"Special Mechanic","value":"When attacked while in stealth, Psylocke will remain in stealth but will briefly become visible for a short duration"}]'::jsonb, 3),
  (36501, 'psylocke', null, null, 'Wing Shurikens', 'Ability', 'Launch a volley of psionic shurikens that stick to enemies, dealing damage and granting herself Bonus Health. Press again to recall the shurikens', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Projectile that fires in a straight trajectory."},{"label":"Number Of Projectiles","value":"5"},{"label":"Recall Window","value":"3s"},{"label":"Bonus Health","value":"10 bonus health per round"},{"label":"Cooldown","value":"8s"},{"label":"Special Mechanic","value":"When the projectile is recalled, it will move 20s toward the crosshair before returning to Psylocke"},{"label":"Damage","value":"10 damage per round"},{"label":"Projectile Speed","value":"120 m/s"},{"label":"Spread Angle","value":"0.86°"},{"label":"Maximum Distance","value":"25m"},{"label":"Damage Falloff","value":"Falloff begins at 15m, decreasing to 80% at 25m"},{"label":"Damage","value":"10 per hit"},{"label":"Projectile Speed","value":"150 m/s"}]'::jsonb, 4)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36502, 'psylocke', null, null, 'LIGHT & DARK DARTS', 'Team-Up Ability', 'Cloak & Dagger share light and dark energy with Hawkeye and Psylocke. When Hawkeye uses Crescent Slash, he also releases a blade wave that heals and boosts healing for teammates, while inflicting damage and Vulnerability on enemies. Psylocke can launch a Light Boomerang Dart that heals allies, harms enemies, and provides her with temporary healing upon return. She can also unleash a ring of Dark Darts that slow enemies while she briefly enters a Phased state', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Key","value":"Left Click"},{"label":"Projectile Damage","value":"Deal 40 damage upon unleashing and 20 damage when retrieved."},{"label":"Projectile Healing","value":"Heal 60 health upon unleashing and 30 health when retrieved."},{"label":"Projectile Speed","value":"150 m/s"},{"label":"Projectile Maximum Flight Duration","value":"30m"},{"label":"Self Healing","value":"35/s"},{"label":"Self Healing Duration","value":"Grant 2s of self healing for each target hit"},{"label":"Key","value":"Right Click"},{"label":"Projectile Damage","value":"Deal 50 damage. Affect a single target at most once."},{"label":"Projectile Speed","value":"100 m/s"},{"label":"Slow Rate","value":"35%"},{"label":"Slow Duration","value":"3s"},{"label":"Phased State Duration","value":"2s"}]'::jsonb, 5),
  (36503, 'psylocke', null, null, 'MENTAL PROJECTION', 'Team-Up Ability', 'Base Effect: Create an illusory projection that automatically dashes forward to use Psi-Blade Dash, while Psylocke enters Stealth. If Psylocke attacks, the illusion mimics her strikes. Enhanced Effect: When teaming up with Emma Frost, Psylocke''s mental powers are elevated, allowing her to reactivate the ability to instantly swap places with her illusion.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Flex Up","value":"0.5"},{"label":"Illusion Damage","value":"15%"},{"label":"Magnetic Projection Max Duration","value":"3s"},{"label":"Special Effect","value":"While the illusion exists, reactivate the ability to swap places with the Psionic Illusion, up to once"}]'::jsonb, 6),
  (36504, 'psylocke', null, null, 'LIGHT & DARK DARTS', 'Team-Up Ability', 'Base Effect: Unleash a ring of Light Darts in all directions that damage enemies and restore Psylocke''s Health upon impact, leaving behind a Shadow Domain. Staying inside the domain for a short time will re-enter Stealth. Enhanced Effect: When teaming up with Cloak & Dagger, the radius of the Shadow Domain expands, and each time re-entering Stealth, the Light Darts are fired in all directions again.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Projectile Damage","value":"30"},{"label":"Healing Amount","value":"20"},{"label":"Field Duration","value":"5s"},{"label":"Field Range","value":"6m spherical radius"},{"label":"Psionic Crossbow Base Damage Per Shot","value":"13"},{"label":"Enhanced Field Range","value":"8m spherical radius"}]'::jsonb, 7),
  (36505, 'hawkeye', null, null, 'Piercing Arrow', 'Normal Attack', 'Shoot a powerful arrow', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Charged projectile with an arced trajectory"},{"label":"Slow Rate While Charging","value":"-20%"},{"label":"Minimum Charge Time","value":"0.7s"},{"label":"Projectile Speed","value":"140 - 210 m/s (Maximum speed is achieved after 0.9s of charging)"},{"label":"Damage","value":"28 - 70 (Maximum damage is achieved after 0.9s of charging)"},{"label":"Ammo","value":"Infinite"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36506, 'hawkeye', null, null, 'Blast Arrow', 'Normal Attack', 'Shoot three explosive arrows', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Arced projectile that generates a spell field upon impact"},{"label":"Slow Rate While Charging","value":"-20%"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Projectile Damage","value":"16"},{"label":"Range","value":"3m spherical radius"},{"label":"Spell Field Damage","value":"34"},{"label":"Blast Arrows Per Cast","value":"3"},{"label":"Spread Angle","value":"11.3°"},{"label":"Cooldown","value":"0.5s"},{"label":"Charges","value":"3"}]'::jsonb, 1),
  (36507, 'hawkeye', null, null, 'Hunter''s Sight', 'Ultimate', 'Capture Afterimages of enemies in his view. Damage dealt to an Afterimage is transferred to the corresponding enemy', '[{"label":"Key","value":"Q"},{"label":"Duration","value":"10s"},{"label":"Afterimage Generation Interval","value":"0.5s"},{"label":"Afterimage Duration","value":"3s"},{"label":"Draw Speed Boost Multiplier","value":"1.5"},{"label":"Energy Cost","value":"3100"},{"label":"Special Mechanic","value":"While Hunter''s Sight is active, bow draw speed is increased"}]'::jsonb, 2),
  (36508, 'hawkeye', null, null, 'Crescent Slash', 'Ability', 'Unsheathe a katana and slash forward, launching up enemies hit', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Melee"},{"label":"Maximum Distance","value":"8m"},{"label":"Damage","value":"40"},{"label":"Cooldown","value":"12s"}]'::jsonb, 3),
  (36509, 'hawkeye', null, null, 'Hypersonic Arrow', 'Ability', 'Shoot a Hypersonic Arrow, dealing two instances of damage to enemies in its path and inflicting them with Slow. This ability can Knock Down flying heroes', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Straight-line projectile that is accompanied by a spell field"},{"label":"Projectile Speed","value":"150 m/s"},{"label":"First Spell Field Range","value":"Length: 3m, Width: 5m, Height: 2.7m"},{"label":"First Damage","value":"55"},{"label":"Second Spell Field Range","value":"Length: 3m, Width: 5m, Height: 1.6m"},{"label":"Second Damage","value":"55"},{"label":"Slow Rate","value":"-40%"},{"label":"Slow Duration","value":"1s"},{"label":"Cooldown","value":"12s"}]'::jsonb, 4),
  (36510, 'hawkeye', null, null, 'Ronin Slash', 'Ability', 'Swing a wakizashi to strike frontal enemies, deflecting all incoming projectiles', '[{"label":"Key","value":"V"},{"label":"Casting","value":"Melee"},{"label":"Maximum Distance","value":"3m"},{"label":"Special Effect","value":"This ability cannot block explosions or effects created by projectiles on hit"}]'::jsonb, 5),
  (36511, 'hawkeye', null, null, 'Skyward Leap', 'Ability', 'Perform a double jump in the direction of movement', '[{"label":"Key","value":"Space"},{"label":"Cooldown","value":"6s"}]'::jsonb, 6),
  (36512, 'hawkeye', null, null, 'Archer''s Focus', 'Passive', 'Aim at an enemy to improve focus, enhancing the damage inflicted by Piercing Arrow', '[{"label":"Key","value":"Passive"},{"label":"Bonus Damage","value":"0 - 90 (Maximum damage is achieved after 0.9s of aiming)"},{"label":"Triggering Distance","value":"40m"},{"label":"Critical Hit","value":"Yes"},{"label":"Special Mechanic","value":"Apply bonus damage to the base damage of Piercing Arrow"}]'::jsonb, 7),
  (36513, 'hawkeye', null, null, 'MOONLIT SLASH', 'Team-Up Ability', 'Cloak & Dagger inject light and dark energy into Hawkeye''s katana. When Hawkeye uses Crescent Slash, enemies hit are launched back, and a blade wave filled with light and energy sweeps forward. This wave passes through both allies and enemies: it heals and boosts healing for allies, while damaging enemies and applying Vulnerability', '[{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"12s"},{"label":"Blade Wave Speed","value":"60 m/s"},{"label":"Blade Wave Range","value":"Length: 2m, Width: 6m, Height: 2m"},{"label":"Blade Wave Damage","value":"60"},{"label":"Vulnerability Ratio","value":"0.15"},{"label":"Vulnerability Duration","value":"4s"},{"label":"Blade Wave Healing","value":"60"},{"label":"Healing Boost","value":"0.15"},{"label":"Healing Boost Duration","value":"4s"}]'::jsonb, 8),
  (36514, 'hawkeye', null, null, 'SENBONZAKURA STRIKE', 'Team-Up Ability', 'Base Effect: Upgrade Blast Arrow to Psionic Arrow. While drawn, Hawkeye can continuously bank extra Psionic Arrows. Releasing the bowstring rapidly fires all accumulated arrows forward in sequence. Enhanced Effect: When teaming up with Psylocke, the nocking speed for each Psionic Arrow is significantly quickened, and they explode upon hitting enemies or the environment.', '[{"label":"Key","value":"Left Click"},{"label":"Charge Time Per Arrow (S)","value":"0.09"},{"label":"Spread Type","value":"Fixed spread"},{"label":"Psionic Arrows Fired","value":"5"},{"label":"Psionic Arrow Damage","value":"33/shot"},{"label":"Enhanced Charge Time Per Arrow (S)","value":"0.07"},{"label":"Enhanced Psionic Arrow Damage","value":"24/shot"},{"label":"Psionic Arrow Explosion Damage","value":"8 damage per round"},{"label":"Explosion Range","value":"2m spherical radius spell field"}]'::jsonb, 9),
  (36515, 'hawkeye', null, null, 'MOONLIT SLASH', 'Team-Up Ability', 'Base Effect: Upgrade Crescent Slash to Moonlit Slash, projecting a radiant slash outward. It heals and boosts healing for allies, while damaging enemies and applying Vulnerability. Enhanced Effect: When teaming up with Cloak & Dagger, Moonlit Slash can be chained into a three-hit combo, firing off three consecutive sweeping light blades.', '[{"label":"Key","value":"Shift"},{"label":"Light Blade Damage","value":"65"},{"label":"Vulnerability Rate","value":"15% for 4s"},{"label":"Light Blade Healing","value":"65"},{"label":"Healing Boost Rate","value":"15% for 4s"},{"label":"Enhanced Light Blade Damage","value":"35/shot, 3 shots total"},{"label":"Sword Aura Healing","value":"35/shot, 3 shots total"}]'::jsonb, 10),
  (36516, 'iron-man', null, null, 'Repulsor Blast', 'Normal Attack', 'Fire nano pulse cannons forward', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Ammo","value":"100"},{"label":"Critical Hit","value":"No"},{"label":"Special Mechanic 1","value":"After firing the one-handed repulsor twice in a row, the next attack will fire two repulsors at once"},{"label":"Special Mechanic 2","value":"Repulsor Blast and Unibeam share the same ammo count"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Damage","value":"35"},{"label":"Range","value":"3m spherical radius"},{"label":"Spell Field Damage","value":"45"},{"label":"Spell Field Damage Falloff","value":"40% falloff at 3m"},{"label":"Fire Rate","value":"1.67 rounds per second"},{"label":"Ammo Consumption","value":"10 damage per round"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Damage","value":"50"},{"label":"Range","value":"5m spherical radius"},{"label":"Spell Field Damage","value":"50"},{"label":"Spell Field Damage Falloff","value":"40% falloff at 5m"},{"label":"Fire Rate","value":"1.39 rounds per second"},{"label":"Ammo Consumption","value":"16 damage per round"}]'::jsonb, 0),
  (36517, 'iron-man', null, null, 'Repulsor Blast (Armor Overdrive)', 'Normal Attack', 'Fire nano pulse cannons forward', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Ammo","value":"Infinite"},{"label":"Critical Hit","value":"No"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Damage","value":"45"},{"label":"Range","value":"5m spherical radius"},{"label":"Spell Field Damage","value":"60"},{"label":"Spell Field Damage Falloff","value":"40% falloff at 5m"},{"label":"Fire Rate","value":"1.33 rounds per second"}]'::jsonb, 1),
  (36518, 'iron-man', null, null, 'Unibeam', 'Normal Attack', 'Fire nano pulse cannons forward', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Channeled"},{"label":"Ammo","value":"100"},{"label":"Critical Hit","value":"No"},{"label":"Special Mechanic","value":"Repulsor Blast and Unibeam share the same ammo count"},{"label":"Beam Length","value":"25m"},{"label":"Damage","value":"140 damage per second"},{"label":"Ammo Consumption","value":"10/s"}]'::jsonb, 2),
  (36519, 'iron-man', null, null, 'Unibeam (Armor Overdrive)', 'Normal Attack', 'Fire nano pulse cannons forward', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Channeled"},{"label":"Ammo","value":"Infinite"},{"label":"Critical Hit","value":"No"},{"label":"Beam Length","value":"25m"},{"label":"Damage","value":"180/s"}]'::jsonb, 3),
  (36520, 'iron-man', null, null, 'Invincible Pulse Cannon', 'Ultimate', 'Fire a devastating pulse cannon in the targeted direction, delivering catastrophic damage to the targeted area upon impact', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Energy Cost","value":"3400"},{"label":"Projectile Speed","value":"25 m/s"},{"label":"Dispersive Spell Field","value":"Length: 15m, Width: 5m, Height: 5m"},{"label":"Damage Over Time","value":"300/s"},{"label":"Explosion Range","value":"10m spherical radius"},{"label":"Explosion Damage","value":"1000"},{"label":"Spell Field Damage Falloff","value":"5% falloff at 10m"},{"label":"Special Mechanic","value":"As the projectile travels, it creates a dispersive spell field that deals Damage Over Time to nearby enemies"}]'::jsonb, 4),
  (36521, 'iron-man', null, null, 'Hyper-Velocity', 'Ability', 'Activate Hyper-Velocity state for swift forward flight', '[{"label":"Key","value":"SHIFT"},{"label":"Movement Boost","value":"100%"},{"label":"Maximum Energy","value":"120"},{"label":"Energy Cost","value":"15/s"},{"label":"Energy Recovery Speed","value":"10/s"}]'::jsonb, 5),
  (36522, 'iron-man', null, null, 'Hyper-Velocity (Armor Overdrive)', 'Ability', 'Activate Hyper-Velocity state for swift forward flight', '[{"label":"Key","value":"SHIFT"},{"label":"Movement Boost","value":"100%"},{"label":"Maximum Energy","value":"Infinite"}]'::jsonb, 6),
  (36523, 'iron-man', null, null, 'Armor Overdrive', 'Ability', 'Activate Armor Overdrive state, enhancing the damage of Repulsor Blast and Unibeam', '[{"label":"Key","value":"E"},{"label":"Duration","value":"10s"},{"label":"Bonus Health","value":"100"},{"label":"Cooldown","value":"20s"},{"label":"Special Effect","value":"Each KO while Armor Overdrive is active extends its duration by 2s"}]'::jsonb, 7),
  (36524, 'iron-man', null, null, 'Micro-Missile Barrage', 'Ability', 'When Hyper-Velocity or Armor Overdrive is used, Iron Man can launch a missile bombardment', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Scatter-type projectile that generates a spell area upon impact"},{"label":"Missiles","value":"16"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Range","value":"2m spherical radius"},{"label":"Spell Field Damage","value":"10 damage per round"},{"label":"Cooldown","value":"8s"},{"label":"Special Mechanic","value":"Launch missiles directly beneath Iron Man"}]'::jsonb, 8),
  (36525, 'iron-man', null, null, 'Micro-Missile Barrage (Armor Overdrive)', 'Ability', 'When Hyper-Velocity or Armor Overdrive is used, Iron Man can launch a missile bombardment', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Scatter-type projectile that generates a spell area upon impact"},{"label":"Missiles","value":"18"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Range","value":"2m spherical radius"},{"label":"Spell Field Damage","value":"10 damage per round"},{"label":"Cooldown","value":"6s"},{"label":"Special Mechanic","value":"Launch in the direction of Iron Man''s crosshair"}]'::jsonb, 9),
  (36526, 'iron-man', null, null, 'NANO TECH', 'Team-Up Ability', 'When Iron Man, Ultron and Squirrel Girl team up, Ultron''s Encephalo-Ray upgrades to Nano-Ray, firing a beam that pierces through all characters, dealing continuous damage to foes while healing allies; Squirrel Girl gains the Squirrel Missile ability. She directs a squirrel to ride Iron Man''s nanotech glove as a homing missile. Upon hit, the squirrel flees just before a fiery explosion!', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"5% Damage Boost"}]'::jsonb, 10)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36527, 'iron-man', null, null, 'GAMMA CHARGE', 'Team-Up Ability', 'Base Effect: Upgrade Armor Overdrive to Gamma Overdrive. In this state, Iron Man gains a Gamma Shield and can fire significantly stronger Repulsor Blasts and Unibeams. Enhanced Effect: When teaming up with Hulk, releasing Invincible Invincible Pulse Cannon generates a Gamma Shield and heavily infuses the blast, creating a Gamma Pulse Cannon. Its radiation creates a massive damage increase while the projectile flies', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"20"},{"label":"Duration","value":"10s"},{"label":"Ability Duration Extension Per Assist/Kill (S)","value":"2s"},{"label":"Pulse Cannon Projectile Hit Damage","value":"50"},{"label":"Pulse Cannon Spell Field Damage","value":"65"},{"label":"Pulse Cannon Spell Field Range","value":"5m spherical radius"},{"label":"Pulse Cannon Damage Falloff","value":"Falloff starts at 0.3m, down to 40% at 5m"},{"label":"Unibeam Damage","value":"20/hit, 10 times per second"}]'::jsonb, 11),
  (36528, 'iron-man', null, null, 'GAMMA CHARGE', 'Team-Up Ability', 'Base Effect: Upgrade Armor Overdrive to Gamma Overdrive. In this state, Iron Man gains a Gamma Shield and can fire significantly stronger Repulsor Blasts and Unibeams. Enhanced Effect: When teaming up with Hulk, releasing Invincible Invincible Pulse Cannon generates a Gamma Shield and heavily infuses the blast, creating a Gamma Pulse Cannon. Its radiation creates a massive damage increase while the projectile flies.', '[{"label":"Key","value":"E"},{"label":"Gamma Shield Health","value":"75"},{"label":"Gamma Shield Max Duration","value":"2s"},{"label":"Dissipation Damage","value":"45"}]'::jsonb, 12),
  (36529, 'iron-man', null, null, 'THUNDER OVERDRIVE', 'Team-Up Ability', 'Base Effect: Enhance Unibeam both in and out of Armor Overdrive. When fired, a ring of volatile lightning energy forms, dealing bonus damage to enemies caught near the beam''s edge. Enhanced Effect: When teaming up with Thor, Armor Overdrive cooldown is massively reduced.', '[{"label":"Key","value":"E"},{"label":"Unibeam Outer Ring Range","value":"0.75m radius"},{"label":"Unibeam Outer Ring Damage","value":"8/hit, 10 times per second"},{"label":"Unibeam Damage","value":"14/hit, 10 times per second"},{"label":"Thunder Overdrive Unibeam Outer Ring Range","value":"1.2m radius"},{"label":"Thunder Overdrive Unibeam Outer Ring Range","value":"9/hit, 10 times per second"},{"label":"Thunder Overdrive Unibeam Outer Ring Range","value":"18/hit, 10 times per second"},{"label":"Thunder Overdrive Cd Reduction","value":"5s"}]'::jsonb, 13),
  (36530, 'moon-knight', null, null, 'Crescent Dart', 'Normal Attack', 'Unleash Crescent Darts forward that can bounce between enemies and Ankhs, dealing damage to enemies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Triple shot that fires in a straight trajectory"},{"label":"Projectile Speed","value":"150m/s"},{"label":"Fire Rate","value":"The firing interval between shots is 0.05s, with an interval of 0.57s between each round of shooting"},{"label":"Damage","value":"25 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 30m, decreasing to 50% at 50m"},{"label":"Maximum Bounce Distance","value":"7m"},{"label":"Maximum Number Of Bounces","value":"3"},{"label":"Damage Falloff Per Bounce","value":"-20%"},{"label":"Ammo","value":"30"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36531, 'moon-knight', null, null, 'Hand of Khonshu', 'Ultimate', 'Open a portal that allows Khonshu to bombard enemies with his talons', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Delayed Spherical Spell Field"},{"label":"Duration","value":"4.5s"},{"label":"Descending Range","value":"8m radius"},{"label":"Frequency","value":"4 hits per second"},{"label":"Number Of Hits","value":"18"},{"label":"Range","value":"5m spherical radius"},{"label":"Damage","value":"150 damage per hit"},{"label":"Damage Falloff","value":"Start at 1.5m, 70% falloff at 5m"},{"label":"Energy Cost","value":"3100"}]'::jsonb, 1),
  (36532, 'moon-knight', null, null, 'Night Glider', 'Ability', 'Hold SHIFT to glide', '[{"label":"Key","value":"SHIFT"},{"label":"Horizontal Movement Speed","value":"8.7m/s"},{"label":"Descending Speed","value":"1.5m/s"}]'::jsonb, 2),
  (36533, 'moon-knight', null, null, 'Ancient Ankh', 'Ability', 'Fire an Ankh to launch up enemies within its radius towards the center', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"60m/s"},{"label":"Pull-In Range","value":"5m spherical radius"},{"label":"Pull-In Damage","value":"20"},{"label":"Bouncing Range","value":"7m spherical radius"},{"label":"Cooldown","value":"12s"}]'::jsonb, 3),
  (36534, 'moon-knight', null, null, 'Moonlight Hook', 'Ability', 'Launch a frontal grappling hook that pulls Moon Knight towards it', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Dash"},{"label":"Grappling Hook Speed","value":"120m/s"},{"label":"Grappling Hook Length","value":"25m"},{"label":"Maximum Distance","value":"21.5m/s"},{"label":"Cooldown","value":"12s"}]'::jsonb, 4),
  (36535, 'moon-knight', null, null, 'Rising Leap', 'Ability', 'Perform a double jump', '[{"label":"Key","value":"Space"},{"label":"Cooldown","value":"6s"}]'::jsonb, 5),
  (36536, 'moon-knight', null, null, 'Moon Blade', 'Ability', 'Launch forward a Moon Blade that can bounce between enemies and Ankhs, dealing damage to enemies', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Projectile that fires in a straight trajectory"},{"label":"Projectile Speed","value":"120m/s"},{"label":"Damage","value":"70"},{"label":"Damage Falloff","value":"Falloff begins at 30m, decreasing to 50% at 50m"},{"label":"Maximum Bounce Distance","value":"7m"},{"label":"Maximum Number Of Bounces","value":"3"},{"label":"Damage Falloff Per Bounce","value":"-30%"},{"label":"Bonus Health","value":"25, up to a max of 76 Bonus Health"},{"label":"Critical Hit","value":"Yes"},{"label":"Cooldown","value":"6s"},{"label":"Charges","value":"2"}]'::jsonb, 6),
  (36537, 'moon-knight', null, null, 'Triple Eclipse', 'Ability', 'Perform a combo with his truncheon, and the third strike will launch up the enemy hit slightly', '[{"label":"Key","value":"V"},{"label":"Casting","value":"Melee"},{"label":"Maximum Distance","value":"3m"}]'::jsonb, 7),
  (36538, 'moon-knight', null, null, 'MOON GOD''S CHOSEN', 'Team-Up Ability', 'Blessed by Khonshu, Blade gains a new ability. When activated, Blade swings his Ancestral Sword in a powerful slash, dashing forward a short distance. At the end of the dash, he swiftly slashes four times, each strike sending a Darkmoon Blade forward. When a Darkmoon Blade hits an enemy, it bounces to nearby targets', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"5% Damage Boost"}]'::jsonb, 8),
  (36539, 'moon-knight', null, null, 'LUMINOUS MOON', 'Team-Up Ability', 'Base Effect: Enter Phased state and dash forward. Upon concluding, emit a Light Energy Healing Wave that heals Moon Knight and nearby allies. Enhanced Effect: When teaming up with Cloak & Dagger, the Phased state duration is extended, the dash distance increases, and the Light Energy Healing Wave boasts a larger radius and stronger healing output.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12"},{"label":"Dash Duration","value":"0.35s"},{"label":"Dashing Speed","value":"50 m/s"},{"label":"Phased Duration","value":"0.25s"},{"label":"Healing Amount","value":"55"},{"label":"Healing Range","value":"5m radius"},{"label":"Enhanced Phased Duration","value":"0.35s"},{"label":"Enhanced Healing Amount","value":"65, gains a 3s healing effect of 20 Health/s after leaving the Phased state"},{"label":"Enhanced Healing Range","value":"8m radius"}]'::jsonb, 9),
  (36540, 'moon-knight', null, null, 'BLOOD MOON', 'Team-Up Ability', 'Base Effect: Deploy an Ankh Trap. Upon triggering, an Ankh materializes at the location, while summoning a single Talon of Khonshu to Launch enemies toward the trap''s center. Enhanced Effect: When teaming up with Elsa Bloodstone, triggering the trap summons multiple Talons of Khonshu to bombard the area.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15"},{"label":"Trap Health","value":"100"},{"label":"Ankh Health","value":"125"},{"label":"Time For Trap To Turn Invisible","value":"1s"},{"label":"Talons Of Khonshu Range","value":"5m radius"},{"label":"Damage","value":"70"},{"label":"Enhanced Damage","value":"40"},{"label":"Talons Of Khonshu Generated","value":"3"}]'::jsonb, 10),
  (36541, 'namor', null, null, 'Trident of Neptune', 'Normal Attack', 'Throw the trident forward, reducing Aquatic Dominion''s cooldown upon enemy impact. Critical hits cause Monstro Spawn to enter a berserk state, gaining increased Attack Speed', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Projectile with an arced trajectory"},{"label":"Damage","value":"80"},{"label":"Projectile Speed","value":"150 m/s"},{"label":"Fire Rate","value":"1.09 rounds per second"},{"label":"Ammo","value":"Infinite"},{"label":"Critical Hit","value":"Yes"},{"label":"Aquatic Dominion Charge Per Hit","value":"0.13"}]'::jsonb, 0),
  (36542, 'namor', null, null, 'Horn of Proteus', 'Ultimate', 'Summon Giganto to leap atop enemies within range, disabling their mobility abilities', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Cylindrical Spell Field"},{"label":"Maximum Distance","value":"30m"},{"label":"Range","value":"A cylindrical spell field with an inner circle radius of 3.5m, an outer circle radius of 9m, and a height of 3m"},{"label":"Hit Delay","value":"1.5s"},{"label":"Damage","value":"Inner Circle Damage: 500; Outer Circle Damage: 180"},{"label":"Immobilize Duration","value":"1.5s"},{"label":"Energy Cost","value":"3100"}]'::jsonb, 1),
  (36543, 'namor', null, null, 'Blessing of the Deep', 'Ability', 'Summon a protective barrier while flying upwards', '[{"label":"Key","value":"SHIFT"},{"label":"Vertical Moving Distance","value":"7m"},{"label":"Maximum Duration","value":"3s"},{"label":"Cooldown","value":"20s"}]'::jsonb, 2),
  (36544, 'namor', null, null, 'Aquatic Dominion', 'Ability', 'Summon a Monstro Spawn that can autonomously attack enemies', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Arced Trajectory (Summon Monstro Spawn), Direct Hit (Monstro Spawn)"},{"label":"Projectile Speed (Summon Monstro Spawn)","value":"30 m/s"},{"label":"Monstro Spawn Maximum Duration","value":"8s"},{"label":"Monstro Spawn Health","value":"125"},{"label":"Monstro Spawn Attack Range","value":"40m"},{"label":"Monstro Spawn Maximum Quantity","value":"2"},{"label":"Charges","value":"2"},{"label":"Default Charging Speed","value":"0.1/s"},{"label":"Monstro Spawn Fire Rate","value":"2 rounds per second"},{"label":"Monstro Spawn Damage","value":"18"},{"label":"Monstro Spawn Damage Falloff","value":"Falloff begins at 20m, decreasing to 50% at 40m"},{"label":"Duration","value":"2s"},{"label":"Monstro Spawn Fire Rate","value":"5 rounds per second"},{"label":"Monstro Spawn Damage","value":"12"},{"label":"Monstro Spawn Damage Falloff","value":"Falloff begins at 20m, decreasing to 30% at 40m"}]'::jsonb, 3),
  (36545, 'namor', null, null, 'Wrath of the Seven Seas', 'Ability', 'Launch the trident forward to damage nearby enemies, then direct all Monstro Spawn to perform an enhanced attack on the nearest hit enemy. When the trident hits an enemy, Monstro Spawn to enter a berserk state, gaining increased Attack Speed', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Arced projectile that generates a spell field upon impact"},{"label":"Projectile Damage","value":"40"},{"label":"Projectile Speed","value":"150 m/s"},{"label":"Range","value":"3m spherical radius"},{"label":"Spell Field Damage","value":"60"},{"label":"Spell Field Damage Falloff","value":"50% falloff at 3m"},{"label":"Enhanced Monstro Spawn Projectile Damage","value":"60"},{"label":"Enhanced Monstro Spawn Projectile Speed","value":"120 m/s"},{"label":"Cooldown","value":"6s"}]'::jsonb, 4),
  (36546, 'namor', null, null, 'TIDAL DIRGE', 'Team-Up Ability', 'Hela channels energy of the undead to empower Namor. When Namor strikes with his trident, a spectral water column erupts at the target area, slowing enemies hit. Whenever Hela or Namor assist in a KO, an invulnerable Undead Monstro spawns at the fallen enemy''s position, automatically attacking the nearest foe for a short time before vanishing', '[{"label":"Key","value":"C"},{"label":"Inner Circle Spell Field Range","value":"A cylindrical spell field with a radius of 3m and a height of 13m"},{"label":"Outer Circle Spell Field Range","value":"A cylindrical spell field with a radius of 6m and a height of 11m"},{"label":"Inner Circle Damage","value":"65"},{"label":"Outer Circle Damage","value":"45"},{"label":"Reduced Healing Rate","value":"20%"},{"label":"Slow Rate","value":"35%"},{"label":"Outer Circle Generate Delay","value":"0.5s"},{"label":"Cooldown","value":"30s"},{"label":"Key","value":"Passive"},{"label":"Undead Monstro Duration","value":"3s"},{"label":"Undead Monstro Damage","value":"10"},{"label":"Undead Monstro Fire Rate","value":"0.5s per hit"},{"label":"Undead Monstro Rage Damage","value":"6"},{"label":"Undead Monstro Rage Fire Rate","value":"5 rounds per second"},{"label":"Undead Monstro Maximum Amount","value":"2"},{"label":"Rage Duration","value":"2s"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 50% at 40m"},{"label":"Special Effect","value":"Undead Monstro is untargetable"}]'::jsonb, 5),
  (36547, 'namor', null, null, 'GAMMA MONSTRO', 'Team-Up Ability', 'Base Effect: Summon an extra Gamma Monstro that continuously damages the nearest enemy. Upon landing critical hits, the Gamma Monstro gains increased Attack Speed. Hitting an enemy with Wrath of the Seven Seas prompts it to fire a powerful beam. Enhanced Effect: When teaming up with Hulk, casting Blessing of the Deep creates a water barrier infused with Gamma energy. Standing inside accelerates the Gamma Monstro cooldown and grants it a Damage Boost.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"25"},{"label":"Gamma Monstro Attack Interval","value":"0.1s per use"},{"label":"Gamma Monstro Attack Damage","value":"5.5 per hit"},{"label":"Gamma Monstro Damage Growth Rate Over Time","value":"10% per second"},{"label":"Gamma Monstro Health","value":"150"},{"label":"Gamma Monstro Frenzy Attack Damage","value":"3.5"},{"label":"Gamma Monstro Frenzy Attack Interval","value":"0.05"},{"label":"Cooldown Recovery Speed Boost","value":"200%"},{"label":"Gamma Octopus Damage Boost Rate","value":"25%"}]'::jsonb, 6),
  (36548, 'namor', null, null, 'CHILLING CHARISMA', 'Team-Up Ability', 'Base Effect: Gain a new ability to summon a Frost Tide forward. The wave damages, Pushes Back, and inflicts a Slow on all enemies hit. Enhanced Effect: When teaming up with Luna Snow, the Frost Tide gains 1 charge and crashes down upon reaching its maximum range, dealing area damage and Slowing enemies caught near the endpoint.', '[{"label":"Key","value":"C"},{"label":"Frost Tide Damage","value":"75"},{"label":"Slow Rate","value":"25% for 2s"},{"label":"Cooldown","value":"15s"},{"label":"Frost Tide Movement Speed","value":"17.5m/s"},{"label":"Frost Tide Max Travel Time","value":"1s"},{"label":"Frost Tide Range","value":"6m wide, 3m tall"},{"label":"Special Effect","value":"replace Namor''s Monstro Spawn with Frozen Spawn. The Frozen Spawn attacks apply a 15% slow effect on hit, lasting 1s"},{"label":"Frost Wave Damage At Max Distance","value":"50"},{"label":"Enhanced Slow Rate","value":"40% for 2s"}]'::jsonb, 7),
  (36549, 'star-lord', null, null, 'Element Guns', 'Normal Attack', 'Shoot enemies with dual Element Guns', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Rapid-fire shots with spread."},{"label":"Damage","value":"6.5 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 10m, decreasing to 60% at 25m"},{"label":"Crosshair Spread Radius (At 10m)","value":"After 2 consecutive shots, the spread increases to 0.15m; after 5 consecutive shots, the spread expands to 0.24m"},{"label":"Fire Rate","value":"40 rounds per second"},{"label":"Ammo","value":"50"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36550, 'star-lord', null, null, 'Galactic Legend', 'Ultimate', 'Engage in free-flight and lock onto enemies in sight', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Rapid-fire projectile."},{"label":"Damage","value":"6.5 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 25m, decreasing to 75% at 40m"},{"label":"Fire Rate","value":"40 rounds per second"},{"label":"Ammo","value":"40"},{"label":"Critical Hit","value":"No"},{"label":"Duration","value":"8s"},{"label":"Movement Boost","value":"20%"},{"label":"Reload Time Reduction","value":"70%"},{"label":"Maximum Locking Distance","value":"40m"},{"label":"Energy Cost","value":"3100"},{"label":"Special Mechanic","value":"During this period, Star-Lord''s Reload Speed increases significantly"}]'::jsonb, 1),
  (36551, 'star-lord', null, null, 'Rocket Propulsion', 'Ability', 'Consume energy to gain a Movement Boost and soar forward', '[{"label":"Key","value":"SHIFT"},{"label":"Movement Boost","value":"100%"},{"label":"Maximum Energy","value":"1800"},{"label":"Energy Cost","value":"300/s"},{"label":"Energy Recovery Speed","value":"120/s"}]'::jsonb, 2)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36552, 'star-lord', null, null, 'Blaster Barrage', 'Ability', 'Fire a frenzy of shots, causing damage to enemies within range.', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Spherical Spell Field"},{"label":"Duration","value":"3s"},{"label":"Range","value":"8m spherical radius"},{"label":"Attack Interval","value":"0.1 per hit"},{"label":"Damage","value":"8 damage per hit"},{"label":"Damage Falloff","value":"Falloff begins at 4m, decreasing to 80% at 8m"},{"label":"Cooldown","value":"8s"}]'::jsonb, 3),
  (36553, 'star-lord', null, null, 'Stellar Shift', 'Ability', 'Dodge in the direction of movement and swiftly reload', '[{"label":"Key","value":"Right Click"},{"label":"Invincibility Duration","value":"0.37s"},{"label":"Charges","value":"2"},{"label":"Recharge Speed","value":"5s per charge"}]'::jsonb, 4),
  (36554, 'star-lord', null, null, 'Astral Jump', 'Team-Up Ability', 'Star-Lord gets a teleport to its deployment point from anywhere on the map', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"Teleport Cooldown 30s; jump device deployment Cooldown 5s."},{"label":"Teleport Delay","value":"1s"},{"label":"Summons'' Health","value":"100"}]'::jsonb, 5),
  (36555, 'star-lord', null, null, 'FLORA MUNITIONS', 'Team-Up Ability', 'Gain a new ability to toss Twisted Thorn Seeds forward. Upon landing, they rapidly Sprout and take root, generating Thorn Snares around the area. Enemies stepping on a snare take damage and suffer a Root effect. Enhanced Effect: When teaming up with Groot, the number of Thorn Snares deployed increases, and the damage dealt when an enemy steps on them is boosted.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Traps Generated","value":"5"},{"label":"Trap Generation Delay","value":"1"},{"label":"Trap Duration","value":"4"},{"label":"Imprison Duration","value":"0.8s"},{"label":"Damage","value":"30 each"},{"label":"Enhanced Traps Generated","value":"8"},{"label":"Enhanced Damage","value":"45 each"}]'::jsonb, 6),
  (36556, 'star-lord', null, null, 'STAR-SOUL', 'Team-Up Ability', 'Base Effect: Gain a new ability to place a Telekinetic Beacon. You can teleport back to the location where the beacon is deployed from anywhere on the map. Upon defeat, Star-Lord will cocoon and respawn at the Telekinetic Beacon''s coordinates. Enhanced Effect: When teaming up with Adam Warlock, every time Star-Lord participates in a KO, Telekinetic Beaconcooldown is reduced.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"30s"},{"label":"Cooldown To Respawn","value":"120s"},{"label":"Cooldown To Replace After Canceling Telekinetic Beacon","value":"5s"},{"label":"Ability Cd Reduction Per Ko","value":"10s"}]'::jsonb, 7),
  (36557, 'scarlet-witch', null, null, 'Chaos Control', 'Normal Attack', 'Unleash Chaos Magic on enemies to deal damage and restore Chaos Energy. Concurrently damages any enemies within range bearing a Chaos Magic mark', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Cylindrical Spell Field"},{"label":"Range","value":"A cylindrical spell field with a radius of 3m and a height of 20m"},{"label":"Fire Rate","value":"0.1s per hit"},{"label":"Damage","value":"8.5 per hit"},{"label":"Damage Falloff","value":"Falloff begins at 10m, decreasing to 90% at 20m"},{"label":"Chthonian Burst Recharge Per Hit","value":"0.15 per hit"},{"label":"Ammo","value":"Infinite"},{"label":"Critical Hit","value":"No"},{"label":"Special Effect 1","value":"Attack the nearest enemy within range"},{"label":"Special Effect 2","value":"Hitting with Chaos Control charges Chthonian Burst"},{"label":"Marked Enemy Pull-In Range","value":"120° cone"}]'::jsonb, 0),
  (36558, 'scarlet-witch', null, null, 'Reality Erasure', 'Ultimate', 'Engage in free-flight while gaining Bonus Health and charging energy. While flying, continuously pull in nearby enemies and inflict Chaos Marks, dealing gradually increasing damage over time. Then, unleash the charged energy to deal massive area damage. Small chance to be immune to incoming damage from enemies within the ultimate''s attack range', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Spherical Spell Field"},{"label":"Range","value":"15m spherical radius"},{"label":"Damage","value":"9999"},{"label":"Charge Time","value":"4s"},{"label":"Slow Rate","value":"Begin to slow down by 1.5s, with the effect gradually increasing to -25% by 3.5s"},{"label":"Bonus Health (Self)","value":"100"},{"label":"Special Effect","value":"During this period, Scarlet Witch enters a Free-flight state, pulls in nearby enemies (within 15m radius) during cast charge. Max pull speed up to 3m/s"},{"label":"Energy Cost","value":"3400"},{"label":"Damage Over Time","value":"50/s, increasing to 80/s over 4s"},{"label":"Affected Enemies'' Attack Chance","value":"0.5%"}]'::jsonb, 1),
  (36559, 'scarlet-witch', null, null, 'Mystic Projection', 'Ability', 'Enter the Phased state for free-flight. Press again to exit early', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Dash"},{"label":"Duration","value":"1.5s"},{"label":"Movement Boost","value":"50%"},{"label":"Charges","value":"2"},{"label":"Recharge Speed","value":"12s per charge"},{"label":"Special Effect","value":"During this period, Scarlet Witch enters the Projection state, can be healed by teammates"}]'::jsonb, 2),
  (36560, 'scarlet-witch', null, null, 'Dark Seal', 'Ability', 'Land a hit on a target or the scene, or press {Ability1} again to generate a Force Field. The initial explosion Stuns enemies within range, while continuing to apply a Slow effect for the remaining duration. Continuously inflicts Chaos Marks on enemies within range', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Spell Field Generation Delay","value":"0.8s"},{"label":"Range","value":"3m spherical radius"},{"label":"Spell Field Duration","value":"4.5s"},{"label":"Detection Interval","value":"1.25s"},{"label":"Stun Duration Per Detection","value":"0.5s"},{"label":"Cooldown","value":"12s"},{"label":"Damage","value":"20/s"},{"label":"Slow Rate","value":"30%"}]'::jsonb, 3),
  (36561, 'scarlet-witch', null, null, 'Telekinesis', 'Ability', 'Hold Space to fall slowly', '[{"label":"Key","value":"Space"},{"label":"Horizontal Movement Speed","value":"6 m/s"},{"label":"Descending Speed","value":"3.5 m/s"}]'::jsonb, 4),
  (36562, 'scarlet-witch', null, null, 'Chthonian Burst', 'Ability', 'Consume Chaos Energy to fire explosive magic missiles, damaging enemies', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"120 m/s"},{"label":"Projectile Damage","value":"40"},{"label":"Range","value":"3m spherical radius"},{"label":"Spell Field Damage","value":"35"},{"label":"Charges","value":"4"},{"label":"Default Charging Speed","value":"0.2/s"}]'::jsonb, 5),
  (36563, 'scarlet-witch', null, null, 'SCARLET HEX', 'Ability', 'Unleash a shockwave of Chaos Magic forward, dealing damage and applying a Chaos Magic mark to enemies', '[{"label":"Key","value":"F"},{"label":"Cd","value":"10s"},{"label":"Spell Field Range","value":"4m-radius, 20m-long cylindrical field"},{"label":"Damage","value":"40"}]'::jsonb, 6),
  (36564, 'scarlet-witch', null, null, 'CHAOS MARK', 'Passive', 'While the mark is active, using Chaos Control deals damage to marked enemies. Dealing damage to enemies with a Chaos Mark grants Bonus Health', '[{"label":"Key","value":"Passive"},{"label":"Damage/Health Conversion","value":"25%"}]'::jsonb, 7),
  (36565, 'scarlet-witch', null, null, 'Sorcery Surge', 'Team-Up Ability', 'Doctor Strange shares his arcane mastery, replacing Scarlet Witch''s Chthonian Burst with Mystic Burst upon activation. Hold down the attack button to unleash a rapid, relentless salvo of magical missiles in the target direction', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"120 m/s"},{"label":"Projectile Damage","value":"10"},{"label":"Spell Field Range","value":"1.5m spherical radius"},{"label":"Spell Field Damage","value":"6"},{"label":"Fire Rate","value":"0.15s per round"},{"label":"Duration","value":"10s"},{"label":"Cooldown","value":"30s"},{"label":"Special Mechanic","value":"Chaos Control can released during the Sorcery Surge"}]'::jsonb, 8),
  (36566, 'scarlet-witch', null, null, 'SORCERERS SUPREME', 'Team-Up Ability', 'Base Effect: Chthonian Burst is replaced with Mystic Burst upon activation. Hold down the attack button to unleash a rapid, relentless salvo of magical missiles in the target direction. Enhanced Effect: When teaming up with Doctor Strange, Scarlet Witch''s maximum total Chaos Energy pool increases, and Chaos Control generates energy much faster when attacking.', '[{"label":"Key","value":"Right Click"},{"label":"Projectile Firing Interval","value":"0.12s/shot"},{"label":"Ability Energy","value":"300"},{"label":"Natural Recovery Per Second","value":"15"},{"label":"Natural Decay Per Second","value":"50"},{"label":"Energy Required To Activate","value":"15"},{"label":"Enhanced Ability Energy","value":"450"},{"label":"Enhanced Natural Recovery Per Second","value":"22.5"},{"label":"Enhanced Natural Decay Per Second","value":"56.5"},{"label":"Enhanced Energy Required To Activate","value":"22.5"},{"label":"Charge Per Enemy Detected By Magic Mastery","value":"9"}]'::jsonb, 9),
  (36567, 'scarlet-witch', null, null, 'HEX FIREWORKS', 'Team-Up Ability', 'Base Effect: Infuse firework energy into the Dark Seal forcefield, turning it into a Plasmoid Seal, allowing for a secondary blast. After expanding the Plasmoid Seal, pressing the {Ability1} key again while it persists will detonate the fireworks, dealing damage and inflicting Vulnerability. Enhanced Effect: When teaming up with Jubilee, Scarlet Witch receives constant healing from the firework energy while using Mystic Projection.', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"12s"},{"label":"Explosion Damage","value":"52"},{"label":"Vulnerability","value":"15%"},{"label":"Vulnerability Duration","value":"2s"},{"label":"Explosion Range","value":"6m spherical radius"},{"label":"Enhanced Key","value":"SHIFT"},{"label":"Healing Amount","value":"4.2/hit, 10 times per second"}]'::jsonb, 10),
  (36568, 'winter-soldier', null, null, 'Roterstern', 'Normal Attack', 'Fire explosive rounds with his blaster, Roterstern, damaging the target hit and enemies behind them.', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"180 m/s"},{"label":"Projectile Damage","value":"80"},{"label":"Range","value":"Cone-shaped spell field with a 5m radius and an apex angle of 90°"},{"label":"Spell Field Damage","value":"45"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 70% at 40m"},{"label":"Fire Rate","value":"2.5 rounds per second"},{"label":"Ammo","value":"3"},{"label":"Critical Hit","value":"Projectile: Yes; Spell Field: No"},{"label":"Special Mechanic","value":"Enemies that take damage from the projectile will no longer receive damage from the spell field"}]'::jsonb, 0),
  (36569, 'winter-soldier', null, null, 'Kraken Impact', 'Ultimate', 'Leap high, then dash forward and slam down with the bionic arm, dealing damage to enemies in range, marking them for Culling. Marked enemies will perish instantly if their health falls below a certain threshold, recharging the bionic arm for another Kraken Impact within a short period', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Spherical Spell Field"},{"label":"Range","value":"5m spherical radius"},{"label":"Spell Field Damage","value":"70"},{"label":"Culling Duration","value":"5s"},{"label":"Culling Threshold","value":"20% Health"},{"label":"Next Kraken Impact After A Culling","value":"8s"},{"label":"Energy Cost","value":"3100"}]'::jsonb, 1),
  (36570, 'winter-soldier', null, null, 'Trooper''s Fist', 'Ability', 'Dash forward, seizing enemies along the path and launching up enemies at the end of the dash', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Movement-based damage ability"},{"label":"Average Speed","value":"30 m/s"},{"label":"Maximum Distance","value":"9m"},{"label":"Seize Damage","value":"25"},{"label":"Range","value":"Length: 4.5m, Width: 4.5m, Height: 2m"},{"label":"Knockback Damage","value":"65"},{"label":"Cooldown","value":"10s"}]'::jsonb, 2),
  (36571, 'winter-soldier', null, null, 'Tainted Voltage', 'Ability', 'Charge up and launch a powerful electrical punch with the bionic arm in the target direction, dealing damage to enemies within range and Slowing them. This ability can Knock Down flying heroes', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Projectile that fires in a straight trajectory"},{"label":"Projectile Speed","value":"100 m/s"},{"label":"Damage","value":"55"},{"label":"Slow Rate","value":"-25%"},{"label":"Slow Duration","value":"2s"},{"label":"Special Mechanic","value":"Projectiles pierce through enemies"},{"label":"Cooldown","value":"6s"}]'::jsonb, 3),
  (36572, 'winter-soldier', null, null, 'Bionic Hook', 'Ability', 'Charge up and launch a hook with his bionic arm, reeling in the first target hit and enemies lurking behind', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Charge Time","value":"0.5s - 4s"},{"label":"Range","value":"The projectile can travel up to 10m with a 0.5s charge. As the charge time increases, it can reach a maximum distance of 20m with a 1s charge"},{"label":"Projectile Damage","value":"15"},{"label":"Range","value":"Cone-shaped spell field with a 4.5m radius and an apex angle of 80°"},{"label":"Spell Field Damage","value":"20"},{"label":"Cooldown","value":"15s"}]'::jsonb, 4),
  (36573, 'winter-soldier', null, null, 'Ceaseless Charge', 'Passive', 'Roterstern reloads automatically while the bionic arm is in action, granting Bonus Health to the Winter Soldier', '[{"label":"Key","value":"Passive"},{"label":"Bonus Health (Self)","value":"40 (Bionic Hook & Tainted Voltage), 50 (Trooper''s Fist, Kraken Impact)"}]'::jsonb, 5),
  (36574, 'winter-soldier', null, null, 'Stellar Impact', 'Team-Up Ability', 'Inspired by Captain America''s resolve, Winter Soldier can leap to the aid of a designated ally, slamming the ground with his mechanical arm to damage nearby foes and grant Bonus Health to allies within range. Captain America and Winter Soldier can interact with each other once both parties confirm. The duo then collides and unleashes a shockwave that damages and slows enemies', '[{"label":"Key","value":"C"},{"label":"Damage","value":"70"},{"label":"Range","value":"8m spherical radius"},{"label":"Clash Damage","value":"80"},{"label":"Clash Damage Range","value":"10m spherical radius"},{"label":"Special Effect","value":"Stellar Impact also triggers the Ceaseless Charge passive effect"},{"label":"Bonus Health (Self)","value":"30"},{"label":"Bonus Health (Ally)","value":"50"},{"label":"Cooldown","value":"12s"}]'::jsonb, 6),
  (36575, 'winter-soldier', null, null, 'TIMELESS VETERANS', 'Team-Up Ability', 'Base Effect: Unlocks the Burst Spike ability. Using the bionic arm emits forward electricity, dealing damage and Knocking Back enemies. Enhanced Effect: When teaming up with The Punisher, the electric burst applies a Grounded effect and Knocks Back enemies even further.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Burst Spike Max Attack Range","value":"15.25m"},{"label":"Burst Spike Damage","value":"85"},{"label":"Special Effect","value":"Burst Spike applies a Grounded effect and knocks back enemies even further"}]'::jsonb, 7),
  (36576, 'winter-soldier', null, null, 'EXPERT INSTINCT', 'Team-Up Ability', 'Base Effect: Securing or participating in a KO grants a stack of Culling Instinct. Each stack reduces the cooldowns of Winter Soldier''s other abilities. All stacks are lost upon defeat. Enhanced Effect: When teaming up with Elsa Bloodstone, the Bonus Health generated by Ceaseless Charge is increased.', '[{"label":"Key","value":"Passive"},{"label":"Other Ability Cd Reduction Per Culling Instinct Stack","value":"1.5s"},{"label":"Culling Instinct Max Stacks","value":"2"},{"label":"Culling Instinct Stacks For Death Damage Reduction","value":"1"},{"label":"Direct Damage Required Per Energy Stack","value":"500"},{"label":"Bonus Health","value":"55"}]'::jsonb, 8)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36577, 'magik', null, null, 'Soulsword', 'Normal Attack', 'Slash forward with the Soulsword', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"75"},{"label":"Maximum Distance","value":"6.5m"},{"label":"Damage Falloff","value":"Falloff begins at 4.5m, decreasing to 50% at 6.5m"},{"label":"Attack Interval","value":"0.83s per hit"},{"label":"Enhanced Damage","value":"Deals 3 hits at intervals of 0.15s, with each hit dealing 35 damage"},{"label":"Enhanced Maximum Distance","value":"10m"},{"label":"Enhanced Damage Falloff","value":"Falloff begins at 6m, decreasing to 25% at 10m"},{"label":"Enhanced Attack Interval","value":"1 hit per second"}]'::jsonb, 0),
  (36578, 'magik', null, null, 'Darkchild', 'Ultimate', 'Transform into Darkchild, gaining enhancements to all her abilities', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Transformation"},{"label":"Duration","value":"12s"},{"label":"Energy Cost","value":"3400"},{"label":"Special Effect","value":"When in the Darkchild state, all of Magik''s abilities are enhanced"}]'::jsonb, 1),
  (36579, 'magik', null, null, 'Stepping Discs', 'Ability', 'Jump through a Stepping Disc, teleporting a short distance in the direction of movement. Become Invincible while teleporting', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Dash"},{"label":"Average Speed","value":"12m/s"},{"label":"Maximum Distance","value":"10m"},{"label":"Combo Ability Casting Window","value":"3s"},{"label":"Cooldown","value":"6s"},{"label":"Charges","value":"2"},{"label":"Special Effect 1","value":"Magik is invincible while moving"},{"label":"Special Effect 2","value":"Magik can perform a combo ability within a certain time frame, choosing between Eldritch Whirl or Demon''s Rage"},{"label":"Enhanced Average Speed","value":"17m/s"},{"label":"Enhanced Cooldown","value":"3s"}]'::jsonb, 2),
  (36580, 'magik', null, null, 'Umbral Incursion', 'Ability', 'Dash forward and launch up enemies', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Movement-based damage ability"},{"label":"Average Speed","value":"46m/s"},{"label":"Maximum Distance","value":"16m"},{"label":"Upward Slash Damage","value":"85"},{"label":"Cooldown","value":"8s"},{"label":"Enhanced Average Speed","value":"60m/s"},{"label":"Enhanced Maximum Distance","value":"20m"},{"label":"Enhanced Upward Slash Damage","value":"140"},{"label":"Enhanced Cooldown","value":"6s"}]'::jsonb, 3),
  (36581, 'magik', null, null, 'Eldritch Whirl', 'Ability', 'Spin while swinging the Soulsword after exiting a Stepping Disc', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"A cylindrical spell field in melee range"},{"label":"Damage","value":"50"},{"label":"Range","value":"A cylindrical spell field with a radius of 6m and a height of 5m"},{"label":"Enhanced Damage","value":"Deals 3 hits at intervals of 0.25s, each dealing 45 damage"},{"label":"Enhanced Range","value":"A cylindrical spell field with a radius of 12m and a height of 5m"}]'::jsonb, 4),
  (36582, 'magik', null, null, 'Magik Slash', 'Ability', 'Strike forward an air slash', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Charged projectile that travels in a straight trajectory"},{"label":"Maximum Charge Time","value":"2s"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Damage","value":"45 - 81 (Maximum damage is achieved after 1.2s of charging)"},{"label":"Special Effect","value":"Projectile pierces enemies and reduces Stepping Discs cooldown by 1s per enemy pierced"},{"label":"Cooldown","value":"6s"},{"label":"Enhanced Casting","value":"Projectile that fires in a straight trajectory"},{"label":"Enhanced Projectile Speed","value":"100m/s"},{"label":"Enhanced Damage","value":"90 - 180 (Maximum damage is achieved after 1.8s of charging)"},{"label":"Enhanced Cooldown","value":"3s"}]'::jsonb, 5),
  (36583, 'magik', null, null, 'Demon''s Rage', 'Ability', 'Summon a Limbo demon that attacks enemies after exiting a Stepping Disc', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"A cuboid spell field in melee range"},{"label":"Damage","value":"20 damage per hit"},{"label":"Attack Speed","value":"0.25s per hit"},{"label":"Range","value":"Length: 6.5m, Width: 3m, Height: 3m"},{"label":"Maximum Duration For Summons","value":"4s"},{"label":"Summons'' Health","value":"100"},{"label":"Enhanced Damage","value":"25 damage per hit"},{"label":"Enhanced Range","value":"Length: 6m, Width: 4m, Height: 4m"},{"label":"Enhanced Summons'' Health","value":"200"}]'::jsonb, 6),
  (36584, 'magik', null, null, 'Limbo''s Might', 'Passive', 'Convert damage inflicted on enemies into Bonus Health to herself', '[{"label":"Key","value":"Passive"},{"label":"Conversion Rate","value":"30%"},{"label":"Bonus Max Health","value":"150"},{"label":"Energy Cost Special Effect","value":"Convert damage taken into Bonus Health"}]'::jsonb, 7),
  (36585, 'magik', null, null, 'CHAIN OF CYTTORAK', 'Team-Up Ability', 'Doctor Strange shares his arcane mastery with Scarlet Witch and Magik. Scarlet Witch''s Chthonian Burst is replaced with Mystic Burst upon activation. Hold down the attack button to unleash a rapid, relentless salvo of magical missiles in the target direction. Magik can unleash a Chain of Cyttorak that links two enemies and slows them; the farther they are apart, the greater the Slow effect inflicted during the link', '[{"label":"Key","value":"C"},{"label":"Max Link Generation Distance","value":"15m"},{"label":"Projectile Speed","value":"120m/s"},{"label":"Projectile Hit Damage","value":"45"},{"label":"Damage To The Link''S Secondary Target","value":"30"},{"label":"Link Maximum Duration","value":"4s"},{"label":"Slow Rate","value":"Begins at 0%, growing to 40% at 5m"},{"label":"Link Breakage Distance","value":"30m"},{"label":"Cooldown","value":"20s"},{"label":"Damage Over Time","value":"10/s"}]'::jsonb, 8),
  (36586, 'magik', null, null, 'CHAIN OF CYTTORAK', 'Team-Up Ability', 'Base Effect: Chain of Cyttorak can tether two enemies simultaneously, dragging both targets to the same location. Enhanced Effect: When teaming up with Doctor Strange, Chain of Cyttorak can tether multiple enemies at once, pulling the entire group to a singular point.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Slow Rate","value":"Begins at 0%, growing to 40% at 5m"},{"label":"Chain Damage Over Time","value":"10/s, up to 4s"},{"label":"Special Effect","value":"Cyttorak Chains can link multiple enemies at once, pulling them to the same location"}]'::jsonb, 9),
  (36587, 'magik', null, null, 'VOID PENTAGRAM', 'Team-Up Ability', 'Base Effect: Casting Stepping Discs within an Hellish Magic Circle refunds energy, and each use of Stepping Discs summons a Limbo Demon. Enhanced Effect: When teaming up with The Hood, the summoned Limbo Demons have heavily increased Health and a wider attack range.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Duration","value":"5s"},{"label":"Magic Circle Range","value":"8m radius"},{"label":"Hellfire Trail Energy Refund","value":"0.5"},{"label":"Limbo Demo Health","value":"100"},{"label":"Limbo Demo Duration","value":"4s"},{"label":"Limbo Demo Attack Range","value":"6.5m"},{"label":"Damage","value":"20/hit, 4 times per second"},{"label":"Hell Frontier Demon Health Increase","value":"25"},{"label":"Hell Frontier Demon Attack Range Increase","value":"2.5m"}]'::jsonb, 10),
  (36588, 'spider-man', null, null, 'Spider-Power', 'Normal Attack', 'Swing fists forward to strike, dealing extra damage to the enemy with a Spider-Tracer', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Special Mechanic","value":"The default attack is a punch, but after landing two consecutive punches, the next attack will be a flying kick"},{"label":"Damage","value":"25"},{"label":"Maximum Distance","value":"3m"},{"label":"Attack Interval","value":"0.37s per punch"},{"label":"Damage","value":"40"},{"label":"Maximum Distance","value":"4m"},{"label":"Attack Interval","value":"0.82s per kick"}]'::jsonb, 0),
  (36589, 'spider-man', null, null, 'Web-Cluster', 'Normal Attack', 'Shoot a Web-Cluster that deals damage and attaches a Spider-Tracer to the hit enemy', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Projectile that fires in a straight trajectory"},{"label":"Charges","value":"5"},{"label":"Recharge Speed","value":"2s per shot"},{"label":"Projectile Speed","value":"120 m/s"},{"label":"Damage","value":"30"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 50% at 40m"},{"label":"Critical Hit","value":"No"},{"label":"Spider-Tracer Duration","value":"3s"},{"label":"Spider-Tracer Damage","value":"45"}]'::jsonb, 1),
  (36590, 'spider-man', null, null, 'Spectacular Spin', 'Ultimate', 'Launch Web-Clusters all around to damage and Stun enemies', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Spherical Spell Field"},{"label":"Range","value":"8m spherical radius"},{"label":"Duration","value":"2.4s"},{"label":"Attack Interval","value":"0.08s per hit"},{"label":"Damage","value":"15 damage per hit"},{"label":"Bonus Health (Self)","value":"250"},{"label":"Slow Effect","value":"-3% per hit"},{"label":"Slow Duration","value":"1s"},{"label":"Hits Required To Stun","value":"20"},{"label":"Stun Duration","value":"1.5s"},{"label":"Energy Cost","value":"2800"},{"label":"Special Effect","value":"Striking an enemy applies a stacking Slow effect, and after reaching a certain number of stacks, the enemy will be Stunned"}]'::jsonb, 2),
  (36591, 'spider-man', null, null, 'Web-Swing', 'Ability', 'Shoot a strand of webbing to swing.', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Dash"},{"label":"Maximum Webbing Length","value":"30m"},{"label":"Charges","value":"3"},{"label":"Recharge Speed","value":"6s per charge"}]'::jsonb, 3),
  (36592, 'spider-man', null, null, 'Get Over Here!', 'Ability', 'Shoot webbing to reel in the hit enemy. If the enemy is tagged with a Spider-Tracer, Spider-Man will get pulled to them instead', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Projectile that fires in a straight trajectory"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Maximum Distance","value":"20m"},{"label":"Projectile Damage","value":"25"},{"label":"Kicking Distance","value":"24m"},{"label":"Kick Damage","value":"55"},{"label":"Cooldown","value":"8s"},{"label":"Special Mechanic","value":"Attack enemies marked with a Spider-Tracer, pulling Spider-Man towards them and performing a flying kick"}]'::jsonb, 4),
  (36593, 'spider-man', null, null, 'Amazing Combo', 'Ability', 'Launch an enemy upward, dealing extra damage to the enemy with a Spider-Tracer', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Melee"},{"label":"Range","value":"4m spherical radius"},{"label":"Damage","value":"70"},{"label":"Charges","value":"2"},{"label":"Recharge Speed","value":"6s per charge"},{"label":"Cooldown","value":"1s"}]'::jsonb, 5),
  (36594, 'spider-man', null, null, 'Thwip and Flip', 'Ability', 'Perform a double jump', '[{"label":"Key","value":"Space"},{"label":"Special Mechanic","value":"Can only be cast again after landing"}]'::jsonb, 6),
  (36595, 'spider-man', null, null, 'Spider-Sense', 'Passive', 'Give a warning of enemies that have been around', '[{"label":"Key","value":"Passive"},{"label":"Disappearance Time To Trigger Detection","value":"3s"},{"label":"Range","value":"8m spherical radius"}]'::jsonb, 7),
  (36596, 'spider-man', null, null, 'Wall Crawl', 'Ability', 'Press Space to wall crawl, and while crawling, left-click to sprint', '[{"label":"Key","value":"Space"},{"label":"Wall-Crawling Speed","value":"3 m/s"},{"label":"Sprinting Speed","value":"9 m/s"}]'::jsonb, 8),
  (36597, 'spider-man', null, null, 'Inferno Blast', 'Team-Up Ability', 'Human Torch stores Pyrokinetic Energy in Spider-Man''s suit, enabling him to unleash an Inferno Blast that sprays a fiery web while performing a backflip to create distance. The flames damage enemies and apply a Burn-Tracer. Detonating these Burn-Tracers inflicts Damage Over Time', '[{"label":"Key","value":"C"},{"label":"Damage","value":"30"},{"label":"Maximum Distance","value":"8m"},{"label":"Burn-Tracer Duration","value":"3s"},{"label":"Burn-Tracer Dot Duration","value":"4s"},{"label":"Burn-Tracer Dot Damage","value":"15/s"},{"label":"Backflip Distance","value":"7m"},{"label":"Cooldown","value":"12s"}]'::jsonb, 9),
  (36598, 'spider-man', null, null, 'Sticky Spider-Bomb', 'Team-Up Ability', 'Cyber-Spiders Peni Parker whips up a Sticky Bomb for Spider-Man! Prime it, then toss it before the timer''s up for a blast that damages nearby enemies and attaches a Spider-Tracer to them. If not thrown in time, it explodes on Spider-Man, recharging a Web-Cluster shot and granting Bonus Health', '[{"label":"Key","value":"C"},{"label":"Countdown Duration","value":"3s"},{"label":"Projectile Damage","value":"10"},{"label":"Spell Field Damage","value":"30"},{"label":"Spell Field Range","value":"5m radius spherical spell field"},{"label":"Bonus Health","value":"50"},{"label":"Cooldown","value":"20"}]'::jsonb, 10),
  (36599, 'spider-man', null, null, 'SYMBIOTE BOND', 'Team-Up Ability', 'Base Effect: Venom shares a part of his symbiote with Spider-Man, activating their symbiote abilities. Spider-Man can convert the symbiotes into explosive spikes that inflict harm on nearby enemies and relentlessly drive them back. Enhanced Effect: When teaming up with Venom, this triggers additional Touch of Klyntar tendrils that continuously tether and damage enemies on top of the base effect.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Damage Reduction Rate","value":"90%"},{"label":"One-Time Damage","value":"30"},{"label":"Damage Over Time","value":"10/hit, once per second"},{"label":"Damage Range","value":"5m spherical radius"},{"label":"Enhanced Damage Over Time","value":"1/hit, 10 times per second"},{"label":"Slow Rate","value":"50%"}]'::jsonb, 11),
  (36600, 'spider-man', null, null, 'PARKER POWER-UP', 'Team-Up Ability', 'Base Effect: Peni Parker whips up a Sticky Spider-Bomb for Spider-Man! Prime it, then toss it before the timer''s up for a blast that damages nearby enemies and attaches a Spider-Tracer to them. If not thrown in time, it explodes on Spider-Man, recharging all Web-Cluster shots. Enhanced Effect: When teaming up with Peni Parker, Spider-Tracers applied by Web-Cluster are upgraded. Detonating these upgraded marks generates Bonus Health for Spider-Man.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"10s"},{"label":"Sticky Spider-Bomb Explosion Damage","value":"50"},{"label":"Bonus Health","value":"50"},{"label":"Explosion Countdown","value":"2s"},{"label":"Bonus Health From Detonating Mark","value":"40"}]'::jsonb, 12),
  (36601, 'black-panther', null, null, 'Vibranium Claws', 'Normal Attack', 'Slice Vibranium Claws forward', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Melee"},{"label":"Damage","value":"35"},{"label":"Maximum Distance","value":"3m"},{"label":"Attack Interval","value":"0.44s per hit"}]'::jsonb, 0)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36602, 'black-panther', null, null, 'Bast''s Descent', 'Ultimate', 'Summon Bast, pouncing forward, dealing damage, and attaching a Vibranium Mark to enemies hit while refreshing Spirit Rend', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Cuboid Spell Field"},{"label":"Range","value":"Length: 22m, Width: 20m, Height: 7m"},{"label":"Casting Angle","value":"150°"},{"label":"Damage","value":"150"},{"label":"Energy Cost","value":"3300"},{"label":"Special Effect","value":"Gain 50% Damage Reduction during Bast''s Descent startup animation"}]'::jsonb, 1),
  (36603, 'black-panther', null, null, 'Spirit Rend', 'Ability', 'Lunge forward and deal damage to enemies. Vibranium Mark produces Bonus Health and refreshes the ability', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Movement-based damage ability"},{"label":"Average Speed","value":"50m/s"},{"label":"Maximum Distance","value":"15m"},{"label":"Damage","value":"80"},{"label":"Bonus Health","value":"25"},{"label":"Bonus Max Health","value":"75"},{"label":"Cooldown","value":"10s"}]'::jsonb, 2),
  (36604, 'black-panther', null, null, 'Spinning Kick', 'Ability', 'Spiral forward and attach a Vibranium Mark to enemies hit', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Movement-based damage ability"},{"label":"Average Speed","value":"15m/s"},{"label":"Maximum Distance","value":"16m"},{"label":"Damage","value":"75"},{"label":"Cooldown","value":"8s"}]'::jsonb, 3),
  (36605, 'black-panther', null, null, 'Subtle Step', 'Ability', 'Hold Space to run on a wall; perform a jump after detaching from the wall', '[{"label":"Key","value":"Space"},{"label":"Wall-Crawling Speed","value":"10m/s"}]'::jsonb, 4),
  (36606, 'black-panther', null, null, 'Spear Toss', 'Ability', 'Toss a Vibranium energy spear forward, creating a Vibranium Force Field and attaching a Vibranium Mark to enemies in its radius', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Arced projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"60m/s"},{"label":"Range","value":"5m spherical radius"},{"label":"Damage","value":"50"},{"label":"Cooldown","value":"6s"},{"label":"Charges","value":"2"}]'::jsonb, 5),
  (36607, 'black-panther', null, null, 'Panther''s Cunning', 'Passive', 'Deal higher damage when at low Health', '[{"label":"Key","value":"Passive"},{"label":"Trigger Condition","value":"Health drops below 100"},{"label":"Damage Boost","value":"20%"}]'::jsonb, 6),
  (36608, 'black-panther', null, null, 'GAMMA VIBRANIUM ARMOR', 'Team-Up Ability', 'Hulk charges Namor and Black Panther with gamma radiation. Namor can summon an extra Gamma Monstro which will continuously fire gamma rays at locked-on enemies. The longer the rays hit, the higher the damage. Black Panther''s Vibranium armor is enhanced; when his health is low he receives a gamma shield, blocking incoming attacks and becoming Unstoppable', '[{"label":"Key","value":"PASSIVE"},{"label":"Shield Value","value":"100"},{"label":"Health Threshold For Ability Activation","value":"100"},{"label":"Cooldown","value":"45"}]'::jsonb, 7),
  (36609, 'black-panther', null, null, 'DAMISA-YAO', 'Team-Up Ability', 'Base Effect: Triggers the elemental power within his armor, dealing damage and applying Slow to surrounding enemies while attaching Vibranium Marks. Enhanced Effect: When teaming up with Storm, enemies within range are launched toward Black Panther.', '[{"label":"Key","value":"C"},{"label":"Spell Field Range","value":"8m spherical radius"},{"label":"Damage","value":"30"},{"label":"Slow Rate","value":"35% for 2s"},{"label":"Cooldown","value":"15s"},{"label":"Special Effect","value":"When Black Panther teams up with Storm, pulls enemies within range toward himself"},{"label":"Enhanced Slow Rate","value":"45% for 2s"}]'::jsonb, 8),
  (36610, 'black-panther', null, null, 'DIMENSIONAL SHORTCUT', 'Team-Up Ability', 'Base Effect: Activate a Limbo stepping disc to instantly return to your position from a few seconds ago, gaining Bonus Health in the process. When the teleport ends, the disc collapses in an explosion, damaging nearby enemies and applying Vibranium Marks. Enhanced Effect: When teaming up with Magik, the teleportation sequence can be manually canceled mid-transit.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"35s"},{"label":"Bonus Health","value":"50"},{"label":"Explosion Range","value":"8m spherical radius spell field"},{"label":"Damage","value":"40"},{"label":"Special Effect","value":"Can be manually stopped during teleport"}]'::jsonb, 9),
  (36611, 'hela', null, null, 'Nightsword Thorn', 'Normal Attack', 'Throw Nightsword thorns', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast direct hit"},{"label":"Damage","value":"80"},{"label":"Damage Falloff","value":"Falloff begins at 18m, decreasing to 75% at 35m"},{"label":"Fire Rate","value":"2 rounds per second"},{"label":"Ammo","value":"10"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36612, 'hela', null, null, 'Goddess of Death', 'Ultimate', 'Soar into the sky and unleash Nastrond Crows from each hand at will', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Duration","value":"10s"},{"label":"Nastrond Crow Health","value":"1000"},{"label":"Fire Rate","value":"1 rounds per second"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Explosion Range","value":"6m spherical radius"},{"label":"Explosion Damage","value":"125"},{"label":"Explosion Damage Falloff","value":"32% falloff at 4m."},{"label":"Energy Cost","value":"4000"}]'::jsonb, 1),
  (36613, 'hela', null, null, 'Astral Flock', 'Ability', 'Transform into a Nastrond Crow to glide forth, press again to undo the transformation. Gain Bonus Health when the transformation ends', '[{"label":"Key","value":"Shift"},{"label":"Casting","value":"Dash"},{"label":"Dash Speed","value":"15 m/s"},{"label":"Dash Distance","value":"18m"},{"label":"Cooldown","value":"15s"},{"label":"Bonus Health","value":"25"},{"label":"Special Effect","value":"Shapeshift into a Nastrond Crow and gain invincibility"}]'::jsonb, 2),
  (36614, 'hela', null, null, 'Soul Drainer', 'Ability', 'Project an explosive Hel sphere to Stun nearby enemies.', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Arced projectile that generates a spell field upon impact"},{"label":"Projectile Speed","value":"40 m/s"},{"label":"Damage","value":"1"},{"label":"Range","value":"3m spherical radius"},{"label":"Spell Field Damage","value":"40"},{"label":"Stun Duration","value":"0.3s"},{"label":"Cooldown","value":"10s"}]'::jsonb, 3),
  (36615, 'hela', null, null, 'Piercing Night', 'Ability', 'Fire multiple Nightsword thorns that detonate after a delay', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Straight-line projectile that generates a spell field upon impact"},{"label":"Number Of Projectiles","value":"4"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Projectile Damage","value":"10"},{"label":"Explosion Delay","value":"3s"},{"label":"Range","value":"3m spherical radius"},{"label":"Spell Field Damage","value":"35 damage per round"},{"label":"Cooldown","value":"8s"},{"label":"Special Effect","value":"Projectiles stick to enemies on hit"}]'::jsonb, 4),
  (36616, 'hela', null, null, 'Nastrond Crowstorm', 'Passive', 'Defeating an enemy will generate a Nastrond Crow, exploding after a duration', '[{"label":"Key","value":"Passive"},{"label":"Delay","value":"1.8s"},{"label":"Range","value":"5m spherical radius"},{"label":"Damage","value":"80"}]'::jsonb, 5),
  (36617, 'hela', null, null, 'Hel''s Descent', 'Ability', 'Hold Space to fall slowly', '[{"label":"Key","value":"Space"},{"label":"Horizontal Movement Speed","value":"6 m/s"},{"label":"Descending Speed","value":"3.5 m/s"}]'::jsonb, 6),
  (36618, 'hela', null, null, 'Hel Tendrils', 'Team-Up Ability', 'Venom shares his symbiotes with Jeff and Hela. Hela''s Hel Tendrils unleash a symbiotic Hel Sphere. Upon hit, it pulls nearby enemies toward the impact point and links them, slowing enemies that try to escape.', '[{"label":"Key","value":"E"},{"label":"Projectile Speed","value":"40 m/s"},{"label":"Spell Field Damage","value":"40"},{"label":"Range","value":"3m spherical radius spell field"},{"label":"Stun Duration","value":"0.3s"},{"label":"Maximum Linking Distance","value":"5m"},{"label":"Maximum Linking Duration","value":"2s"},{"label":"Slow Effect","value":"Slow the enemies by 20% at the center, increasing to 40% at 2.5m from the center."},{"label":"Cooldown","value":"10s"}]'::jsonb, 7),
  (36619, 'hela', null, null, 'DEATH KNELL', 'Team-Up Ability', 'Hela channels energy of the undead to empower Namor. When Namor strikes with his trident, a spectral water column erupts at the target area, slowing enemies hit. Whenever Hela or Namor assist in a KO, an invulnerable Undead Monstro spawns at the fallen enemy''s position, automatically attacking the nearest foe for a short time before vanishing', '[{"label":"Key","value":"Passive"},{"label":"Undead Monstro Duration","value":"3s"},{"label":"Undead Monstro Damage","value":"10"},{"label":"Undead Monstro Fire Rate","value":"0.5s per hit"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 50% at 40m"}]'::jsonb, 8),
  (36620, 'hela', null, null, 'Hel Tendrils', 'Team-Up Ability', 'Base Effect: Replace Soul Drainer with Hel Tendrils. Upon hit, tendrils pull nearby enemies toward the impact point and links them, Slowingenemies that try to escape. Enhanced Effect: When teaming up with Venom, Piercing Night fires a dense volley of symbiote-infused Nightsword Thorns. Each direct Nightsword Thorn hit restores a portion of Hela''s Health', '[{"label":"Key","value":"PASSIVE"},{"label":"Cooldown","value":"10"},{"label":"Gravity Field Range","value":"3m spherical radius"},{"label":"Max Gravity Duration","value":"2s"},{"label":"Stun Duration","value":"0.5s"},{"label":"Slow Effect","value":"20%, up to 40% at 2.5m from center"},{"label":"Damage","value":"50"},{"label":"Nightsword Thorn Increase","value":"2"},{"label":"Health Restored","value":"20 per round"}]'::jsonb, 9),
  (36621, 'hela', null, null, 'DEEP WRATH', 'Team-Up Ability', 'Base Effect: Whenever Hela participates in a KO, an Undead Monstro spawns at the fallen enemy''s position. While an Undead Monstro is present, casting Piercing Night will command the Monstro to spit a Nightsword Thorn at the nearest enemy. Enhanced Effect: When teaming up with Namor, each attack during Goddess of Death spawns an Undead Monstro at the point of impact.', '[{"label":"Key","value":"PASSIVE"},{"label":"Undead Monstro Health","value":"150"},{"label":"Undead Monstro Damage","value":"10 per round"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 50% at 40m"},{"label":"Attack Speed","value":"0.33s per round"},{"label":"Special Effect","value":"Each attack during Goddess of Death spawns an Undead Monstro at the point of impact."}]'::jsonb, 10),
  (36622, 'storm', null, null, 'Wind Blade', 'Normal Attack', 'Launch forward-piercing Wind Blades', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Projectile that fires in a straight trajectory"},{"label":"Projectile Speed","value":"150m/s"},{"label":"Damage","value":"60 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 15m, decreasing to 60% at 30m"},{"label":"Fire Rate","value":"2 rounds per second"},{"label":"Ammo","value":"12"},{"label":"Critical Hit","value":"No"},{"label":"Special Effect","value":"Wind Blade pierces through enemies"}]'::jsonb, 0),
  (36623, 'storm', null, null, 'Omega Hurricane', 'Ultimate', 'Transform into a hurricane to draw in nearby enemies and deal damage', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Spherical Spell Field"},{"label":"Maximum Selection Duration","value":"5s"},{"label":"Tornado Duration","value":"5s"},{"label":"Range","value":"8m spherical radius"},{"label":"Attack Interval","value":"2 hits per second"},{"label":"Damage","value":"80"},{"label":"Bonus Health (Self)","value":"450"},{"label":"Energy Cost","value":"3400"},{"label":"Special Effect","value":"Weather effects will be disabled during the Ultimate"}]'::jsonb, 1),
  (36624, 'storm', null, null, 'Weather Control', 'Ability', 'Switch the weather to empower allies: Tornado grants a Movement Boost; Thunder grants a Damage Boost', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Spherical Spell Field"},{"label":"Range","value":"15m spherical radius"},{"label":"Movement Boost (Self)","value":"16%"},{"label":"Movement Boost (Ally)","value":"8%"},{"label":"Special Effect","value":"Using Wind Blade and Bolt Rush under this aura grants Storm Bonus Health. Damage Conversion Ratio: 25%, up to a max of 75 Bonus Health"},{"label":"Damage Boost (Self)","value":"12%"},{"label":"Damage Boost (Ally)","value":"8%"},{"label":"Special Effect","value":"Under this aura, Wind Blade hits reduce Bolt Rush cooldown by 0.5s (only once per cast, even if hitting multiple enemies). Increase Bolt Rush spell field range radius from 1m to 1.5m"}]'::jsonb, 2),
  (36625, 'storm', null, null, 'Goddess Boost', 'Ability', 'Channel the power of the weather to empower Storm: Tornado grants a Movement Boost and inflicts Slow on enemies; Thunder grants a Damage Boost and summons lightning to inflict damage', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Spherical Spell Field"},{"label":"Range","value":"15m spherical radius"},{"label":"Duration","value":"8s"},{"label":"Cooldown","value":"15s"},{"label":"Movement Boost (Self)","value":"40%"},{"label":"Movement Boost (Ally)","value":"20%"},{"label":"Enemy Slow Rate","value":"-15%"},{"label":"Damage Boost (Self)","value":"25%"},{"label":"Damage Boost (Ally)","value":"15%"},{"label":"Strike Frequency","value":"2s per strike"},{"label":"Damage","value":"35"}]'::jsonb, 3),
  (36626, 'storm', null, null, 'Bolt Rush', 'Ability', 'Unleash a lightning bolt forward', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Straight Spell Field"},{"label":"Range","value":"A cylindrical spell field with a radius of 1m and a height of 40m"},{"label":"Damage","value":"80"},{"label":"Cooldown","value":"8s"}]'::jsonb, 4)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36627, 'storm', null, null, 'ETERNAL WEATHER WITCH', 'Team-Up Ability', 'Storm channels her elemental power into Adam Warlock. When Adam uses Soaring Surge, his movement speed is increased. While flying, Adam leaves behind a storm-charged trail that heals and speeds up allies within it', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"5% Damage Boost"}]'::jsonb, 5),
  (36628, 'storm', null, null, 'GOD OF THUNDER', 'Team-Up Ability', 'Base Effect: Upgrade Wind Blade into a hitscan beam that detonates upon striking a target. Enhanced Effect: When teaming up with Thor, Bolt Rush becomes Chain Lightning, allowing it to bounce from foe to foe', '[{"label":"Key","value":"Left Click"},{"label":"Beam Damage","value":"45"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 75% at 40m"},{"label":"Critical Hit","value":"Yes"},{"label":"Spell Field Range","value":"3m spherical radius"},{"label":"Spell Field Damage","value":"15"},{"label":"Enhanced Key","value":"Right Click"},{"label":"Cooldown","value":"6s"},{"label":"Bolt Rush Attack Range","value":"60m"},{"label":"Bolt Rush Bounce Range","value":"8m radius"},{"label":"Bolt Rush Hit Damage","value":"80"},{"label":"Bolt Rush Bounce Damage","value":"50"}]'::jsonb, 6),
  (36629, 'storm', null, null, 'JAWS OF FATE', 'Team-Up Ability', 'Base Effect: Unleash a torrential downpour that continuously heals both herself and her teammates. Enhanced Effect: When teaming up with Jeff the Land Shark, casting Omega Hurricane allows Jeff to swim inside the cyclone, generating a localized Jeff-nado.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Ability Duration","value":"8s"},{"label":"Healing Downpour Range","value":"15m radius"},{"label":"Self-Healing Rate","value":"35/s"},{"label":"Ally-Healing Rate","value":"25/s"},{"label":"Enhanced Key","value":"X"},{"label":"Jeff-Nado Damage","value":"80/hit, 2 times per second"},{"label":"Jeff-Nado Ability Duration Increase","value":"2s"},{"label":"Jeff-Nado Range","value":"10m radius"},{"label":"Jeff-Nado Ally-Healing Rate","value":"10/s"},{"label":"Jeff-Nado Self-Healing Rate","value":"15/s"},{"label":"Time Required To Swallow","value":"2.5"}]'::jsonb, 7),
  (36630, 'hulk', null, null, 'Gamma Ray Gun', 'Normal Attack', 'Fire with a Gamma Ray Gun', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact"},{"label":"Projectile Speed","value":"120m/s"},{"label":"Damage","value":"16"},{"label":"Fire Rate","value":"5 rounds per second"},{"label":"Ammo","value":"25"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36631, 'hulk', null, null, 'Puny Banner', 'Ultimate', 'Transform from Bruce Banner into Hero Hulk', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Transformation"},{"label":"Energy Cost","value":"600"},{"label":"Special Effect","value":"The caster is immobilized during the transformation process and gains Invincibility"}]'::jsonb, 1),
  (36632, 'hulk', null, null, 'Gamma Grenade', 'Ability', 'Launch a Gamma Grenade to inflict damage and Launch Up enemies', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Single-cast projectile with a downward delay that creates a spell field upon impact"},{"label":"Damage","value":"40"},{"label":"Range","value":"3m spherical radius"},{"label":"Cooldown","value":"8s"},{"label":"Special Effect","value":"When the caster enters the spell field, it restores 100 gamma energy"}]'::jsonb, 2),
  (36633, 'hulk', null, null, 'Gamma Boost', 'Team-Up Ability', 'Hulk charges Iron Man and Namor with gamma radiation. When Iron Man uses Armor Overdrive, he will initiate a gamma upgrade. When Namor receives the radiation, he will summon an extra Gamma Monstro which will continuously fire gamma rays at locked-on enemies. The longer the rays hit, the higher the damage', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"Hero Hulk and Monster Hulk gain 100 Max Health"}]'::jsonb, 3),
  (36634, 'hulk', null, null, 'Heavy Blow', 'Normal Attack', 'Swing fists forward to punch enemies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast Spell Field"},{"label":"Damage","value":"45"},{"label":"Range","value":"4.5m"},{"label":"Attack Interval","value":"0.467s"}]'::jsonb, 4),
  (36635, 'hulk', null, null, 'HULK SMASH!', 'Ultimate', 'Unleash stored gamma energy, transforming from Hero Hulk into Monster Hulk for a limited time period', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Transformation"},{"label":"Duration","value":"12s"},{"label":"Energy Cost","value":"3700"},{"label":"Special Effect","value":"The caster is immobilized during the transformation process and gains Invincibility"}]'::jsonb, 5),
  (36636, 'hulk', null, null, 'Indestructible Guard', 'Ability', 'Generate gamma shields for Hero Hulk and nearby allies, absorbing and converting damage into energy for HULK SMASH', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Single-cast spell field that surrounds the caster"},{"label":"Range","value":"5m spherical radius"},{"label":"Cooldown","value":"10s"},{"label":"Caster''S Shield Value","value":"200"},{"label":"Ally''S Shield Value","value":"100"},{"label":"Max Shield Duration","value":"2.5s"},{"label":"Special Effect","value":"When the caster''s shield takes damage, 130% of the damage is converted into gamma energy. When an ally''s shield takes damage, 10% of the damage is converted into gamma energy"}]'::jsonb, 6),
  (36637, 'hulk', null, null, 'Radioactive Lockdown', 'Ability', 'Emit gamma energy to irradiate enemies and render them immobilize and immune to all ability effects. Using Heavy Blow or Gamma Burst will prematurely remove this status', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Single-cast projectile."},{"label":"Projectile Speed","value":"100m/s"},{"label":"Damage","value":"5"},{"label":"Cooldown","value":"15s"},{"label":"Max Duration","value":"2s"},{"label":"Special Effect","value":"Heavy Blow and Gamma Burst can detect and damage irradiated enemies, and prematurely remove the status"},{"label":"Enhanced Casting","value":"Single-cast projectile"},{"label":"Enhanced Projectile Speed","value":"150m/s"},{"label":"Enhanced Cooldown","value":"5s"}]'::jsonb, 7),
  (36638, 'hulk', null, null, 'Incredible Leap', 'Ability', 'HOLD Space to perform a charged leap that allows Hero Hulk to Knock a flying enemy to the ground', '[{"label":"Key","value":"Space"},{"label":"Casting","value":"Charged Dash"},{"label":"Minimum Charge Time","value":"0.4s"},{"label":"Maximum Charge Time","value":"1.7s"},{"label":"Speed At Minimum Charge Time","value":"19m/s"},{"label":"Speed At Maximum Charge Time","value":"25m/s"},{"label":"Special Effect","value":"Press Space during the Incredible Leap to cling to the wall you encounter"}]'::jsonb, 8),
  (36639, 'hulk', null, null, 'Gamma Burst', 'Ability', 'Emit gamma-ray bursts to inflict damage. Reduce Indestructible Guard cooldown upon hit', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile that can pierce through enemies"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Damage","value":"65"},{"label":"Cooldown","value":"Basic Cooldown 2s, with a charge of 6s per use."},{"label":"Special Effect","value":"Each direct hit reduces Indestructible Guard cooldown by 1s"}]'::jsonb, 9),
  (36640, 'hulk', null, null, 'Gamma Fastball', 'Team-Up Ability', 'Wolverine, Hulk can interact with each other. Once both parties confirm, Hulk can lift Wolverine and press the key to hurl him forward', '[{"label":"Key","value":"C"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"20m"},{"label":"Cooldown","value":"3s when not thrown, 15s when thrown"}]'::jsonb, 10),
  (36641, 'hulk', null, null, 'Heavy Blow', 'Normal Attack', 'Swing fists forward to punch and launch up enemies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast Spell Field"},{"label":"Damage","value":"70"},{"label":"Range","value":"5m"},{"label":"Attack Interval","value":"0.52s"}]'::jsonb, 11),
  (36642, 'hulk', null, null, 'World Breaker', 'Ultimate', 'Grab and smash the enemy in front', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Targeted"},{"label":"Damage","value":"Delivers 5 hits, each dealing 40 damage"},{"label":"Duration","value":"5s"},{"label":"Range","value":"5m"},{"label":"Special Effect","value":"While performing the smash, Hulk gains a 30% Damage Reduction"}]'::jsonb, 12),
  (36643, 'hulk', null, null, 'Incredible Leap', 'Ability', 'HOLD Space to perform a charged leap that allows Monster Hulk to Knock a flying enemy to the ground', '[{"label":"Key","value":"Space"},{"label":"Casting","value":"Charged Dash"},{"label":"Minimum Charge Time","value":"0.7s"},{"label":"Maximum Charge Time","value":"1.5s"},{"label":"Speed At Minimum Charge Time","value":"19.4m/s"},{"label":"Speed At Maximum Charge Time","value":"25m/s"},{"label":"Special Effect","value":"Press Space during the Incredible Leap to cling to the wall you encounter"}]'::jsonb, 13),
  (36644, 'hulk', null, null, 'Gamma Burst', 'Ability', 'Emit gamma-ray bursts to inflict damage', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile that can pierce through enemies"},{"label":"Projectile Speed","value":"60m/s"},{"label":"Damage","value":"125"},{"label":"Cooldown","value":"1s"}]'::jsonb, 14),
  (36645, 'hulk', null, null, 'SAVAGE SLAM', 'Team-Up Ability', 'Base Effect: Leap high and smash the ground, dealing damage to enemies and reducing the cooldowns of other abilities based on remaining Health. Enhanced Effect: When teaming up with Captain America, the ground slam additionally applies Vulnerability to enemies hit.', '[{"label":"Key","value":"C"},{"label":"Launch Speed","value":"60 m/s"},{"label":"Landing Damage Range","value":"8m spherical radius spell field"},{"label":"Landing Damage","value":"40"},{"label":"Gamma Burst Cd Reduction","value":"1s, up to 3s at 400 HP"},{"label":"Radioactive Lockdown Cd Reduction","value":"1s, up to 3s at 400 HP"},{"label":"Indestructible Guard Cd Reduction","value":"2s, up to 5s at 400 HP"},{"label":"Cooldown","value":"20s"},{"label":"Enhanced Landing Damage","value":"50"},{"label":"Vulnerability Rate","value":"20% for 3s"}]'::jsonb, 15),
  (36646, 'hulk', null, null, 'GAMMA FASTBALL', 'Team-Up Ability', 'Base Effect: Enter a Furious state upon activation, gaining Speed Boost and Attack Speed for a duration. Also unlocks the Dances With Werewolves ability, granting Unstoppable for a period when Health drops to a certain threshold. Enhanced Effect: When teaming up with Wolverine, unlocks the Fastball Special. Upon mutual confirmation, Hulk hurls Wolverine forward', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Furious Duration","value":"6s"},{"label":"Movement Speed Boost","value":"25%"},{"label":"Attack Speed Boost","value":"25%"},{"label":"Unstoppable Threshold","value":"400"},{"label":"Unstoppable Duration","value":"6s"},{"label":"Unstoppable Cd","value":"45s"},{"label":"Enhanced Key","value":"X"}]'::jsonb, 16),
  (36647, 'jeff-the-land-shark', null, null, 'Joyful Splash', 'Normal Attack', 'Unleash a healing splash', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Rapid-fire, delayed projectile"},{"label":"Projectile Speed","value":"100m/s"},{"label":"Healing Amount","value":"140/s"},{"label":"Damage","value":"70/s"},{"label":"Damage Falloff","value":"Damage falloff starts at 15m to a maximum of 60% at 30m"},{"label":"Fire Rate","value":"20 rounds per second"},{"label":"Ammo","value":"100"}]'::jsonb, 0),
  (36648, 'jeff-the-land-shark', null, null, 'Aqua Burst', 'Normal Attack', 'Launch a high-speed water sphere that bursts upon impact, dealing damage to enemies within range', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact that also generates a spell field"},{"label":"Damage","value":"Projectile Damage: 30 damage per round, Spell Field Damage: 45 damage per cast"},{"label":"Range","value":"3m spherical radius"},{"label":"Damage Falloff","value":"Falloff begins at 1m, decreasing to 50% at 3m (projectile damage has no falloff)"},{"label":"Projectile Speed","value":"150m/s"},{"label":"Fire Rate","value":"1.75 rounds per second"},{"label":"Cooldown","value":"3 charges, with each charge taking 3s to recharge"},{"label":"Special Effect","value":"Direct hits can launch enemies up"},{"label":"Critical Hit","value":"No"}]'::jsonb, 1),
  (36649, 'jeff-the-land-shark', null, null, 'It''s Jeff!', 'Ultimate', 'Deep dive into the scene and resurface to swallow both enemies and allies within range, activating Hide and Seek for a brief duration before ejecting the swallowed heroes forward', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Targeted"},{"label":"Special Effect1","value":"After swallowing allies and enemies, Jeff will deal damage to enemies and heal allies for the duration of the effect, during which they will also benefit from Hide and Seek"},{"label":"Special Effect2","value":"It''s Jeff! (Ultimate Ability) leaves an 8m radius Healing Pool at the point of activation that heals allies within range by 130/s. Healing Pool lasts for 8s"},{"label":"Range","value":"10m radius,5m high cylindrical spell field"},{"label":"Damage","value":"25/s"},{"label":"Healing Amount","value":"225/s"},{"label":"Bonus Health (Ally)","value":"Overflow healing on swallowed allies grants 45 Health per second as Bonus Health, up to 150"},{"label":"Duration","value":"6s"},{"label":"Energy Cost","value":"4500"}]'::jsonb, 2),
  (36650, 'jeff-the-land-shark', null, null, 'Hide and Seek', 'Ability', 'Dive into the scene with only his dorsal fin exposed, granting himself a Movement Boost. Jeff can heal while submerged and gains the wall-crawl ability', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Instant Cast"},{"label":"Special Effect","value":"During the dive, gain Unstoppable, healing over time, and a Movement Boost, while Jeff''s hitbox is reduced"},{"label":"Movement Boost","value":"60%"},{"label":"Maximum Energy","value":"120"},{"label":"Energy Cost","value":"20/s"},{"label":"Energy Recovery Speed","value":"15/s"},{"label":"Healing Amount","value":"35/s"}]'::jsonb, 3),
  (36651, 'jeff-the-land-shark', null, null, 'Healing Bubble', 'Ability', 'Spit a bubble that heals the ally who collects it, granting them Healing Boost and Movement Boost while also launching up nearby enemies', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Summons"},{"label":"Special Effect","value":"Touching the bubble will immediately activate its effect"},{"label":"Healing Amount","value":"30/s"},{"label":"Healing Boost","value":"15%"},{"label":"Movement Boost","value":"60%"},{"label":"Buff Duration","value":"4s"},{"label":"Duration","value":"180s"},{"label":"Cooldown","value":"3 charges, with each charge taking 6s to recharge"}]'::jsonb, 4)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36652, 'jeff-the-land-shark', null, null, 'Oblivious Cuteness', 'Passive', 'Reduce damage taken from critical hits', '[{"label":"Key","value":"Passive"},{"label":"Critical Hit Damage Reduction","value":"50%"}]'::jsonb, 5),
  (36653, 'jeff-the-land-shark', null, null, 'IT''S JEFF-NADO!', 'Team-Up Ability', 'When Storm activates Omega Hurricane and Jeff the Land Shark''s It''s Jeff is ready, they can unleash a powerful Team-Up Ability. During this period, Storm''s Omega Hurricane merges with Jeff to form a Jeff-nado', '[{"label":"Key","value":"Z"},{"label":"Select Range","value":"60m radius, 90° fan-shaped area in front of Jeff"},{"label":"Swallow Time Required","value":"1.5s"},{"label":"Warning Before Swallow","value":"0.1"},{"label":"Swallow Range","value":"10m spherical radius spell field centered around Storm"},{"label":"Swallow Damage","value":"80"},{"label":"Attack Interval","value":"2 hits per second"}]'::jsonb, 6),
  (36654, 'jeff-the-land-shark', null, null, 'GUARDIAN OF THE DEEP', 'Team-Up Ability', 'Venom shares his symbiotes with Jeff and Hela. Jeff''s Guardian of the Deep links with nearby allies, providing continuous healing. When the effect ends, it releases a powerful healing burst, converting any excess into Bonus Health.', '[{"label":"Key","value":"X"},{"label":"Cooldown","value":"20s"},{"label":"Range","value":"10m spherical radius spell field"},{"label":"Continuous Healing Duration","value":"5s"},{"label":"Continuous Healing Efficiency","value":"60/s"},{"label":"One-Time Healing Amount","value":"70"},{"label":"Bonus Health","value":"50"},{"label":"Bonus Health Falloff","value":"Falloff begins at 3s and decreases by 30/s"}]'::jsonb, 7),
  (36655, 'jeff-the-land-shark', null, null, 'New Friends', 'Team-Up Ability', 'Jeff the Land Shark and Rocket Raccoon can ride on Groot''s shoulders, receiving Damage Reduction', '[{"label":"Key","value":"None"},{"label":"Casting","value":"Targeted"},{"label":"Range","value":"Up to 12m"},{"label":"Damage Reduction","value":"35%"}]'::jsonb, 8),
  (36656, 'jeff-the-land-shark', null, null, 'Jeff''s Cuddle Buddy', 'Team-Up Ability', 'Jeff the Land Shark and Rocket Raccoon can ride on Groot''s shoulders, receiving Damage Reduction', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"35"},{"label":"Spell Field Range","value":"A cylindrical spell field with a 6m radius and a height of 6m."},{"label":"Healing","value":"50/s"},{"label":"Duration","value":"5s"}]'::jsonb, 9),
  (36657, 'jeff-the-land-shark', null, null, 'GUARDIAN OF THE DEEP', 'Team-Up Ability', 'Base Effect: Shoot out healing tendrils; linked allies receive Continuous Healing, and excess healing is converted into Bonus Health. Enhanced Effect: When teaming up with Venom, symbiote tendrils can also lash out at nearby enemies within range, inflicting continuous damage.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20"},{"label":"Spell Field Range","value":"15m spherical radius"},{"label":"Healing Amount","value":"45/s"},{"label":"Overhealing To Bonus Health Conversion Rate","value":"0.5"},{"label":"Ability Duration","value":"5s"},{"label":"One-Time Healing","value":"45"},{"label":"Damage Over Time","value":"35/s"}]'::jsonb, 10),
  (36658, 'jeff-the-land-shark', null, null, 'MR. POOL''S INTERDIMENSIONAL TOY BOX', 'Team-Up Ability', 'Base Effect: Gain a new ability to spit out a Deadpool Plushie. The plushie continuously Taunts nearby enemies while spraying a healing mist onto surrounding allies. Enhanced Effect: When teaming up with Deadpool, the Deadpool Plushie asserts a much stronger Taunt while concurrently damaging enemies caught in its radius.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15"},{"label":"Deadpool Plushie Duration","value":"5s"},{"label":"Deadpool Plushie Range","value":"6m radius"},{"label":"Healing Amount","value":"30/s"},{"label":"Damage","value":"30/s"}]'::jsonb, 11),
  (36659, 'the-punisher', null, null, 'Adjudication', 'Normal Attack', 'Fire at enemies with Adjudication, his Automatic Rifle', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Rapid-fire projectile"},{"label":"Damage","value":"19 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 85% at 40m"},{"label":"Crosshair Spread Radius (At 10m)","value":"Up to a 0.075m radius."},{"label":"Fire Rate","value":"10 rounds per second"},{"label":"Ammo","value":"40"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36660, 'the-punisher', null, null, 'Deliverance', 'Normal Attack', 'Fire at enemies with Deliverance, his Shotgun', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Shotgun projectiles that hit instantly"},{"label":"Damage","value":"9.5 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 8m, decreasing to 40% at 15m"},{"label":"Bullets Fired Each Cast","value":"16"},{"label":"Crosshair Spread Radius (At 10m)","value":"0.6m"},{"label":"Fire Rate","value":"1.43 rounds per second"},{"label":"Ammo","value":"8"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 1),
  (36661, 'the-punisher', null, null, 'Final Judgement', 'Ultimate', 'Unleash two Gatling guns and missiles to attack enemies', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Rapid-fire projectiles that hit instantly and have a tracking trajectory"},{"label":"Duration","value":"10s"},{"label":"Slow Rate While Idling","value":"-10%"},{"label":"Slow Rate While Shooting","value":"-30%"},{"label":"Energy Cost","value":"3400"},{"label":"Damage","value":"8 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 70% at 40m"},{"label":"Crosshair Spread Radius (At 10m)","value":"Start with a spread radius of 0.6m, which reduces to 0.3m after 50 shots, and further decreases to 0.15m after 100 shots"},{"label":"Fire Rate","value":"33.33 rounds per second"},{"label":"Ammo","value":"Infinite"},{"label":"Critical Hit","value":"Yes"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Damage","value":"50"},{"label":"Interval Between Volleys","value":"3s"},{"label":"Interval Between Missiles","value":"0.3s"},{"label":"Maximum Number Of Missiles Per Volley","value":"8"},{"label":"Maximum Number Of Locked-On Missiles Per Target","value":"3"},{"label":"Maximum Locking Distance","value":"40m"}]'::jsonb, 2),
  (36662, 'the-punisher', null, null, 'Vantage Connection', 'Ability', 'Launch a hook to generate a cable that enables the Punisher to move rapidly by pressing F', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Dash"},{"label":"Cable Attachment Angle","value":"20° - 160°"},{"label":"Cable Length","value":"5m - 35m"},{"label":"Dash Speed","value":"25 m/s"},{"label":"Cooldown","value":"20s"}]'::jsonb, 3),
  (36663, 'the-punisher', null, null, 'Culling Turret', 'Ability', 'Deploy a Culling Turret that grounds Punisher and blocks damage from the front while dealing massive damage', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Rapid-fire projectiles that create a spell field upon impact"},{"label":"Damage","value":"10 damage per round"},{"label":"Explosion Damage","value":"10 damage per round"},{"label":"Explosion Range","value":"3m spherical radius"},{"label":"Crosshair Spread Radius (At 10m)","value":"Start with a spread radius of 0.2m, which reduces to 0.1m after 10 shots, and further decreases to 0.05m after 20 shots"},{"label":"Fire Rate","value":"12.5 rounds per second"},{"label":"Ammo","value":"200"},{"label":"Turret Health","value":"600"},{"label":"Cooldown","value":"20s"}]'::jsonb, 4),
  (36664, 'the-punisher', null, null, 'Scourge Grenade', 'Ability', 'Throw a smoke grenade forward to obscure enemy vision and leap backward', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Projectile with an arced trajectory"},{"label":"Projectile Speed","value":"40 m/s"},{"label":"Range","value":"5m spherical radius"},{"label":"Damage","value":"45"},{"label":"Backward Jump Distance","value":"9m"},{"label":"Cooldown","value":"8s"},{"label":"Special Effect","value":"Create a temporary smokescreen that obstructs vision"}]'::jsonb, 5),
  (36665, 'the-punisher', null, null, 'Warrior''s Gaze', 'Passive', 'Retain vision of enemies that disappear from view for a short duration', '[{"label":"Key","value":"Passive"},{"label":"Special Effect","value":"Retain vision of enemies that disappear from view for a short duration"},{"label":"Range","value":"30m spherical radius"},{"label":"Duration","value":"3s"}]'::jsonb, 6),
  (36666, 'the-punisher', null, null, 'CUTTING-EDGE TECH', 'Team-Up Ability', 'The Punisher upgrades Black Widow''s arsenal, adding a Pulse Mode to her Red Room Rifle. While the ability is active, using Straight Shooter fires a pulse beam that deals piercing damage', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"+25 Max Health, +5% Damage Boost"}]'::jsonb, 7),
  (36667, 'the-punisher', null, null, 'JUSTICE SENSE', 'Team-Up Ability', 'Daredevil shares the location of his Sonic Pursuit target with The Punisher. At the same time, The Punisher can launch a devil-infused shock grenade to damage and blind enemies', '[{"label":"Key","value":"C"},{"label":"Casting","value":"Projectile with an arced trajectory"},{"label":"Projectile Speed","value":"40 m/s"},{"label":"Range","value":"5m spherical radius"},{"label":"Damage","value":"45"},{"label":"Cooldown","value":"15s"},{"label":"Blind Effect Duration","value":"1.5s"}]'::jsonb, 8),
  (36668, 'the-punisher', null, null, 'Ancient Judgement', 'Team-Up Ability', 'The Punisher rides atop Devil Dinosaur, restricting him to only Adjudication/Deliverance and Scourge Grenade while disabling other abilities. While mounted, Devil Dinosaur absorbs a portion of all damage inflicted on The Punisher', '[{"label":"Key","value":"X"},{"label":"Damage Reduction","value":"25%"},{"label":"Conversion Ratio","value":"50%"}]'::jsonb, 9),
  (36669, 'the-punisher', null, null, 'BESTIAL HUNT', 'Team-Up Ability', 'Base Effect: Shoot piercing bullets that carry a Damage Boost effect. Enhanced Effect: When teaming up with Daredevil, the bullets break enemy summoned walls and shields more quickly.', '[{"label":"Key","value":"PASSIVE"},{"label":"Adjudication Piercing Beam Damage","value":"20 damage per round"},{"label":"Deliverance Piercing Beam Damage","value":"10 damage per round"},{"label":"Bonus Damage To Barriers","value":"40%"}]'::jsonb, 10),
  (36670, 'the-punisher', null, null, 'AMMO OVERLOAD', 'Team-Up Ability', 'Base Effect: Throw an Ammo Overload Device in the target direction. Upon entering the device''s range, receive Faster Firing. Enhanced Effect: When teaming up with Rocket Raccoon, the device grants Infinite Ammo.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"25s"},{"label":"Device Effect Range","value":"5m radius"},{"label":"Adjudication Fire Rate Boost","value":"35%"},{"label":"Deliverance Fire Rate Boost","value":"40%"},{"label":"Special Effect","value":"Adds unlimited ammo on top of the base effect"}]'::jsonb, 11),
  (36671, 'luna-snow', null, null, 'Light & Dark Ice', 'Normal Attack', 'Fire ice shots that damage enemies or heal allies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"A triple shot that hits instantly"},{"label":"Damage","value":"24 damage per round, for a total of 72 damage"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 70% at 40m"},{"label":"Healing Amount","value":"24 health per round, for a total of 72 health"},{"label":"Fire Rate","value":"0.5s for three shots. The interval between the first two shots is 0.05s"},{"label":"Ammo","value":"30"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36672, 'luna-snow', null, null, 'Fate of Both Worlds', 'Ultimate', 'Take center stage and start dancing! Press to toggle between two performances: Heal allies or grant them Damage Boost', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Persistent spell field that surrounds the caster"},{"label":"Healing Amount","value":"250/s"},{"label":"Damage Boost","value":"40%"},{"label":"Cast To Heal The Ally Once","value":"200"},{"label":"Shield Value","value":"250"},{"label":"Duration","value":"10s"},{"label":"Energy Cost","value":"4800"}]'::jsonb, 1),
  (36673, 'luna-snow', null, null, 'Ice Arts', 'Ability', 'Fire ice shards for a short duration, damaging enemies or healing allies while restoring her own Health', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Single-cast spell field that pierces through enemies"},{"label":"Special Effect","value":"Replace the previous Light & Dark Ice cast"},{"label":"Damage","value":"50 damage per round"},{"label":"Healing Amount","value":"75 health per round"},{"label":"Range","value":"A cylindrical spell field with a radius of 1m and a height of 40m"},{"label":"Fire Rate","value":"1.43 rounds per second"},{"label":"Duration","value":"6s"},{"label":"Cooldown","value":"15s"}]'::jsonb, 2),
  (36674, 'luna-snow', null, null, 'Share the Stage', 'Ability', 'Attach Idol Aura to an ally. Allies with Idol Aura also restore Health when Luna Snow is healing others', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Targeted"},{"label":"Healing Boost","value":"35%"},{"label":"Special Effect","value":"Provide healing to allies marked with Idol Aura; Reduce Ice Arts cooldown by 2s whenever a hero with Idol Aura takes part in a KO"}]'::jsonb, 3),
  (36675, 'luna-snow', null, null, 'Absolute Zero', 'Ability', 'Cast a clump of ice to Freeze the hit enemy and restore Health', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Damage","value":"50"},{"label":"Special Effect","value":"Freeze enemies for 2.7s. However, if they are attacked during the last 2.2s of the freeze, the effect will be canceled. Grants 50 Bonus Health per enemy hit"},{"label":"Cooldown","value":"12s"}]'::jsonb, 4),
  (36676, 'luna-snow', null, null, 'Cryo Heart', 'Passive', 'Automatically restore Health when casting Ice Arts or Absolute Zero', '[{"label":"Key","value":"Passive"},{"label":"Healing Amount","value":"35/s for 3 seconds"}]'::jsonb, 5)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36677, 'luna-snow', null, null, 'Smooth Skate', 'Passive', 'Keep moving forward to start ice skating and enable higher jumps', '[{"label":"Key","value":"Passive"},{"label":"Time Required To Start Skating","value":"0.5s"},{"label":"Skating Speed","value":"9.6m/s"}]'::jsonb, 6),
  (36678, 'luna-snow', null, null, 'Number One Idol', 'Ability', 'Boost Healing. Gain extra healing when healing others', '[{"label":"Key","value":"F"},{"label":"Healing Boost","value":"10%"}]'::jsonb, 7),
  (36679, 'luna-snow', null, null, 'ICED OUT DIAMOND', 'Team-Up Ability', 'Luna Snow grants Winter''s Chill to Iron Fist and Emma Frost. When Iron Fist activates Harmony Recovery, he can heal nearby allies with Lunar Chi. Emma Frost can project ice energy forward, dealing damage and slowing enemies. She can also enhance her diamond form, condensing frost into an Absolute Zero Diamond barrier that blocks enemy attacks and movement', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"5% Healing Boost"}]'::jsonb, 8),
  (36680, 'luna-snow', null, null, 'SPIRIT FOX ACCORD', 'Team-Up Ability', 'White Fox grants Luna Snow a spirit fox for protection. Luna can activate it for a burst of speed and fire it forward, healing allies in its path while applying Charm to enemies', '[{"label":"Key","value":"C"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Damage Area Radius","value":"3m"},{"label":"Charm Area Radius","value":"0.8m"},{"label":"Damage","value":"35"},{"label":"Healing Amount","value":"60"},{"label":"Charm Duration","value":"0.4s"},{"label":"Cooldown","value":"20s"},{"label":"Movement Boost (Self)","value":"30% for 4s"}]'::jsonb, 9),
  (36681, 'luna-snow', null, null, 'ATLAS BOND', 'Team-Up Ability', 'Base Effect: Unleash a spirit fox forward that Charms enemies while healing any allies in its path. Activating the ability instantly cleanses all negative status effects on Luna Snow. Enhanced Effect: When teaming up with White Fox, the spirit fox automatically returns after reaching its maximum distance, and the self-cleanse is retained.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Healing Amount","value":"70"},{"label":"Charm Duration","value":"0.35s"},{"label":"Flight Speed","value":"60 m/s"},{"label":"Maximum Flight Distance","value":"40m"},{"label":"Damage","value":"35"},{"label":"Damage Radius","value":"3m"},{"label":"Charm Radius","value":"0.8m"},{"label":"Enhanced Cooldown","value":"10"}]'::jsonb, 10),
  (36682, 'luna-snow', null, null, 'DUALITY DANCE', 'Team-Up Ability', 'Base Effect: Cast Soul Bond to tether all characters within range. Attacking tethered enemies or healing linked allies restores your Health. Enhanced Effect: When teaming up with Adam Warlock, scoring critical hits with Light & Dark Ice reduces the cooldowns of Absolute Zero and Ice Arts.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Ability Duration","value":"6s"},{"label":"Chain Cast Detection Range","value":"20m radius"},{"label":"Max Chain Distance","value":"25m"},{"label":"Damage Dealt To Self-Healing Ratio","value":"50%"},{"label":"Ally Healing To Self-Healing Ratio","value":"25%"},{"label":"Ice Arts Cd Reduction Per Crit","value":"1.5s"},{"label":"Absolute Zero Cd Reduction Per Crit","value":"0.5s"}]'::jsonb, 11),
  (36683, 'adam-warlock', null, null, 'Quantum Magic', 'Normal Attack', 'Launch quantum energy to deal damage', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast direct hit"},{"label":"Damage","value":"60 damage per round"},{"label":"Damage Falloff","value":"Falloff begins at 20m, decreasing to 60% at 40m"},{"label":"Fire Rate","value":"2 rounds per second"},{"label":"Ammo","value":"15"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36684, 'adam-warlock', null, null, 'Karmic Revival', 'Ability', 'Take to the skies, entering a flying state and swiftly surge forward', '[{"label":"Key","value":"F"},{"label":"Movement Boost","value":"4m/s"},{"label":"Maximum Energy","value":"120"},{"label":"Energy Cost","value":"30/s"},{"label":"Energy Recovery Speed","value":"8/s"}]'::jsonb, 1),
  (36685, 'adam-warlock', null, null, 'Karmic Revival', 'Ultimate', 'Awaken the karma of allies to revive them. Allies revived have lower health but enjoy a brief period of Invincibility', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Persistent spell field that surrounds the caster"},{"label":"Special Effect","value":"Revive allies within range, centered on Adam. Continuously monitor for fallen allies within this range; if they enter the area, they can be revived at the casting location"},{"label":"Health Upon Revival","value":"30% of the Max Health"},{"label":"Range","value":"35m spherical radius"},{"label":"Duration","value":"10s"},{"label":"Energy Cost","value":"4500"},{"label":"Health Upon Revival","value":"Allies revived will be blessed with Bonus Health equal to 70% of their Maximum Health with a 5s duration. Bonus Health falloff begins at 5s, decreasing to 0 in 2s."}]'::jsonb, 2),
  (36686, 'adam-warlock', null, null, 'Soul Bond', 'Ability', 'Forge a soul bond with allies, granting Healing Over Time and distributing damage taken across the bond', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Instant Cast"},{"label":"Special Effect 1","value":"Adam Warlock will share a portion of the damage sustained by linked allies. If Adam Warlock sustains damage that would KO him due to the link, then the link will be broken, and he will retain 1 Health. The link will also break once enough damage is sustained, if Adam Warlock or the linked ally leave the link''s range, or after a certain length of time has passed"},{"label":"Special Effect 2","value":"Adam can hover and attack during the ability''s duration"},{"label":"Healing Amount","value":"15/s"},{"label":"Range","value":"15m"},{"label":"Duration","value":"6s"},{"label":"Maximum Damage Shared Per Target","value":"250"},{"label":"Cooldown","value":"40s"}]'::jsonb, 3),
  (36687, 'adam-warlock', null, null, 'Avatar Life Stream', 'Ability', 'Target an ally for a bouncing stream of healing energy, which also heals himself upon casting; self-targets if no ally is selected', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Targeted"},{"label":"Special Effect","value":"Bouncing target does not include Adam Warlock"},{"label":"Healing Amount","value":"95"},{"label":"Healing Amount (Self)","value":"35"},{"label":"Number Of Bounces","value":"2"},{"label":"Range","value":"20m spherical radius"},{"label":"Cooldown","value":"2 charges, with each charge taking 6s to recharge; when a critical hit lands on an enemy, reduce the cooldown time of Avatar Life Stream by 1s."}]'::jsonb, 4),
  (36688, 'adam-warlock', null, null, 'Cosmic Cluster', 'Ability', 'Gather quantum energy into a cluster and then swiftly launch it at the enemy', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Charged release, with multiple delayed projectiles"},{"label":"Damage","value":"35"},{"label":"Maximum Projectile Count","value":"5"},{"label":"Fire Rate","value":"The firing interval for a single charged shot is 0.3s, while the interval for multiple shots is 0.07s"},{"label":"Projectile Speed","value":"100 m/s"},{"label":"Special Effect","value":"Cosmic Cluster shares ammo with Quantum Magic, each hit reduces the cooldown of Avatar Life Stream by 0.6s."}]'::jsonb, 5),
  (36689, 'adam-warlock', null, null, 'Regenerative Cocoon', 'Passive', 'Once his body perishes, Adam Warlock can freely move as a soul and reforge his body at a chosen spot', '[{"label":"Key","value":"Passive"},{"label":"Cooldown","value":"105s"}]'::jsonb, 6),
  (36690, 'adam-warlock', null, null, 'HEAVENLY HARMONY', 'Team-Up Ability', 'Storm channels her elemental power into Adam Warlock. When Adam uses Soaring Surge, his movement speed is increased. While flying, Adam leaves behind a storm-charged trail that heals and speeds up allies within it', '[{"label":"Key","value":"F"},{"label":"Movement Boost","value":"5m/s"},{"label":"Maximum Energy","value":"120"},{"label":"Energy Cost","value":"30/s"},{"label":"Energy Recovery Speed","value":"8/s"},{"label":"Trail Width","value":"4m"},{"label":"Trail Duration","value":"5s"},{"label":"Healing Amount","value":"35/s"},{"label":"Movement Boost","value":"0.25"}]'::jsonb, 7),
  (36691, 'adam-warlock', null, null, 'COSMIC CYCLONE', 'Team-Up Ability', 'Base Effect: Teammates linked by Soul Bond receive a Speed Boost. Enhanced Effect: When teaming up with Storm, linked teammates additionally gain a Damage Boost.', '[{"label":"Key","value":"Shift"},{"label":"Movement Boost","value":"20%"},{"label":"Soul Bond Range Increase","value":"5m"},{"label":"Damage Boost","value":"12%"},{"label":"Enhanced Movement Boost","value":"30%"}]'::jsonb, 8),
  (36692, 'adam-warlock', null, null, 'FLAWLESS DESIGN', 'Team-Up Ability', 'Base Effect: Cosmic Cluster now provides healing to allies. Enhanced Effect: When teaming up with Ultron, Cosmic Cluster creates an explosion upon impact.', '[{"label":"Key","value":"Right Click"},{"label":"Healing To Allies Hit By Cosmic Cluster","value":"18 per round"},{"label":"Quantum Magic Ammo Increase","value":"10"},{"label":"Spell Field Range","value":"3m spherical radius"},{"label":"Spell Field Damage","value":"5/shot"},{"label":"Spell Field Healing","value":"7/shot"}]'::jsonb, 9),
  (36693, 'rocket-raccoon', null, null, 'Bombard Mode', 'Normal Attack', 'Fire energy projectiles that deal damage', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Rapid-fire, delayed projectile"},{"label":"Damage","value":"16 damage per round"},{"label":"Projectile Speed","value":"180 m/s"},{"label":"Damage Falloff","value":"Falloff begins at 10m, decreasing to 40% at 20m"},{"label":"Fire Rate","value":"12.05 rounds per second"},{"label":"Ammo","value":"45"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36694, 'rocket-raccoon', null, null, 'Repair Mode', 'Normal Attack', 'Shoot bouncing spheres to heal allies', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact that also generates a spell field"},{"label":"Healing Amount (Ally)","value":"50/s"},{"label":"One-Time Healing Amount","value":"55"},{"label":"Healing Amount (Self)","value":"30/s"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Range","value":"5m spherical radius"},{"label":"Fire Rate","value":"2 rounds per second"},{"label":"Ammo","value":"8"},{"label":"Duration","value":"5s"},{"label":"Special Effect","value":"One-time healing for allies when projectile hits them，Bouncing Spheres will bounce off surfaces upon contact, with a maximum of 10 bounces. When they approach injured allies, their speed will reduce"},{"label":"Projectile Speed Reduction","value":"7 m/s"}]'::jsonb, 1),
  (36695, 'rocket-raccoon', null, null, 'C.Y.A.', 'Ultimate', 'Deploy a Cosmic Yarn Amplifier that grants allies a Damage Boost', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Targeted ability that, when activated, summons a creature and detects allies within the area."},{"label":"Damage Boost","value":"40%"},{"label":"Bonus Health","value":"100/s"},{"label":"Bonus Max Health","value":"150"},{"label":"Range","value":"20m radius"},{"label":"Duration","value":"12s"},{"label":"Summons'' Health","value":"800"},{"label":"Special Effect","value":"During the ability''s duration, linked allies will receive an additional 100 Bonus Health points per second, capping at 150. After breaking the link, this bonus starts to falloff after 1 second at a rate of 75 per/s"},{"label":"Energy Cost","value":"4300"}]'::jsonb, 2),
  (36696, 'rocket-raccoon', null, null, 'Jetpack Dash', 'Ability', 'Dash forward', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Dash"},{"label":"Dash Direction","value":"Crosshair Direction"},{"label":"Dash Distance","value":"8m"},{"label":"Cooldown","value":"2 charges, with each charge taking 10s to recharge"}]'::jsonb, 3),
  (36697, 'rocket-raccoon', null, null, 'B.R.B.', 'Ability', 'Deploy a Battle Rebirth Beacon that revives a fallen ally and periodically produces armor packs and rocket jet packs', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Summons"},{"label":"Special Effect","value":"Generate an item every 3s, including Armor Pack and Rocket Boots"},{"label":"Maximum Revive Distance","value":"50m"},{"label":"Bonus Health From Armor Pack","value":"25"},{"label":"Duration","value":"300s"},{"label":"Cooldown","value":"40s. You can reclaim the beacon by pressing E. When reclaimed, the cooldown will be reduced based on the beacon''s remaining health. If you reclaim a full-health beacon, the minimum cooldown will be 5s"}]'::jsonb, 4),
  (36698, 'rocket-raccoon', null, null, 'Wild Crawl', 'Ability', 'Hold Space to run on a wall', '[{"label":"Key","value":"Space"},{"label":"Wall-Crawling Speed","value":"8m/s"}]'::jsonb, 5),
  (36699, 'rocket-raccoon', null, null, 'Flying Ace', 'Ability', 'Hold Space to fall slowly', '[{"label":"Key","value":"Space"},{"label":"Descending Speed","value":"3.5m/s"}]'::jsonb, 6),
  (36700, 'rocket-raccoon', null, null, 'Old Friends', 'Team-Up Ability', 'Jeff the Land Shark and Rocket Raccoon can ride on Groot''s shoulders, receiving Damage Reduction', '[{"label":"Key","value":"C"},{"label":"Casting","value":"Targeted"},{"label":"Range","value":"Up to 12m"},{"label":"Special Effect","value":"Pressing SHIFT will exit the Team-Up status with Groot"},{"label":"Damage Reduction","value":"0.35"}]'::jsonb, 7),
  (36701, 'rocket-raccoon', null, null, 'MAMMALIAN BOND', 'Team-Up Ability', 'Base Effect: Tosses out a scattered batch of augmented Vitality Acorns. Acorns that hit the floor can be collected. Whether struck directly or picked up, teammates receive a burst of healing and global cooldown reduction. Enhanced Effect: When teaming up with Squirrel Girl, the maximum charge count for this ability is increased.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"2 charges, with each charge taking 20s to recharge."},{"label":"Vitality Acorn Amount","value":"5"},{"label":"Vitality Acorn Healing Amount","value":"30 per acorn"},{"label":"Ability Cooldown Reduction","value":"0.5s per acorn"},{"label":"Enhanced Cooldown","value":"3 charges, with each charge taking 20s to recharge."}]'::jsonb, 8)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36702, 'rocket-raccoon', null, null, 'PLANET X PALS', 'Team-Up Ability', 'Base Effect: Converts Bombard Mode to launch Thorny Spores. Upon impact, they deal continuous damage to enemies within the radius while healing and granting Bonus Health to allies. Enhanced Effect: When teaming up with Groot, Rocket can ride on Groot''s shoulders, and the active duration of the Thorny Spores field is extended.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Ability Duration","value":"8s"},{"label":"Spore Fire Rate","value":"0.2s per shot"},{"label":"Spore Damage","value":"18 per hit"},{"label":"Damage Over Time","value":"5 per round for 1 second"},{"label":"Healing Amount","value":"20 per round"},{"label":"Bonus Health","value":"20 damage per round"},{"label":"Spell Field Range","value":"5m spherical radius"},{"label":"Enhanced Key","value":"X"},{"label":"Duration:","value":"4s"}]'::jsonb, 9),
  (36703, 'loki', null, null, 'Mystical Missile', 'Normal Attack', 'Fire Mystical Missiles to heal allies or deal damage to enemies. Direct hits on allies provide extra healing', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact that also generates a spell field"},{"label":"Damage","value":"The projectile deals no damage, while the spell field inflicts 25 damage per cast"},{"label":"Range","value":"3m spherical radius"},{"label":"Damage Falloff","value":"Falloff begins at 0.5m, decreasing to 80% at 2.5m"},{"label":"Projectile Speed","value":"120 m/s"},{"label":"Area Of Effect Healing","value":"40 per hit"},{"label":"Fire Rate","value":"1.75 rounds per second"},{"label":"Ammo","value":"10"},{"label":"Critical Hit","value":"No"},{"label":"Healing Per Hit","value":"15 per hit"}]'::jsonb, 0),
  (36704, 'loki', null, null, 'God of Mischief', 'Ultimate', 'Shapeshift into a targeted ally or enemy hero and use all their abilities except any of their Team-Up Abilities', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Targeted"},{"label":"Special Effect","value":"After transforming, Loki''s Ultimate ability will be fully charged. Casting a transformation-type Ultimate ability will extend the duration of God of Mischief until the transformation ability ends"},{"label":"Duration","value":"12s"},{"label":"Energy Cost","value":"4500"}]'::jsonb, 1),
  (36705, 'loki', null, null, 'Regeneration Domain', 'Ability', 'Use Rune Stones to create a magical field that provides allies Healing and converts incoming damage into further healing', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Release a spell field at the location of Loki and the Illusion"},{"label":"Special Effect","value":"The spell field is sustained by Rune Stones. It will disappear if the Rune Stone is destroyed or if its maximum duration is reached. Allies within the field will receive healing over time, and any damage taken will be converted into healing based on the amount of damage taken"},{"label":"Range","value":"A cylindrical spell field with a radius of 5m and a height of 2m"},{"label":"Duration","value":"5s"},{"label":"Conversion Rate","value":"30%"},{"label":"Healing Amount","value":"100/s"},{"label":"Rune Stone Health","value":"100"},{"label":"Cooldown","value":"30s"}]'::jsonb, 2),
  (36706, 'loki', null, null, 'Doppelganger', 'Ability', 'Project an Illusion that can cast some of Loki''s abilities', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"30m"},{"label":"Special Effect","value":"Project an Illusion at a selected location"},{"label":"Cooldown","value":"2 charges, with each charge taking 12s to recharge"}]'::jsonb, 3),
  (36707, 'loki', null, null, 'Devious Exchange', 'Ability', 'Swap with the selected Illusion', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"30m"},{"label":"Cooldown","value":"15s"}]'::jsonb, 4),
  (36708, 'loki', null, null, 'Backstab', 'Ability', 'Pull out a dagger to stab enemies, dealing extra damage when attacking an enemy from behind', '[{"label":"Key","value":"V"},{"label":"Casting","value":"Single-cast Spell Field"},{"label":"Damage","value":"Damage: 30; Backstab Damage: +15 (total of 45)"},{"label":"Range","value":"3m"}]'::jsonb, 5),
  (36709, 'loki', null, null, 'Deception', 'Ability', 'Become Invisible and conjure an Illusion to deceive enemies', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Instant Cast"},{"label":"Special Effect","value":"Loki leaves an illusion in his place and becomes invisible while continuously healing himself. This invisibility has no time limit, but any actions other than casting Devious Exchange, reloading, or casting Doppelganger will render him visible"},{"label":"Healing Amount","value":"Health regenerates at a rate of 30 Health per second while invisible"},{"label":"Cooldown","value":"15s"}]'::jsonb, 6),
  (36710, 'loki', null, null, 'Deific Blessing', 'Team-Up Ability', 'Mantis enhances Groot''s wooden walls and Loki''s Rune Stones with life energy. Groot can additionally unleash a Flower Wall, which, when in Flora Colossus state, restores health to random nearby allies and grants them Damage Reduction. Loki''s Rune Stones grant allies within Regeneration Domain a Damage Boost', '[{"label":"Key","value":"Shift"},{"label":"Range","value":"A cylindrical spell field with a radius of 6.5m and a height of 2m."},{"label":"Maximum Duration For Summons","value":"5s"},{"label":"Conversion Rate","value":"30%"},{"label":"Healing Amount","value":"100/s"},{"label":"Rune Stone Health","value":"100"},{"label":"Cooldown","value":"30s"},{"label":"Damage Boost","value":"15%"}]'::jsonb, 7),
  (36711, 'loki', null, null, 'VILLAIN''S ILLUSION', 'Team-Up Ability', 'Base Effect: Gain a new ability to target fallen heroes (friend or foe), letting Loki assume their form for a set time (cannot cast their Ultimate Ability). Enhanced Effect: When teaming up with Hela, Loki''s transformation lasts slightly longer. Furthermore, taking lethal damage while transformed or in his Ultimate Ability state will merely revert him back to Loki with a sliver of Health, preventing a KO.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"30"},{"label":"Ability Duration","value":"6s"},{"label":"Enhanced Ability Duration","value":"8s"},{"label":"Health Retained On Death","value":"150"}]'::jsonb, 8),
  (36712, 'loki', null, null, 'VIBRANT VITALITY', 'Team-Up Ability', 'Base Effect: Gain a new ability to target fallen heroes (friend or foe), letting Loki assume their form for a set time (cannot cast their Ultimate Ability). Enhanced Effect: When teaming up with Hela, Loki''s transformation lasts slightly longer. Furthermore, taking lethal damage while transformed or in his Ultimate Ability state will merely revert him back to Loki with a sliver of Health, preventing a KO', '[{"label":"Key","value":"Shift"},{"label":"Cooldown","value":"30s"},{"label":"Summon Health Bar","value":"100"},{"label":"Duration","value":"5s"},{"label":"Field Range","value":"6.5m radius"},{"label":"Damage Boost Rate","value":"15%"},{"label":"One-Time Damage","value":"45"}]'::jsonb, 9),
  (36713, 'mantis', null, null, 'Life Energy Blast', 'Normal Attack', 'Fire an energy thorn and regain one Life Orb after a critical hit.', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact"},{"label":"Damage","value":"55 damage per round"},{"label":"Projectile Speed","value":"150m/s"},{"label":"Damage Falloff","value":"No falloff"},{"label":"Fire Rate","value":"2.5 rounds per second"},{"label":"Ammo","value":"15"},{"label":"Critical Hit","value":"Yes"},{"label":"Special Effect","value":"Critical hit generates 1 Life Orb"}]'::jsonb, 0),
  (36714, 'mantis', null, null, 'Soul Resurgence', 'Ultimate', 'Release energy around her while moving, providing Healing Over Time and Movement Boosts for surrounding allies. Excess healing converts to Bonus Health', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Persistent spell field that surrounds the caster"},{"label":"Healing Amount","value":"150"},{"label":"Caster & Ally One-Time Healing Amount","value":"200"},{"label":"Movement Boost","value":"3m/s"},{"label":"Excess Healing/Bonus Health Conversion","value":"100%"},{"label":"Excess Healing/Max Health Conversion","value":"150"},{"label":"Range","value":"15m spherical radius"},{"label":"Duration","value":"8s"},{"label":"Energy Cost","value":"4300"}]'::jsonb, 1),
  (36715, 'mantis', null, null, 'Spore Slumber', 'Ability', 'Throw a spore to Sedate the nearest enemy', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Single-cast projectile with delayed impact that also generates a spell field"},{"label":"Damage","value":"10"},{"label":"Range","value":"3m spherical radius"},{"label":"Sedation Duration","value":"3.5s"},{"label":"Special Effect","value":"A Mantis illusions will manifest beside the sedated heroes. Allies can attack this illusion to awaken the affected hero"},{"label":"Illusion Health","value":"100"},{"label":"Cooldown","value":"15s"}]'::jsonb, 2),
  (36716, 'mantis', null, null, 'Allied Inspiration', 'Ability', 'Consume Life Orbs to grant allies a Damage Boost', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Targeted"},{"label":"Damage Boost","value":"8%"},{"label":"Movement Boost","value":"1m/s"},{"label":"Duration","value":"8s (16s maximum duration)"},{"label":"Cooldown","value":"Consume 1 Life Orb"}]'::jsonb, 3),
  (36717, 'mantis', null, null, 'Natural Anger', 'Ability', 'Consume Life Orbs to grant herself a Damage Boost', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Instant Cast"},{"label":"Damage Boost","value":"12%"},{"label":"Duration","value":"8s (the duration cannot stack; repeatedly casting will only refresh the duration)"},{"label":"Cooldown","value":"Consume 1 Life Orb"}]'::jsonb, 4),
  (36718, 'mantis', null, null, 'Healing Flower', 'Ability', 'Consume Life Orbs to grant allies Healing Over Time', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Targeted"},{"label":"Special Effect","value":"Healing Flower provides two types of healing effects: One-time Healing and Healing Over Time"},{"label":"One-Time Healing Amount","value":"60"},{"label":"Healing Over Time Amount","value":"12 + 3% of the target''s maximum Health per second"},{"label":"Duration","value":"8s (16s maximum duration)"},{"label":"Cooldown","value":"Consume 1 Life Orb"}]'::jsonb, 5),
  (36719, 'mantis', null, null, 'Nature''s Favor', 'Passive', 'Receive a Movement Boost when not injured and Healing Over Time when consuming Life Orbs', '[{"label":"Key","value":"Passive"},{"label":"Time Required To Leave Combat","value":"3s"},{"label":"Out-Of-Combat Movement Speed","value":"7.5m/s"},{"label":"Special Effect","value":"Consume Life Orbs to receive Healing Over Time"},{"label":"Healing Amount","value":"12.5 per second"},{"label":"Duration","value":"8s"}]'::jsonb, 6),
  (36720, 'mantis', null, null, 'Heavenly Guardian', 'Team-Up Ability', 'Mantis enhances Groot''s wooden walls and Loki''s Rune Stones with life energy. Groot can additionally unleash a Flower Wall, which, when in Flora Colossus state, restores health to random nearby allies and grants them Damage Reduction. Loki''s Rune Stones grant allies within Regeneration Domain a Damage Boost', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"10% Healing Boost"}]'::jsonb, 7),
  (36721, 'mantis', null, null, 'STAR BLOSSOM', 'Team-Up Ability', 'Base Effect: Recasting Healing Flower on a teammate with the effect enhances and spreads the healing aura. Enhanced Effect: When teaming up with Star-Lord, using Healing Flower on any teammate instantly triggers the enhanced Spell Field and healing effect.', '[{"label":"Key","value":"Right Click"},{"label":"Healing Flower Healing Amount","value":"10+Target''s 3% Maximum Health/s"},{"label":"Spread Spell Field Range","value":"8m radius"},{"label":"Spread Healing","value":"7.5+Targe''s 1.75% Maximum Health/s"},{"label":"Enhanced Heal Bonus Healing","value":"10+Target''s 3.5% Maximum Health/s"},{"label":"Spread Spell Field One-Time Healing","value":"10, 15 when enhanced"},{"label":"Special Effect","value":"When Star-Lord is selected as her Team-Up partner, enhance the healing output of Healing Flower from 10 + 2.5% of target''s max Health/s to 15 + 3% of target''s max Health/s"},{"label":"Enhanced Special Effect","value":"Casting Healing Flower on any ally enhances and spreads the healing effect"}]'::jsonb, 8),
  (36722, 'mantis', null, null, 'VITALITY PACT', 'Team-Up Ability', 'Base Effect: Upon defeat, Mantis can freely move as a soul, healing nearby allies, and reforge her body at a chosen spot. After using Natural Anger, the effect of Nature''s Favor is enhanced, increasing the amount of healing provided. Enhanced Effect: When teaming up with Adam Warlock, her soul state can forge Soul Bond with nearby teammates, granting Healing Over Timeand distributing damage taken across the bond.', '[{"label":"Key","value":"Passive"},{"label":"Cooldown","value":"90"},{"label":"Area Of Effect Healing","value":"30/s"},{"label":"Special Effect","value":"When Adam Warlock is selected as her Team-Up partner, the Nature''s Favor passive effect is enhanced. After casting Natural Anger (and ONLY while Natural Anger is active), increase her self-healing from 12.5/s to 17.5/s"},{"label":"Max Damage Shared Per Character","value":"300"},{"label":"Range","value":"15m radius"}]'::jsonb, 9),
  (36723, 'peni-parker', null, null, 'Cyber-Web Cluster', 'Normal Attack', 'Launch forward a Cyber-Web Cluster', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Rapid-fire, delayed projectile that is accompanied by a spell field"},{"label":"Projectile Speed","value":"150m/s"},{"label":"Range","value":"1.5m spherical radius"},{"label":"Fire Rate","value":"4 rounds per second"},{"label":"Damage","value":"Projectile Damage: 15; Spell Field Damage: 15"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36724, 'peni-parker', null, null, 'Spider-Sweeper', 'Ultimate', 'Enhance the SP//dr suit, launching up enemies in its path and deploying Arachno-Mines, Spider-Drones, and Cyber-Webs repeatedly', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Enhancement"},{"label":"Sweep Range","value":"5m"},{"label":"Attack Interval","value":"1s"},{"label":"Spider-Drone Generation Interval","value":"0.5s"},{"label":"Arachno-Mine Attack Interval","value":"0.7s"},{"label":"Maximum Arachno-Mine Quantity","value":"7"},{"label":"Range","value":"4m spherical radius"},{"label":"Duration","value":"12s"},{"label":"Damage","value":"Sweep Attack Damage: 60"},{"label":"Energy Cost","value":"3400"},{"label":"Special Effect","value":"Gain 450 Bonus Health and a 70% Movement Boost"}]'::jsonb, 1),
  (36725, 'peni-parker', null, null, 'Bionic Spider-Nest', 'Ability', 'Generate a Bionic Spider-Nest at a targeted area, periodically spawning Spider-Drones and creating Cyber-Webs. While in the Cyber-Web, Peni and allies gain Healing Over Time and a Movement Boost. Excess healing converts into Bonus Health. Spider-Drones inflict a Slow effect on hit, which can stack and refresh its effect period with multiple hits', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"10m"},{"label":"Spider-Nest Health","value":"350"},{"label":"Range","value":"12m spherical radius"},{"label":"Damage","value":"Each Spider-Drone inflicts 40 damage"},{"label":"Cooldown","value":"15s"},{"label":"Special Effect","value":"Two Spider-Drones are generated every 3s, slows hit enemies by 8% for 2s, each hit stacks the effect and resets the slow period, stacking up to 40%"}]'::jsonb, 2),
  (36726, 'peni-parker', null, null, 'Arachno-Mine', 'Ability', 'Deploy Arachno-Mines that can be concealed within the confines of a Cyber-Web', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Single-cast Spell Field"},{"label":"Range","value":"3m spherical radius"},{"label":"Damage","value":"100"},{"label":"Cooldown","value":"4 charges, with each charge taking 4s to recharge"}]'::jsonb, 3)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36727, 'peni-parker', null, null, 'Cyber-Bond', 'Ability', 'Shoot a web strand that links to the targeted area or Cyber-Web. If stretched too far, it will trigger a pullback', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Dash"},{"label":"Pull-Back Distance","value":"10m"},{"label":"Maximum Cyber-Bond Distance","value":"19m, with the possibility to exceed this distance if descending"},{"label":"Projectile Speed","value":"100m/s"},{"label":"Minimum Dash Distance","value":"10m"},{"label":"Maximum Dash Distance","value":"30m"},{"label":"Cooldown","value":"3s"}]'::jsonb, 4),
  (36728, 'peni-parker', null, null, 'Wall Crawl', 'Ability', 'HOLD Jump to crawl on vertical surfaces', '[{"label":"Key","value":"Space"},{"label":"Wall-Crawling Speed","value":"7.2m/s"}]'::jsonb, 5),
  (36729, 'peni-parker', null, null, 'Cyber-Web Snare', 'Ability', 'Cast futuristic webbing that Immobilizes enemies or creates a Cyber-Web. While in the Cyber-Web, Peni and allies gain Healing Over Time and a Movement Boost. Excess healing converts into Bonus Health', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Range","value":"3m spherical radius"},{"label":"Damage","value":"5"},{"label":"Cooldown","value":"2 charges, with each charge taking 3s to recharge"},{"label":"Slow Rate","value":"30%"},{"label":"Slow Duration","value":"1s"},{"label":"Web-Tracer Duration","value":"5s"},{"label":"Special Effect 1","value":"If an enemy with a Web-Tracer is hit by the snare again, they will be Immobilized for 0.7s"},{"label":"Special Effect 2","value":"While trapped in the Cyber-Web, Peni Parker receives 25 healing per second. Any excess healing is converted into Bonus Health, up to a maximum of 150 Health, and grants a 25% Movement Boost"},{"label":"Special Effect 3","value":"Allies in Peni''s Cyber-Webs now receive the same Healing Over Time and a Movement Boost effects as her. Movement Boost for allies is 25%, Healing is 15/s. Ally excess healing converts into Bonus Health, up to 25"}]'::jsonb, 6),
  (36730, 'peni-parker', null, null, 'ARMORIZED SPIDER-NEST', 'Team-Up Ability', 'Enhanced by Rocket Raccoon, Peni Parker’s Bionic Spider-Nest regularly generates strengthened armor packs. Each armor pack grants bonus health to the hero who picks up the pack. Peni Parker can deploy Bionic Spider-Nest and Armored Spider-Nest at the same time', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"30"},{"label":"Spider-Nest Health","value":"250"},{"label":"Spider-Drone Generate Interval","value":"3s"},{"label":"Spider-Drone Generate Quantity","value":"2"},{"label":"Spider-Drone Explosion Range","value":"1m spherical radius spell field"},{"label":"Spider-Drone Damage","value":"40"},{"label":"Armor Pack Generate Interval","value":"3s"},{"label":"Bonus Health From Armor Pack","value":"50"}]'::jsonb, 7),
  (36731, 'peni-parker', null, null, 'Cyber-Spiders', 'Team-Up Ability', 'Peni Parker whips up a Sticky Bomb for Spider-Man! Prime it, then toss it before the timer''s up for a blast that damages nearby enemies and attaches a Spider-Tracer to them. If not thrown in time, it explodes on Spider-Man, recharging a Web-Cluster shot and granting Bonus Health', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"+50 Max Health"}]'::jsonb, 8),
  (36732, 'peni-parker', null, null, 'VIBRANIUM MECH', 'Team-Up Ability', 'Base Effect: Upon activation, briefly grants Cyber-Web Clusteran Attack Speedand DamageBoost. Enhanced Effect: When teaming up with Black Panther, activating the ability deploys a frontal Vibranium Shield, while reducing the Vibranium Energy cost of Cyber-Web Cluster.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Duration","value":"5s"},{"label":"Barrier Health","value":"300"},{"label":"Attack Interval","value":"0.18s per shot"},{"label":"Enhanced Barrier Health","value":"400"}]'::jsonb, 9),
  (36733, 'peni-parker', null, null, 'ROCKET NETWORK', 'Team-Up Ability', 'Base Effect: Deploy an Armored Spider-Nestthat periodically drops Spider-Dronesand Armor Packsthat grant Bonus Health. Enhanced Effect: When teaming up with Rocket Raccoon, the Armored Spider-Nestpassively regenerates its own Health. Furthermore, Rocket''s B.R.B.will generate Cyber-Webs, and spawn both Spider-Dronesand Arachno-Mines.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"25s"},{"label":"Spider-Nest Health","value":"250"},{"label":"Armor Pack Generate Interval","value":"3s"},{"label":"Bonus Health From Armor Pack","value":"50"},{"label":"Spider-Drone Self Healing","value":"25"},{"label":"Spider-Drone Damage","value":"40"},{"label":"Spider-Drone Generate Interval","value":"8s"}]'::jsonb, 10),
  (36734, 'thor', null, null, 'Mjolnir Bash', 'Normal Attack', 'Wield Mjolnir to strike enemies. When Awakened, Thor can launch lightning arc waves to deal damage', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast Spell Field"},{"label":"Range","value":"4m"},{"label":"Attack Interval","value":"0.6s"},{"label":"Damage","value":"45"}]'::jsonb, 0),
  (36735, 'thor', null, null, 'God of Thunder', 'Ultimate', 'Soar upwards and smite the ground after charging for a duration, inflicting damage on enemies within range', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"A persistent spell field that generates a one-time spell field upon expiration"},{"label":"Range","value":"The sustained spell field is cylindrical, measuring 8m in radius and 20m in height, whereas the one-time spell field has an 8m spherical radius"},{"label":"Height","value":"9m"},{"label":"Duration","value":"1.5s"},{"label":"Damage","value":"The sustained spell field lasts for 0.5s, dealing 40 damage, while the one-time spell field deals 220 damage"},{"label":"Special Effect","value":"After Ultimate Ability lands, Stun surrounding enemies for 1s"},{"label":"Energy Cost","value":"3100"}]'::jsonb, 1),
  (36736, 'thor', null, null, 'Storm Surge', 'Ability', 'Hold to spin Mjolnir before dashing forward and knocking back enemies', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Charged Dash"},{"label":"Maximum Charge Time","value":"2s"},{"label":"Dash Distance","value":"No charge: 10m; Full charge: 20m. When carrying an enemy, the ranges are 6m with no charge and 13m with full"},{"label":"Damage","value":"No Charge Damage: 40; Full Charge Damage: 60"},{"label":"Thorforce Cost","value":"1"}]'::jsonb, 2),
  (36737, 'thor', null, null, 'Lightning Realm', 'Ability', 'Summon lightning that restores Thorforce based on the number of hit enemies', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Persistent Spell Field"},{"label":"Range","value":"5m spherical radius"},{"label":"Maximum Duration","value":"4s"},{"label":"Damage","value":"Deal 40 damage when enemies cross the boundaries"},{"label":"Cooldown","value":"12s"},{"label":"Special Effect","value":"For each enemy within the spell area, 1 point of Thorforce is restored. Enemies that cross the boundary will be Slowed by 30%, Enemies that cross the boundary will receive an additional debuff that restricts aerial abilities for 2s."}]'::jsonb, 3),
  (36738, 'thor', null, null, 'Awakening Rune', 'Ability', 'Consume Thorforce to enter the Awakened state, granting Bonus Health and enhancing Mjolnir Bash', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Ability Enhancement"},{"label":"Key (Enhanced)","value":"Left Click"},{"label":"Projectile Speed","value":"60 m/s"},{"label":"Attack Interval","value":"The first three stages last for 0.4s each, while the fourth stage lasts for 0.8s"},{"label":"Range","value":"3m spherical radius"},{"label":"Duration","value":"5s"},{"label":"Damage","value":"Projectile Damage: 70, Spell Field Damage: 15 per second"},{"label":"Max Shield Duration","value":"2.5s"},{"label":"Thorforce Cost","value":"3"},{"label":"Special Effect","value":"Inflict damage over time on nearby enemies; After casting Awakening Rune, you can manually cancel the Awakened state after a brief delay. At the end of the Awakened state, Thor restores 1 point of Thunderforce."}]'::jsonb, 4),
  (36739, 'thor', null, null, 'Hammer Throw', 'Ability', 'Throw Mjolnir forward which then returns', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Launch a single-target projectile that returns after a delayed hit"},{"label":"Projectile Speed","value":"The projectile travels outward at a speed of 60m per second and returns at a speed of 80m per second"},{"label":"Maximum Distance","value":"24m"},{"label":"Damage","value":"Outward Projectile Damage: 50; Returning Projectile Damage: 25"},{"label":"Cooldown","value":"6s"},{"label":"Critical Hit","value":"No"},{"label":"Special Effect","value":"Hits grant 75 Bonus Health (only triggers once per throw, even if hitting multiple enemies)"}]'::jsonb, 5),
  (36740, 'thor', null, null, 'Thorforce', 'Passive', 'Consume Thorforce to gain Bonus Health. Landing Mjolnir Bash on an enemy instantly recharges Thorforce', '[{"label":"Key","value":"Passive"},{"label":"Maximum Thorforce","value":"3"},{"label":"Thorforce Recovery Speed","value":"5s per Thorforce"},{"label":"Bonus Health Per Thorforce","value":"Each point of Thorforce consumed grants 50 Bonus Health, while abilities that consume 3 points of Thorforce grant 150 Bonus Health"},{"label":"Bonus Max Health","value":"150"},{"label":"Mjolnir Bash Energy Recovery Per Thorforce","value":"5s"},{"label":"Thorforce Consumption Cooldown","value":"1.5s"}]'::jsonb, 6),
  (36741, 'thor', null, null, 'THUNDERSTRIKE PIKE', 'Team-Up Ability', 'Angela shares fragments of her Ichors with Thor, empowering him to hurl a Thunder Spear that restores Thorforce for each enemy struck. Afterward, Thor can leap to the spear''s explosion point, dealing a second wave of damage to all enemies within range', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"30s"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Projectile Damage","value":"25"},{"label":"Projectile-Generated Spell Field Range","value":"5m"},{"label":"Projectile-Generated Spell Field Damage","value":"30"},{"label":"Hit Ground Spell Field Range","value":"5m"},{"label":"Hit Ground Spell Field Damage","value":"45"},{"label":"Hit Ground Maximum Distance","value":"30m"}]'::jsonb, 7),
  (36742, 'thor', null, null, 'RAGNAROK REBIRTH', 'Team-Up Ability', 'Base Effect: Receiving fatal damage prevents immediate defeat, Thor gains a decaying pool of Bonus Health. If he participates in a KO during this time, he resurrects and recovers a small amount of Health. Enhanced Effect: When teaming up with Hela, if either of them participates in a KO, Thor instantly revives, restoring Health equal to his remaining Bonus Health and gaining a Continuous Healing effect.', '[{"label":"Key","value":"Passive"},{"label":"Cooldown","value":"50s"},{"label":"Cooldown On Failed Resurrection","value":"30s"},{"label":"Minimum Health Gained On Successful Resurrection","value":"300"},{"label":"Bonus Health","value":"600"},{"label":"Damage Reduction While Active","value":"40%"},{"label":"Healing Over Time","value":"50/s for 3s"}]'::jsonb, 8),
  (36743, 'thor', null, null, 'DIVINE ARMORY', 'Team-Up Ability', 'Base Effect: Hurl a Thunder Spear that restores Thorforce for each enemy struck. Afterward, Thor canleap to the spear''s explosion point, dealing a second wave of damage to all enemies within range. Enhanced Effect: When teaming up with Angela, leaping to the Thunder Spear grants Bonus Health.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Thunder Spear Spell Field Damage","value":"30"},{"label":"Thunder Spear Spell Field Range","value":"5m spherical radius"},{"label":"Ground Slam Damage","value":"45"},{"label":"Ground Slam Damage Range","value":"5m spherical radius"},{"label":"Bonus Health","value":"100"}]'::jsonb, 9),
  (36744, 'magneto', null, null, 'Iron Volley', 'Normal Attack', 'Fire a volley of magnetic orbs forward. The range of the resulting explosion increases based on distance flown', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact that also generates a spell field"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Charges","value":"10"},{"label":"Maximum Distance","value":"25m"},{"label":"Range","value":"Initially, it produces a spell field with a 1m spherical radius; when the projectile reaches maximum distance, the explosion radius expands to a spell field with a 3m spherical radius"},{"label":"Attack Interval","value":"0.8s"},{"label":"Damage","value":"Projectile Damage: 40. The spell field deals 40 damage at its center, reducing to 50% within a 3m radius from the center"}]'::jsonb, 0),
  (36745, 'magneto', null, null, 'Meteor M', 'Ultimate', 'Draw in all materials around to forge an iron meteor that deals massive damage upon impact. Absorbing enemy projectiles can enhance the meteor''s power, yet overloading will cause it to self-destruct', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Create a persistent spell field that launches a projectile upon completion, which generates another spell field on impact"},{"label":"Projectile Absorption Range","value":"15m spherical radius"},{"label":"Projectile Speed","value":"45m/s"},{"label":"Explosion Range","value":"Initially, the ability has a spherical range with a radius of 5m. After charging for 4s, it expands to an 8m radius"},{"label":"Maximum Duration","value":"5s"},{"label":"Damage","value":"The projectile deals no damage. The base damage at the center of the spell field starts at 100 and increases to 350 when fully charged. Each point of Energy adds an extra 3 points of damage to the spell field, with damage reducing to 50% at a distance of 6m from the center"},{"label":"Energy Cost","value":"3400"},{"label":"Special Effect","value":"For each point of projectile damage absorbed, the power increases by 0.125, with a maximum absorption of 800 projectile damage"}]'::jsonb, 1),
  (36746, 'magneto', null, null, 'Metallic Curtain', 'Ability', 'Change the magnetic field around to form a metallic curtain, blocking all incoming projectiles', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Shield"},{"label":"Maximum Energy","value":"100"},{"label":"Energy Cost","value":"65/s"},{"label":"Energy Recovery Delay","value":"1s"},{"label":"Energy Recovery Speed","value":"11/s"},{"label":"Cooldown","value":"3s"}]'::jsonb, 2),
  (36747, 'magneto', null, null, 'Metal Bulwark', 'Ability', 'Conjure a metal shield around a chosen ally. Damage taken will transform into rings on Magneto''s back', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"20m"},{"label":"Shield Value","value":"200"},{"label":"Max Shield Duration","value":"2.5s"},{"label":"Cooldown","value":"15s"},{"label":"Special Effect","value":"The shield grants one charge of Iron Ring for every 100 damage it absorbs"}]'::jsonb, 3),
  (36748, 'magneto', null, null, 'Iron Bulwark', 'Ability', 'Conjure an iron shield around himself. Damage taken will transform into rings on Magneto''s back', '[{"label":"Key","value":"F"},{"label":"Shield Value","value":"200"},{"label":"Max Shield Duration","value":"2.5s"},{"label":"Cooldown","value":"10s"},{"label":"Special Effect","value":"The shield grants one charge of Iron Ring for every 100 damage it absorbs"}]'::jsonb, 4),
  (36749, 'magneto', null, null, 'Mag-Cannon', 'Ability', 'Convert the iron rings on Magneto''s back into a Mag-Cannon and launch a metallic mass forward. Higher stacks of rings increase damage, and full stacks knock back enemies', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact"},{"label":"Projectile Speed","value":"120m/s"},{"label":"Damage","value":"Iron Rings'' first charge deals 40 damage, the second charge deals 65 damage, and the third charge deals 90 damage"},{"label":"Cooldown","value":"No cooldown, but the ability can only be activated when the Iron Ring has at least one charge"},{"label":"Critical Hit","value":"No"},{"label":"Special Effect","value":"When fully charged, the Iron Ring has a 6m knockback distance"}]'::jsonb, 5),
  (36750, 'magneto', null, null, 'Magnetic Descent', 'Ability', 'Hold Space to fall slowly', '[{"label":"Key","value":"Space"},{"label":"Horizontal Movement Speed","value":"6m/s"},{"label":"Descending Speed","value":"3.5m/s"}]'::jsonb, 6),
  (36751, 'magneto', null, null, 'ROYAL BLADE', 'Team-Up Ability', 'Gambit charges Magneto''s greatsword with kinetic energy. When Magneto activates this ability, Iron Volley is replaced with Ace Greatsword, which detonates upon striking enemies. The explosion leaves residual kinetic energy within the target, inflicting secondary damage after a brief delay', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"30s"},{"label":"Duration","value":"10s"},{"label":"Shoot Interval","value":"First hit 0.6s, second hit 1s"},{"label":"Projectile Speed","value":"80m/s"},{"label":"Projectile Damage","value":"40"},{"label":"Spell Field Range","value":"3m spherical radius spell field"},{"label":"Spell Field Damage","value":"30"},{"label":"Explosion Delay","value":"0.5s"},{"label":"Delay Explosion Damage","value":"25"}]'::jsonb, 7)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36752, 'magneto', null, null, 'METALLIC CHAOS', 'Team-Up Ability', 'Base Effect: Summons a Chaos Greatsword that deals damage to enemies in front. Enhanced Effect: When teaming up with Scarlet Witch, Magnetic Cannon becomes a charged ability. Charging consumes passive energy, and each energy segment consumed fires a Chaos Greatsword that deals damage to enemies.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"18s"},{"label":"Ability Duration","value":"8s"},{"label":"Projectile Hit Damage","value":"45"},{"label":"Spell Field Explosion Damage","value":"35"},{"label":"Projectile Damage Falloff","value":"Falloff starts at 20m, down to 70% at 30m"},{"label":"Spell Field Damage Falloff","value":"Falloff starts at 0m, down to 70% at 3m"},{"label":"Projectile Speed","value":"120m/s"},{"label":"Charge Interval","value":"0.33s per use"},{"label":"Enhanced Projectile Hit Damage","value":"10"},{"label":"Enhanced Spell Field Explosion Damage","value":"25"}]'::jsonb, 8),
  (36753, 'magneto', null, null, 'MAGNETIC RESONANCE', 'Team-Up Ability', 'Base Effect: Cast a magnetic projection that mimics Magneto''s movement and ability casts perfectly from the enemy''s perspective. Enhanced Effect: When teaming up with Emma Frost, the magnetic projection receives a massive Health bump and will persist indefinitely unless destroyed or manually recalled.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Magnetic Projection Max Damage Absorbed","value":"300"},{"label":"Magnetic Projection Damage Dealt Ratio","value":"50%"},{"label":"Magnetic Projection Max Duration","value":"6s"},{"label":"Magnetic Projection Max Damage Absorbed Increase","value":"150"}]'::jsonb, 9),
  (36754, 'venom', null, null, 'Dark Predation', 'Normal Attack', 'Unleash tentacles forward to attack enemies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Quad-cast delayed spell field"},{"label":"Range","value":"15m"},{"label":"Attack Interval","value":"0.9s, with a 0.1s interval between each tendril"},{"label":"Damage","value":"20"},{"label":"Critical Hit","value":"Yes"}]'::jsonb, 0),
  (36755, 'venom', null, null, 'Feast of the Abyss', 'Ultimate', 'Burrow underground for free movement. After a duration or by left-clicking, devour enemies above to deal damage based on the enemy''s current health and generate equivalent Bonus Health. Devoured enemies suffer Reduced Healing', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Single-cast spell field that surrounds the caster"},{"label":"Movement Boost","value":"80%"},{"label":"Range","value":"7m spherical radius"},{"label":"Maximum Duration","value":"4s"},{"label":"Damage","value":"Inflict damage equal to 50% of the target''s health, followed by an additional 50 damage"},{"label":"Energy Cost","value":"2500"},{"label":"Special Effect","value":"130% of damage dealt is converted into Bonus Health"},{"label":"Healing Reduction Proportion","value":"30%"},{"label":"Healing Reduction Duration","value":"4s"}]'::jsonb, 1),
  (36756, 'venom', null, null, 'Venom Swing', 'Ability', 'Launch webbing forward, allowing for a singular swing in the desired direction', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Dash"},{"label":"Maximum Webbing Length","value":"30m"},{"label":"Cooldown","value":"10s"}]'::jsonb, 2),
  (36757, 'venom', null, null, 'Symbiotic Resilience', 'Ability', 'Generate Bonus Health against damage. The lower Venom''s Health, the greater the Bonus Health generated', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Instant Cast"},{"label":"Cooldown","value":"15s"},{"label":"Special Effect","value":"Grant 100 Bonus Health and convert 110% of lost Health into Bonus Health"}]'::jsonb, 3),
  (36758, 'venom', null, null, 'Frenzied Arrival', 'Ability', 'Dash to the target location from a certain height. Upon landing, damage nearby enemies, launching them up toward the landing point', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"40m"},{"label":"Minimum Distance","value":"3m"},{"label":"Range","value":"6m spherical radius"},{"label":"Damage","value":"65 damage, with damage falloff starting at 2m from the center of the spell field and decreasing to 40% at 6m"},{"label":"Cooldown","value":"8s"},{"label":"Special Effect","value":"Knocks enemies inward, with an inward knockback angle of 75°"}]'::jsonb, 4),
  (36759, 'venom', null, null, 'Cellular Corrosion', 'Ability', 'Unleash tentacles to Slow enemies within reach. Enemies unable to break free in time will suffer damage', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Spell field that surrounds the caster"},{"label":"Range","value":"8m spherical radius"},{"label":"Damage","value":"The spell field deals 5 damage, increasing to 80 damage if the target remains in the area for a duration"},{"label":"Cooldown","value":"8s"},{"label":"Special Effect","value":"Tendrils apply a 25% Slow on the target and take 3s to inflict damage. If the distance from Venom exceeds 11m, the tendrils will detach"}]'::jsonb, 5),
  (36760, 'venom', null, null, 'Alien Biology', 'Ability', 'Press Space to wall crawl, and while crawling, left-click to sprint', '[{"label":"Key","value":"Space"},{"label":"Wall-Crawling Speed","value":"3 m/s"},{"label":"Sprinting Speed","value":"9 m/s"}]'::jsonb, 6),
  (36761, 'venom', null, null, 'HEALING TENDRILS', 'Team-Up Ability', 'Venom shares his symbiotes with Jeff and Hela. Jeff''s Guardian of the Deep links with nearby allies, providing continuous healing. When the effect ends, it releases a powerful healing burst, converting any excess into Bonus Health. Hela''s Hel Tendrils unleash a symbiotic Hel Sphere. Upon hit, it pulls nearby enemies toward the impact point and links them, slowing enemies that try to escape.', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"+150 Max Health"}]'::jsonb, 7),
  (36762, 'venom', null, null, 'BLOOD LEECH', 'Team-Up Ability', 'Base Effect: Cellular Corrosion new effect: while tethered to enemies, continuously siphon health from every linked target, restoring Venom''s Health. Enhanced Effect: When teaming up with Blade, Venom gains a burst of one-time healing when using certain specific abilities.', '[{"label":"Key","value":"Right Click"},{"label":"Damage Over Time","value":"2/hit, 10 times per second"},{"label":"Damage Over Time To Healing Conversion Rate","value":"100%"},{"label":"Tentacle Explosion Damage To Healing Conversion Rate","value":"50%"},{"label":"Enhanced Key","value":"Passive"},{"label":"One-Time Healing Amount","value":"40"}]'::jsonb, 8),
  (36763, 'venom', null, null, 'ABYSSAL FLAMES', 'Team-Up Ability', 'Base Effect: Ignites the symbiote with Phoenix Flames for a duration, replacing Dark Predation with a sweeping Phoenix Touch frontal slash. Enhanced Effect: When teaming up with Phoenix, Venom''s Phoenix Force is enhanced: every Phoenix Touch applies Sparks. Upon reaching three stacks, the Sparks detonate.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Duration","value":"8s"},{"label":"Attack Range","value":"10m"},{"label":"Damage","value":"55"},{"label":"Attack Interval","value":"0.8s"},{"label":"Explosion Range","value":"3m spherical radius"},{"label":"Explosion Damage","value":"20"}]'::jsonb, 9),
  (36764, 'groot', null, null, 'Vine Strike', 'Normal Attack', 'Launch vines to attack enemies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Single-cast projectile with delayed impact"},{"label":"Projectile Speed","value":"120m/s"},{"label":"Maximum Distance","value":"22m"},{"label":"Attack Interval","value":"0.7s"},{"label":"Damage","value":"65"},{"label":"Critical Hit","value":"No"}]'::jsonb, 0),
  (36765, 'groot', null, null, 'Strangling Prison', 'Ultimate', 'Fire a massive vine cluster that pulls nearby enemies to its center and Imprisons them', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Single-cast projectile with a downward delay that creates a spell field upon impact"},{"label":"Projectile Speed","value":"60m/s"},{"label":"Range","value":"8m spherical radius"},{"label":"Damage","value":"The projectile deals 10 damage, while the spell field deals 70 damage. While imprisoning enemies, it deals 20 damage every 0.5s"},{"label":"Energy Cost","value":"2800"},{"label":"Special Effect","value":"Imprison enemies for 3.5s"}]'::jsonb, 1),
  (36766, 'groot', null, null, 'Thornlash Wall', 'Ability', 'Target a location and grow a Thornlash Wall. When Awakened, it strikes nearby enemies attacked by Groot and his allies', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"18m"},{"label":"Thornlash Wall Health","value":"250"},{"label":"Cooldown","value":"2 charges, with each charge taking 6s to recharge"},{"label":"Special Effect","value":"Thornlash Wall deals 60 damage every 0.5s"}]'::jsonb, 2),
  (36767, 'groot', null, null, 'Ironwood Wall', 'Ability', 'Target a location and grow an Ironwood Wall. When the wall is Awakened, damage dealt by Groot and nearby allies grants Groot Bonus Health. Groot gains Unstoppable while near Ironwood Walls', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"10m"},{"label":"Thornlash Wall Health","value":"600"},{"label":"Cooldown","value":"12s"},{"label":"Special Effect","value":"Ironwood Wall heals 50 Bonus Health per second, up to 250 Bonus Health; gain Unstoppable status when within 15m of Awakened Ironwood Walls"}]'::jsonb, 3),
  (36768, 'groot', null, null, 'Spore Bomb', 'Ability', 'Throw an explosive Spore Bomb that splits into multiple small explosive spores', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Single-cast projectile with a downward delay that creates a spell field upon impact"},{"label":"Projectile Speed","value":"60m/s"},{"label":"Range","value":"Spore Bomb generates a spell field with a 5m spherical radius, while small explosive spores create a spell field with a 1.5m spherical radius"},{"label":"Damage","value":"The projectile itself deals no damage, while Spore Bomb deals 55 damage and explosive spores deal 10 damage"},{"label":"Cooldown","value":"6s"},{"label":"Special Effect","value":"Spore Bomb explodes into 6 explosive spores"}]'::jsonb, 4),
  (36769, 'groot', null, null, 'Flora Colossus', 'Passive', 'Wooden walls near Groot will Awaken, activating an extra effect. Right-click while building a wooden wall to continue building additional walls', '[{"label":"Key","value":"Passive"},{"label":"Casting","value":"Persistent spell field that surrounds the caster"},{"label":"Range","value":"A cylindrical spell field with a 24m radius and a height of 40m"}]'::jsonb, 5),
  (36770, 'groot', null, null, 'Furious Flora', 'Ability', 'Perform a combo with his arms, and the third strike will slightly Launch Up the hit enemy airborne', '[{"label":"Key","value":"V"},{"label":"Range","value":"The first two strikes can reach 3m, while the third strike can reach 4m"}]'::jsonb, 6),
  (36771, 'groot', null, null, 'Wild Wall', 'Team-Up Ability', 'Mantis enhances Groot''s wooden walls and Loki''s Rune Stones with life energy. Groot can additionally unleash a Flower Wall, which, when in Flora Colossus state, restores health to random nearby allies and grants them Damage Reduction. Loki''s Rune Stones grant allies within Regeneration Domain a Damage Boost', '[{"label":"Key","value":"C"},{"label":"Casting","value":"Targeted"},{"label":"Cooldown","value":"10s"},{"label":"Flower Wall Health","value":"150"},{"label":"Range","value":"10m spherical radius spell field"},{"label":"Maximum Unleash Distance","value":"7m"},{"label":"Healing Amount","value":"40/s"}]'::jsonb, 7),
  (36772, 'groot', null, null, 'WILD WALL', 'Team-Up Ability', 'Base Effect: Summon a Wild Wall that provides Continuous Healing and Bonus Health to allies within its range. Enhanced Effect: When teaming up with Mantis, the Wild Wall evolves after providing a certain amount of healing, increasing its healing', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"10s"},{"label":"Wild Wall Range","value":"15m radius"},{"label":"Buff Frequency","value":"Once per second"},{"label":"Buff Duration Per Application","value":"6s"},{"label":"Healing Amount","value":"20/s"},{"label":"Bonus Health","value":"10/hit"},{"label":"Wild Wall Health","value":"200"},{"label":"Healing Required To Enhance","value":"200"},{"label":"Enhanced Healing","value":"35/s"},{"label":"Health Increase Per Upgrade","value":"50"}]'::jsonb, 8),
  (36773, 'groot', null, null, 'BUBBLE BUDDIES', 'Team-Up Ability', 'Base Effect: Retreat inside a Bubble Shield to enter an Invincible state, granting self-targeted Continuous Healing. Enhanced Effect: When teaming up with Jeff the Land Shark, the healing effect inside the bubble is enhanced, and any excess healing converts into Bonus Health.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"20s"},{"label":"Shield Value","value":"400"},{"label":"Maximum Duration","value":"4s"},{"label":"Healing Amount","value":"40/s"},{"label":"Enhanced Key","value":"X"},{"label":"Increase Healing Amount","value":"40/s"},{"label":"Overhealing To Bonus Health Conversion Rate","value":"50%"}]'::jsonb, 9),
  (36774, 'captain-america', null, null, 'Sentinel Strike', 'Normal Attack', 'Get up close to strike enemies. Landing the second hit enables a shield throw that can ricochet four times', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Change Form"},{"label":"Melee Range","value":"4m"},{"label":"Shield Flying Speed","value":"60m/s"},{"label":"Max Flying Distance","value":"25m"},{"label":"Damage","value":"Melee Attack Damage: 45, Flying Shield Damage: 45"},{"label":"Attack Interval","value":"Melee 1st Hit: 0.4s, Melee 2nd Hit: 0.5s, Flying Shield 1st Hit: 0.5s, Flying Shield 2nd Hit: 0.57s"},{"label":"Ammo","value":"Up to 4 throws"},{"label":"Critical Hit","value":"No"},{"label":"Special Effect","value":"Automatically target enemies near the crosshair"}]'::jsonb, 0),
  (36775, 'captain-america', null, null, 'Freedom Charge', 'Ultimate', 'Shield held high, carve a path forward, granting both himself and allies along the path continuous Bonus Health and Movement Boosts. Allies also gain Ultimate Ability Charge Acceleration. Using Living Legend and Leading Dash while this ability is active can Launch Up enemies', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Activation"},{"label":"Range","value":"A spherical spell field with a 4m radius enveloping the caster, and a spell area with a width of 4m along the path"},{"label":"Spell Field Duration","value":"10s"},{"label":"Spell Area Duration","value":"5s"},{"label":"Health Recovery Rate","value":"Cast to gain 150 Bonus Health and grant allies 100 Bonus Health. Every second afterward, gain 100 Bonus Health and grant allies 60 Bonus Health"},{"label":"Movement Boost","value":"Grant a 30% Movement Boost to both yourself and your allies"},{"label":"Energy Cost","value":"3100"},{"label":"Special Effect","value":"Allies within its path gain a 20% boost to Ultimate Energy charge efficiency"}]'::jsonb, 1),
  (36776, 'captain-america', null, null, 'Leading Dash', 'Ability', 'Boost speed and enable Fearless Leap to leap into the air', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Channeled"},{"label":"Movement Boost","value":"33.40%"},{"label":"Fearless Leap Height","value":"5m"}]'::jsonb, 2)
on conflict do nothing;

insert into public.hero_abilities (id, hero_id, kit_role, kit_label, name, ability_type, description, technical_details, sort_order) values
  (36777, 'captain-america', null, null, 'Vibranium Energy Saw', 'Ability', 'Hurl the energy-charged shield to strike enemies in a path', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Single-cast projectile that can ricochet"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Maximum Distance","value":"25m"},{"label":"Number Of Ricochets","value":"3"},{"label":"Damage","value":"70,"},{"label":"Cooldown","value":"6s"}]'::jsonb, 3),
  (36778, 'captain-america', null, null, 'Liberty Rush', 'Ability', 'Raise the shield and charge forward', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Single-cast forward dash"},{"label":"Dash Distance","value":"12m"},{"label":"Damage","value":"30"},{"label":"Cooldown","value":"10s"}]'::jsonb, 4),
  (36779, 'captain-america', null, null, 'Super-Soldier Slam', 'Ability', 'Slam down from the sky onto the targeted area, Launching Up enemies', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Targeted"},{"label":"Maximum Distance","value":"20m (horizontal)"},{"label":"Damage","value":"30"},{"label":"Cooldown","value":"12s"}]'::jsonb, 5),
  (36780, 'captain-america', null, null, 'Living Legend', 'Ability', 'Raise the shield to deflect incoming projectiles, sending them ricocheting in random directions', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Channeled"},{"label":"Maximum Shield Value","value":"350"},{"label":"Recovery Shield Value","value":"50/s"},{"label":"Delayed Recovery After Release","value":"4s"},{"label":"Cooldown After Destroyed","value":"5s"},{"label":"Cooldown","value":"1s"},{"label":"Ricochet Damage Falloff","value":"50%"}]'::jsonb, 6),
  (36781, 'captain-america', null, null, 'Captain''s Spirit', 'Team-Up Ability', 'Inspired by Captain America''s resolve, Winter Soldier can leap to the aid of a designated ally, slamming the ground with his mechanical arm to deal damage to nearby foes. Additionally, Captain America and Winter Soldier can interact with each other once both parties confirm. The duo collides and unleashes a shockwave that deals damage and inflicts slow on enemies', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"Captain America gain 100 Max Health"}]'::jsonb, 7),
  (36782, 'captain-america', null, null, 'VIBRANIUM BASTION', 'Team-Up Ability', 'Black Cat shares her luck with her allies. When White Fox embraces her newfound fortune, she unleashestracking Spirit Tails to grant Healing and Speed to allies, while damaging and Slowing foes. When Captain America enjoys his luck, his shield''s block radius expands and allows him to aim deflectedProjectiles directly toward his target', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Ability Duration","value":"10s"},{"label":"Summon Radius Increase","value":"1m"},{"label":"Special Effect","value":"Within the duration, deflect Projectiles ricochet directly toward his target direction."}]'::jsonb, 8),
  (36783, 'captain-america', null, null, 'STARS ALIGNED', 'Team-Up Ability', 'Base Effect: Captain America can leap directly to a teammate, providing Bonus Health to both himself and the ally, while redirecting a portion of their incoming damage to himself. Enhanced Effect: When teaming up with Winter Soldier, the duo can trigger a mutual rally. Upon confirmation, they charge at one another, slamming together to grant Bonus Health and Movement Speed to all nearby friends. The original effect remains, now additionally granting a Speed Boost to the targeted teammate.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"12s"},{"label":"Bonus Health","value":"150"},{"label":"Damage Sharing Duration","value":"2s"},{"label":"Movement Boost","value":"1.5 m/s"}]'::jsonb, 9),
  (36784, 'captain-america', null, null, 'VOLTAIC UNION', 'Team-Up Ability', 'Base Effect: Modifies Sentinel Strike into a Lightning Shield projectile. After landing two hits, Captain America launches the piercing Lightning Shield four times. Enhanced Effect: When teaming up with Thor, the lightning energy imbued in the shield intensifies. Each hit from the Lightning Shield triggers an extra burst of damage in the surrounding area.', '[{"label":"Key","value":"C"},{"label":"Cooldown","value":"15s"},{"label":"Ability Duration","value":"10s"},{"label":"Thunderous Shield Damage","value":"45"},{"label":"Aoe Damage","value":"5"},{"label":"Damage Range","value":"3m spherical radius"}]'::jsonb, 10),
  (36785, 'doctor-strange', null, null, 'Daggers of Denak', 'Normal Attack', 'Cast Daggers of Denak forward', '[{"label":"Key","value":"Left Click"},{"label":"Casting","value":"Five-round delayed hit projectiles"},{"label":"Projectile Speed","value":"80 m/s"},{"label":"Damage","value":"18"},{"label":"Damage Falloff","value":"Falloff begins at 10m, decreasing to 80% at 20m"},{"label":"Fire Rate","value":"6.25 rounds per second, with a 0.03-second interval between every two rounds"},{"label":"Ammo","value":"12 (1 dagger per release)"},{"label":"Critical Hit","value":"No"}]'::jsonb, 0),
  (36786, 'doctor-strange', null, null, 'Eye of Agamotto', 'Ultimate', 'Separate nearby enemies'' Souls from their bodies. Damage dealt to these Souls is transferred to their physical bodies', '[{"label":"Key","value":"Q"},{"label":"Casting","value":"Single-cast spell field that surrounds the caster"},{"label":"Range","value":"10m spherical radius"},{"label":"Damage","value":"60"},{"label":"Soul Separation Duration","value":"3s"},{"label":"Energy Cost","value":"3100"}]'::jsonb, 1),
  (36787, 'doctor-strange', null, null, 'Cloak of Levitation', 'Ability', 'Ascend and then enter a brief state of sustained flight', '[{"label":"Key","value":"SHIFT"},{"label":"Casting","value":"Instant Cast"},{"label":"Dash Distance","value":"8m"},{"label":"Free-Flight Duration","value":"6s"},{"label":"Cooldown","value":"12s"}]'::jsonb, 2),
  (36788, 'doctor-strange', null, null, 'Maelstrom of Madness', 'Ability', 'Release Dark Magic to deal damage to nearby enemies', '[{"label":"Key","value":"E"},{"label":"Casting","value":"Single-cast spell field that surrounds the caster"},{"label":"Range","value":"8m spherical radius"},{"label":"Damage","value":"Each point of Dark Magic deals 1.3 damage"},{"label":"Cooldown","value":"6s"}]'::jsonb, 3),
  (36789, 'doctor-strange', null, null, 'Pentagram of Farallah', 'Ability', 'Open portals between two locations, enabling all units to travel through them', '[{"label":"Key","value":"F"},{"label":"Casting","value":"Multi-segment release"},{"label":"Duration","value":"20s"},{"label":"Cooldown","value":"180s"}]'::jsonb, 4),
  (36790, 'doctor-strange', null, null, 'Shield of the Seraphim', 'Ability', 'Create a protective barrier against damage', '[{"label":"Key","value":"Right Click"},{"label":"Casting","value":"Channeled"},{"label":"Maximum Shield Value","value":"850"},{"label":"Recovery Speed","value":"60/s"},{"label":"Delayed Recovery After Release","value":"1s"},{"label":"Cooldown After Destroyed","value":"3s"}]'::jsonb, 5),
  (36791, 'doctor-strange', null, null, 'Price of Magic', 'Passive', 'Dark Magic accumulates with every hit on an enemy. If Dark Magic peaks for too long, Doctor Strange will be cursed with Anti-Heal', '[{"label":"Key","value":"Passive"},{"label":"Anti-Heal Activation Delay At Peak Dark Magic","value":"3s"},{"label":"Anti-Heal Duration","value":"2s"},{"label":"Generate Dark Magic","value":"Daggers of Denak: Each hit generates 3.5 Dark Magic. When using the V key, every enemy hit generates 10 Dark Magic"}]'::jsonb, 6),
  (36792, 'doctor-strange', null, null, 'Enchanted Enhancement', 'Team-Up Ability', 'Doctor Strange shares his arcane mastery, replacing Scarlet Witch''s Chthonian Burst with Mystic Burst upon activation. Hold down the attack button to unleash a rapid, relentless salvo of magical missiles in the target direction', '[{"label":"Key","value":"Passive"},{"label":"Team-Up Bonus","value":"Doctor Strange gain 100 Max Health"}]'::jsonb, 7),
  (36793, 'doctor-strange', null, null, 'PSIONIC VORTEX', 'Team-Up Ability', 'Invisible Woman enhances Doctor Strange''s Maelstrom of Madness with a psionic explosion. The explosion damages and pulls enemies toward Doctor Strange. Based on the explosion''s damage, Doctor Strange and nearby allies gain Bonus Health', '[{"label":"Key","value":"E"},{"label":"Cooldown","value":"6s"},{"label":"Damage","value":"Each point of energy deals 1.3 damage."},{"label":"Range","value":"8m spherical radius spell field"},{"label":"Self Bonus Health Conversion","value":"0.3"},{"label":"Ally Bonus Health Conversion","value":"0.2"},{"label":"Bonus Max Health","value":"75"},{"label":"Special Effect","value":"The spell field pulls enemies in range toward Doctor Strange"}]'::jsonb, 8),
  (36794, 'doctor-strange', null, null, 'GAMMA MAELSTROM', 'Team-Up Ability', 'Base Effect: Upgrade Maelstrom of Madness to Gamma Maelstrom. This drastically boosts energy charge rates and removes the Anti-Heal curse. Enhanced Effect: When teaming up with Hulk, releasing Gamma Maelstrom retains some energy, and stored Gamma energy doesn''t decay over time.', '[{"label":"Key","value":"E"},{"label":"Damage","value":"Each point of Dark Magic deals 1.3 damage."},{"label":"Range","value":"10m spherical radius spell field"},{"label":"Cooldown","value":"6s"},{"label":"Minimum Energy","value":"50"}]'::jsonb, 9),
  (36795, 'doctor-strange', null, null, 'PSIONIC VORTEX', 'Team-Up Ability', 'Base Effect: Upgrade Maelstrom of Madness to Psionic Vortex. Enemies caught in are Launched toward you. Shield of the Seraphim also gains increased shield value. Enhanced Effect: When teaming up with Invisible Woman, any damage dealt by Psionic Vortex provides proportional Bonus Health for Doctor Strange.', '[{"label":"Key","value":"E"},{"label":"Damage","value":"Each point of Dark Magic deals 1.3 damage."},{"label":"Range","value":"8m spherical radius spell field"},{"label":"Cooldown","value":"6s"},{"label":"Shield Of The Seraphim Health Boost","value":"150"},{"label":"Special Effect","value":"The spell field pulls enemies within range toward itself"},{"label":"Bonus Health (Self)","value":"0.5"},{"label":"Ally Bonus Health Conversion Factor","value":"0.3"},{"label":"Max Bonus Health","value":"150"}]'::jsonb, 10)
on conflict do nothing;

